-- ----------------------------
-- Table structure for dis_file_process_node
-- ----------------------------
DROP TABLE IF EXISTS `dis_file_process_node`;
CREATE TABLE `dis_file_process_node`  (
  `f_pnode_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '流程节点ID',
  `file_id` int(11) NOT NULL COMMENT '上报文件ID',
  `process_id` int(11) NULL DEFAULT NULL COMMENT '流程ID',
  `node_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '节点编号',
  `f_pnode_sn` int(11) NOT NULL DEFAULT 1 COMMENT '处理顺序序号，从1开始',
  `f_pnode_retry_times` int(11) NOT NULL DEFAULT 0 COMMENT '失败重试次数',
  `f_pnode_start` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始处理时间',
  `f_pnode_stop` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '完成处理时间',
  `f_pnode_times` int(11) NOT NULL COMMENT '实际处理次数',
  `f_pnode_state` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '当前状态码',
  `f_pnode_created` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `f_pnode_updated` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `f_pnode_reset_flag` int(11) NULL DEFAULT 0 COMMENT '重置状态标识',
  PRIMARY KEY (`f_pnode_id`) USING BTREE,
  INDEX `file_id`(`file_id`, `node_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '文件处理流程节点表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exec_shell_task
-- ----------------------------
DROP TABLE IF EXISTS `exec_shell_task`;
CREATE TABLE `exec_shell_task`  (
  `id` varchar(40) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL COMMENT '主键',
  `task_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '任务名称',
  `shell_path` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '执行shell路径',
  `shell_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '执行shell名称',
  `shell_param` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '执行shell参数（多个参数时，参数之间使用@符号隔开）',
  `cron_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '任务执行周期编号',
  `status` varchar(3) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '任务执行状态(0:未执行,1:正在执行,200:执行成功,500:执行失败)',
  `create_time` char(19) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '创建时间',
  `create_user` varchar(128) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '创建用户',
  `update_time` char(19) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '修改时间',
  `update_user` varchar(128) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '修改用户',
  `task_type` varchar(2) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_bin COMMENT = '执行shell任务表' ROW_FORMAT = Dynamic;

