  `BATCH_DATE` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '跑批日期',
  `AREA_NO` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '上报地区',
  `DATA_DATE` char(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据日期，账期',
  `ORG_NO` varchar(53) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '上报机构/上报用户',
  `ROWS_ID` int(11) NULL DEFAULT NULL COMMENT '行号',
  `ORG_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '地区名称',
  `LOAN_BALANCE_SUM` decimal(30, 5) NULL DEFAULT NULL COMMENT '余额(合计)',
  `LOAN_BAL_REAL_ESTATE` decimal(30, 5) NULL DEFAULT NULL COMMENT '一、房地产开发贷款 ',
  `LOAN_BAL_LAND` decimal(30, 5) NULL DEFAULT NULL COMMENT '1．地产开发贷款 ',
  `LOAN_BAL_GOV_RESVER` decimal(30, 5) NULL DEFAULT NULL COMMENT '其中：政府土地储备机构贷款 ',
  `LOAN_BAL_DEV_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '2．房产开发贷款 ',
  `LOAN_BAL_LIVE_DEV_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '(1)住房开发贷款 ',
  `LOAN_BAL_SECU_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '其中：保障性住房开发贷款 ',
  `LOAN_BAL_COMC_DEV_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '(2)商业用房开发贷款 ',
  `LOAN_BAL_OTHER_DEV_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '(3)其他房产开发贷款 ',
  `LOAN_BAL_PURCH_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '二、购房贷款 ',
  `LOAN_BAL_ENTER_PURCH_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '1．企业购房贷款 ',
  `LOAN_BAL_COMMC_USE_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '(1)商业用房贷款 ',
  `LOAN_BAL_LIVE_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '(2)住房贷款 ',
  `LOAN_BAL_TEAM_PURCH_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '2.机关团体购房贷款 ',
  `LOAN_BAL_TEAM_COMMC_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '(1)机关团体商业用房贷款 ',
  `LOAN_BAL_TEAM_LIVE_HOUS` decimal(30, 5) NULL DEFAULT NULL COMMENT '(2)机关团体住房贷款 ',
  `LOAN_BAL_PERSON` decimal(30, 5) NULL DEFAULT NULL COMMENT '3．个人购房贷款 ',
  `LOAN_BAL_COMMC_PERSON` decimal(30, 5) NULL DEFAULT NULL COMMENT '(1)个人商业用房贷款 ',
  `LOAN_BAL_LIVE_PERSON` decimal(30, 5) NULL DEFAULT NULL COMMENT '(2)个人住房贷款 ',
  `LOAN_BAL_DEV_NEW` decimal(30, 5) NULL DEFAULT NULL COMMENT '1)新建房贷款 ',
  `LOAN_BAL_MORTGAGE` decimal(30, 5) NULL DEFAULT NULL COMMENT '其中：抵押贷款 ',
  `LOAN_BAL_RETRANS` decimal(30, 5) NULL DEFAULT NULL COMMENT '2)再交易房贷款',
  `LOAN_BAL_STOCK` decimal(30, 5) NULL DEFAULT NULL COMMENT '三、证券化的房地产贷款 ',
  `LOAN_BAL_STOCK_PERSON` decimal(30, 5) NULL DEFAULT NULL COMMENT '1．证券化个人住房贷款 ',
  `LOAN_BAL_STOCK_OTHER` decimal(30, 5) NULL DEFAULT NULL COMMENT '2．其他证券化房地产贷款 ',
  `LOAN_BAL_LOWER_INCOME` decimal(30, 5) NULL DEFAULT NULL COMMENT '附：个人购买保障性住房贷款 ',
  `LOAN_BAL_MERGE_PLAN` decimal(30, 5) NULL DEFAULT NULL COMMENT '附：企业收购、租赁保障性住房贷款 ',
  `LOAN_BAL_TERM_MERGE_PLAN` decimal(30, 5) NULL DEFAULT NULL COMMENT '附：机关团体收购、租赁保障性住房贷款 ',
  `LOAN_BAL_MAIN_PERSON` decimal(30, 5) NULL DEFAULT NULL COMMENT '主报个人住房贷款 ',
  `LOAN_BAL_DEV_ESTA_HB` decimal(30, 5) NULL DEFAULT NULL COMMENT '房地产开发贷款比上月'
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '表3-2 重庆市金融机构(含外资)房地产贷款投向统计分地区表(人民币)' ROW_FORMAT = Dynamic;

