  `DATA_DATE` char(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据日期，账期',
  `ORG_NO` varchar(53) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '上报机构/上报用户',
  `ROWS_ID` int(11) NULL DEFAULT NULL COMMENT '行号',
