  `LOAN_BAL_SUB_P` decimal(30, 5) NULL DEFAULT NULL COMMENT '余额比上月增减(贷款)',
  `LOAN_BAL_TB` decimal(30, 5) NULL DEFAULT NULL COMMENT '余额同比(贷款)'
