-- ----------------------------
-- Table structure for rpt_m_loan_sum_proj
-- ----------------------------
DROP TABLE IF EXISTS `rpt_m_loan_sum_proj`;
CREATE TABLE `rpt_m_loan_sum_proj`  (
  `BATCH_DATE` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '跑批日期',
  `AREA_NO` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '上报地区',
  `DATA_DATE` char(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据日期，账期',
  `ORG_NO` varchar(53) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '上报机构/上报用户',
  `PROJECT` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '项目信息',
  `ROWS_ID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行号',
  `LOAN_BAL` decimal(30, 5) NULL DEFAULT NULL COMMENT '本期余额',
  `LOAN_BAL_ADD_NEW` decimal(30, 5) NULL DEFAULT NULL COMMENT '当年新增',
  `LOAN_BAL_TB` decimal(30, 5) NULL DEFAULT NULL COMMENT '余额同比增长',
  `LOAN_BAL_Y` decimal(30, 5) NULL DEFAULT NULL COMMENT '当年累计发放',
  `LOAN_BAL_TB_Y` decimal(30, 5) NULL DEFAULT NULL COMMENT '当年累计发放同比增长',
  `LOAN_COUNT` decimal(30, 5) NULL DEFAULT NULL COMMENT '贷款笔数',
  `PEOPLE_COUNT` decimal(30, 5) NULL DEFAULT NULL COMMENT '带动服务贫困人口数',
  `LOAN_WBAL` decimal(30, 5) NULL DEFAULT NULL COMMENT '贷款加权平均利率',
  `LOAN_FUND` decimal(30, 5) NULL DEFAULT NULL COMMENT '使用央行资金'
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '表3-8 重庆市金融精准扶贫贷款汇总表（分项目）' ROW_FORMAT = Dynamic;

