  `F_FGR_FM_RES` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '流动性情况-流动性缺口率',
  `F_CORE_DEBT` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '流动性情况-核心负债',
