  `F_RERR_FM` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '流动性情况-人民币超额备付金率-分母',
  `F_RERR_FM_RES` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '流动性情况-人民币超额备付金率',
