  `Y2504` decimal(28, 8) NULL DEFAULT NULL COMMENT '存续余额',
  `Y2708` decimal(28, 8) NULL DEFAULT NULL COMMENT '转让价格比率',
  `Y3102` decimal(28, 8) NULL DEFAULT NULL COMMENT '风险准备金',
  `Y3104` int(11) NULL DEFAULT NULL COMMENT '逾期天数'
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

