  `TABLE_ID` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '表编号',
  `COLUMN_NAME` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '列名称',
  `COLUMN_TYPE` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '列类型',
  `COLUMN_LENGTH` int(11) NULL DEFAULT NULL COMMENT '列长度',
  `COLUMN_PRECISION` int(11) NULL DEFAULT 0 COMMENT '列精度',
  `CELL` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Excel单元格',
  `CELL_TYPE` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Excel单元格类型',
  `READER_RULE` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '读取规则',
  `IN_DTL` int(11) NULL DEFAULT NULL COMMENT '包含在DTL中',
  `IS_NOT_NULL` int(11) NULL DEFAULT NULL COMMENT '是否必填',
  `COLUMN_DESC` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '列描述',
  `IS_LOOP` int(11) NULL DEFAULT NULL COMMENT '是否循环单元格',
  `ADD_DATE` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '临时头表' ROW_FORMAT = Dynamic;

