  `TEMPLATE_TYPE_DESC` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '类别名称',
  `ADD_DATE` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '模版类别' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for t_sys_template_verify
-- ----------------------------
DROP TABLE IF EXISTS `t_sys_template_verify`;
CREATE TABLE `t_sys_template_verify`  (
  `VERIFY_ID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '校验编码',
  `VERIFY_NAME` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '校验名称',
  `TEMPLATE_ID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '模版编码',
  `VERIFY_RULE` varchar(10000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `VERIFY_TYPE` int(11) NULL DEFAULT NULL COMMENT '校验类型（1硬/0软）',
  `VERIIFY_FORM` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '校验类别（F计算/E正则/W对比/S sql语句返回记录数大于0校验不通过）',
  `IS_APP_VERIFY` int(11) NULL DEFAULT NULL COMMENT '是否程序校验 1程序、2过程',
  `IS_VALID` int(11) NULL DEFAULT 1 COMMENT '是否有效 1有效、0无效',
  `SQLTXT` varchar(10000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'sql脚本 是否程序校验为2时使用',
  `MSG` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '提示信息',
  `ADD_DATE` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `IF_SHOW` int(11) NULL DEFAULT 1 COMMENT '0 对内部 1 对机构有效'
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '模版校验' ROW_FORMAT = Dynamic;

