  `S_PAYEEACCTNAME` varchar(120) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人名称',
  `S_PAYEEOPNBNKNO` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人开户行行号',
  `S_PAYEEOPNBNKNAME` varchar(120) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人开户行名称',
  `S_CLEARACCTNO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算账户账号',
  `S_CLEARACCTNAME` varchar(120) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算账户名称',
  `S_CLEARBANKNO` char(12) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算账户开户行行号',
  `S_CLEARBANKNAME` varchar(120) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算账户开户行名称',
  `S_REMARK` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '摘要: 0-审核成功,1-超出预算计划,2-关注账户提示未通过,3-资金支付文件依据不足,4-收款账户不符合规定,5-其他原因,91-报文解析错误,92-审核签名错误,93-其他错误',
  `F_PAYAMT` decimal(15, 2) NULL DEFAULT NULL COMMENT '支付金额',
  `C_AUTOAUDITSTATE` char(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '自动审核状态',
  `T_AUTOAUDITTIME` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '自动审核时间',
  `S_AUDITREASON` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核不通过原因',
  `C_HANDAUDITSTATE` char(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '人工确认状态',
  `T_HANDAUDITTIME` varchar(40) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '人工确认时间',
  `S_HANDREASON` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '人工确认原因',
  `C_HANDAUDITFLAG` char(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '人工确认标志',
  `C_ISDEDPLAN` char(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '是否扣减计划',
  `C_CHECKRESULT` char(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对账结果',
  `S_HOLD1` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `S_HOLD2` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `S_HOLD3` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留字段3',
  `S_HOLD4` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留字段4',
  `TS_SYSUPDATE` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '系统更新时间',
  `id` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`S_ENTRUSTDATE`) USING BTREE,
  INDEX `guoku`(`S_TRECODE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9350217 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代理银行发起集中支付明细表' ROW_FORMAT = Dynamic;

