-- ----------------------------
-- View structure for sust_enterprise_view
-- ----------------------------
DROP VIEW IF EXISTS `sust_enterprise_view`;
CREATE ALGORITHM = UNDEFINED DEFINER = `dis`@`%` SQL SECURITY DEFINER VIEW `sust_enterprise_view` AS select distinct `ana_sust_mth_enterprise_survey_temp`.`ENTERPRISE_id` AS `ENTERPRISE_ID`,`ana_sust_mth_enterprise_survey_temp`.`ENTERPRISE_name` AS `ENTERPRISE_name` from `ana_sust_mth_enterprise_survey_temp` where (`ana_sust_mth_enterprise_survey_temp`.`data_date` = 202607);

-- ----------------------------
-- View structure for sust_standard_norm_view
-- ----------------------------
DROP VIEW IF EXISTS `sust_standard_norm_view`;
CREATE ALGORITHM = UNDEFINED DEFINER = `dis`@`%` SQL SECURITY DEFINER VIEW `sust_standard_norm_view` AS select `sust_standard_norm`.`NORM_ID` AS `NORM_ID`,`sust_standard_norm`.`NORM_NAME` AS `NORM_NAME` from `sust_standard_norm` order by `sust_standard_norm`.`ID`;

-- ----------------------------
-- Procedure structure for ana_cx_mth_cash_servinfo
-- ----------------------------
DROP PROCEDURE IF EXISTS `ana_cx_mth_cash_servinfo`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `ana_cx_mth_cash_servinfo`(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
BEGIN
    

    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'adm.ana_cx_mth_cash_servinfo.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_RESULT        INT           DEFAULT 0;
    DECLARE V_DATES         VARCHAR(20)   DEFAULT 0;
    DECLARE V_STATE CHAR(1);
    
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_DATES = V_ACCT_ID;
    
    SET V_STEP_ID = 1;
    DELETE FROM adm.ana_cx_mth_cash_servinfo WHERE MONTH = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   SET V_STEP_ID = 2;
 
INSERT INTO ana_cx_mth_cash_servinfo(
DATA_DATE,	
MONTH,	        
CITY_CODE,	
CITY_NAME,	
COUNTY_CODE,	
COUNTY_NAME,	
TRADE_ACTIVE,	
TRADE_INEFFICT,	
TRADE_ACTIVE_LM	,	
TRADE_INEFFICT_LM,	
TRADE_ACTIVE_LY,	
TRADE_INEFFICT_LY,	
TRADE_NUM
)
SELECT 
  DATE_FORMAT( CONCAT(a.trade_date, '01'), '%Y-%m-%d' ),
  a.trade_date,
  a.CITY_CODE,
  a.CITY_NAME,
  a.area_code,
  a.area_name,
  a.TRADE_ACTIVE,
  a.TRADE_INEFFICT,
  IFNULL(b.TRADE_ACTIVE, 0),
  IFNULL(c.TRADE_ACTIVE, 0),
  IFNULL(b.TRADE_INEFFICT, 0),
  IFNULL(c.TRADE_INEFFICT, 0),
  d.serv_no 
FROM
  adm.ana_cx_mth_cash_servinfo_tmp a 
  LEFT JOIN adm.ana_cx_mth_cash_servinfo_tmp b 
    ON a.area_code = b.area_code 
    AND DATE_FORMAT( DATE_SUB(CONCAT(a.trade_date, '01'),INTERVAL 1 MONTH), '%Y%m' ) = b.trade_date
  LEFT JOIN adm.ana_cx_mth_cash_servinfo_tmp c 
    ON a.area_code = c.area_code 
    AND DATE_FORMAT( DATE_SUB( CONCAT(a.trade_date, '01'),INTERVAL 12 MONTH),  '%Y%m') = c.trade_date 
  LEFT JOIN 
    (SELECT  COUNT(DISTINCT shop_num) AS serv_no,
      c.area_code,
      c.area_name 
    FROM   edw.py_cx_cash_servinfo b 
      INNER JOIN edw.py_cx_area_code c 
        ON b.village_code = c.nbh_code 
    WHERE b.state = '正常' 
    GROUP BY c.area_code,
      c.area_name) d 
    ON a.area_code = d.area_code 
      WHERE   a.trade_date = SUBSTR(V_ACCT_ID, 1, 6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
  
  
INSERT INTO adm.ana_cx_mth_cash_servinfo(
DATA_DATE,	
MONTH,	        
CITY_CODE,	
CITY_NAME,	
COUNTY_CODE,	
COUNTY_NAME,	
TRADE_ACTIVE,	
TRADE_INEFFICT,	
TRADE_ACTIVE_LM	,	
TRADE_INEFFICT_LM,	
TRADE_ACTIVE_LY,	
TRADE_INEFFICT_LY,	
TRADE_NUM
)
select DATA_DATE,	
MONTH,	        
(SELECT DISTINCT zone_code FROM edw.`py_cx_area_code`),	
(SELECT DISTINCT zone_name FROM edw.`py_cx_area_code`),	
CITY_CODE,	
CITY_NAME,	
sum(TRADE_ACTIVE),	
SUM(TRADE_INEFFICT),	
SUM(TRADE_ACTIVE_LM)	,	
SUM(TRADE_INEFFICT_LM),	
SUM(TRADE_ACTIVE_LY),	
SUM(TRADE_INEFFICT_LY),	
SUM(TRADE_NUM)
from adm.ana_cx_mth_cash_servinfo
  where DATA_DATE=SUBSTR(V_ACCT_ID, 1, 6)
  group by DATA_DATE,MONTH,CITY_CODE, CITY_NAME ;
      CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    SET V_STEP_ID = 3;
    DELETE FROM adm.ana_cx_mth_cash_servinfo_map WHERE MONTH = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
        SET V_STEP_ID = 4;
  
INSERT INTO adm.`ana_cx_mth_cash_servinfo_map`
(DATA_DATE, 
 MONTH, 
 AREA_CODE, 
 AREA_NAME, 
 AREA_ISO_ID, 
 TRADE_ACTIVE, 
 TRADE_INEFFICT 
)
SELECT DATE_FORMAT(CONCAT(a.trade_date,'01'),'%Y-%m-%d'),a.trade_date,
area_code,area_name,area_code,TRADE_ACTIVE,TRADE_INEFFICT
 FROM adm.ana_cx_mth_cash_servinfo_tmp a WHERE a.trade_date = SUBSTR(V_ACCT_ID, 1, 6) 
UNION ALL
SELECT DATE_FORMAT(CONCAT(a.trade_date,'01'),'%Y-%m-%d'),a.trade_date,
city_code,city_name,SUBSTR(city_code,1,4),SUM(TRADE_ACTIVE),SUM(TRADE_INEFFICT)
FROM  adm.ana_cx_mth_cash_servinfo_tmp a  WHERE a.trade_date = SUBSTR(V_ACCT_ID, 1, 6)
GROUP BY trade_date,city_code,city_name,SUBSTR(city_code,1,4) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
   
   
      DELETE FROM  adm.py_cx_menu_zt  WHERE  url_type ='MONTH' AND url_pro='RPY';  
    
     INSERT INTO  adm.py_cx_menu_zt
  SELECT menu_id,CONCAT(SUBSTR(a.url,1,LENGTH(SUBSTRING_INDEX(a.url,'MONTH',1))+41),
 (SELECT MAX(QUARTER) FROM adm.ana_cx_qtr_non_cash_pay),
 SUBSTR(a.url,LENGTH(SUBSTRING_INDEX(a.url,'MONTH',1))+48,10000)) ,'MONTH','RPY'
  FROM  dps.t_sc_menu a 
  WHERE  SUBSTR(a.url,-3) ='RPY' AND a.url LIKE '%MONTH%' ;
  
  UPDATE dps.t_sc_menu a  
  SET a.url= (SELECT b.url FROM adm.py_cx_menu_zt b WHERE a.menu_id=b.menu_id)
  WHERE SUBSTR(a.url,-3) ='RPY' AND a.url LIKE '%MONTH%' ;   		
  
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ana_cx_qtr_accts
-- ----------------------------
DROP PROCEDURE IF EXISTS `ana_cx_qtr_accts`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `ana_cx_qtr_accts`(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 宋楠
     Name      : adm.ana_cx_qtr_accts.PRC
     Functions : 
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'adm.ana_cx_qtr_accts.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_RESULT        INT           DEFAULT 0;
    DECLARE V_DATES         VARCHAR(20)   DEFAULT 0;
    DECLARE V_STATE CHAR(1);
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_AREA_ID,V_ORG_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_DATES = CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
    SET V_STEP_ID = 1;
    DELETE FROM adm.ana_cx_qtr_accts WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    
   SET V_STEP_ID = 2;
  -- 取非支付现金业务 当期数据
INSERT INTO adm.`ana_cx_qtr_accts`
SELECT 
a.DATA_DATE,
a.QUARTER,
a.CITY_CODE,
a.CITY_NAME,
a.COUNTY_CODE,
a.COUNTY_NAME,
a.AREA_TYPE_CODE,
a.TYPE1,
a.TYPE2,
SUM(a.UNIT_BACK)
FROM 
(SELECT 
DATE_FORMAT(CONCAT(t.DATA_DATE,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.DATA_DATE AS QUARTER,           
CASE WHEN t.AREA_ID LIKE '%4401%' THEN '440100' ELSE t.AREA_ID END AS CITY_CODE,    
CASE WHEN t.AREA_NAME LIKE '%区%' THEN '广州市' ELSE t.AREA_NAME END AS CITY_NAME,   
'' AS COUNTY_CODE,
'' AS COUNTY_NAME, 
CASE WHEN t.AREA_TYPE_CODE='1' THEN '农村'
      WHEN t.AREA_TYPE_CODE='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'单位银行结算账户' AS TYPE1,
'单位银行结算账户' AS TYPE2,
t.UNIT_BACK AS UNIT_BACK
FROM  edw.`py_cx_envbld_rural_bnk_accts` t
WHERE t.data_date=SUBSTR(V_ACCT_ID,1,6)
 UNION ALL
 
SELECT 
DATE_FORMAT(CONCAT(t.DATA_DATE,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.DATA_DATE AS QUARTER,           
CASE WHEN t.AREA_ID LIKE '%4401%' THEN '440100' ELSE t.AREA_ID END AS CITY_CODE,    
CASE WHEN t.AREA_NAME LIKE '%区%' THEN '广州市' ELSE t.AREA_NAME END AS CITY_NAME,     
'' AS COUNTY_CODE,
'' AS COUNTY_NAME, 
CASE WHEN t.AREA_TYPE_CODE='1' THEN '农村'
      WHEN t.AREA_TYPE_CODE='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'个人银行结算账户' AS TYPE1,
'I类账户' AS TYPE2,    
t.PERSONAL_BANK_1*10000
FROM  edw.`py_cx_envbld_rural_bnk_accts` t  
   WHERE t.data_date=SUBSTR(V_ACCT_ID,1,6)
   
UNION ALL
 
SELECT 
DATE_FORMAT(CONCAT(t.DATA_DATE,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.DATA_DATE AS QUARTER,           
CASE WHEN t.AREA_ID LIKE '%4401%' THEN '440100' ELSE t.AREA_ID END AS CITY_CODE,    
CASE WHEN t.AREA_NAME LIKE '%区%' THEN '广州市' ELSE t.AREA_NAME END AS CITY_NAME,     
'' AS COUNTY_CODE,
'' AS COUNTY_NAME, 
CASE WHEN t.AREA_TYPE_CODE='1' THEN '农村'
      WHEN t.AREA_TYPE_CODE='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'个人银行结算账户' AS TYPE1,
'II类账户' AS TYPE2,    
t.PERSONAL_BANK_2*10000  
FROM  edw.`py_cx_envbld_rural_bnk_accts` t    
 WHERE t.data_date=SUBSTR(V_ACCT_ID,1,6)
 
UNION ALL
 
SELECT 
DATE_FORMAT(CONCAT(t.DATA_DATE,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.DATA_DATE AS QUARTER,           
CASE WHEN t.AREA_ID LIKE '%4401%' THEN '440100' ELSE t.AREA_ID END AS CITY_CODE,    
CASE WHEN t.AREA_NAME LIKE '%区%' THEN '广州市' ELSE t.AREA_NAME END AS CITY_NAME,    
'' AS COUNTY_CODE,
'' AS COUNTY_NAME, 
CASE WHEN t.AREA_TYPE_CODE='1' THEN '农村'
      WHEN t.AREA_TYPE_CODE='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'个人银行结算账户' AS TYPE1,
'III类账户' AS TYPE2,    
t.PERSONAL_BANK_3*10000  
FROM  edw.py_cx_envbld_rural_bnk_accts t
WHERE t.data_date=SUBSTR(V_ACCT_ID,1,6)) a
GROUP BY a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6),
a.QUARTER,
a.CITY_CODE,
a.CITY_NAME,
a.COUNTY_CODE,
a.COUNTY_NAME,
a.AREA_TYPE_CODE,
a.TYPE1,
a.TYPE2;  
 
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ana_cx_qtr_bank_card
-- ----------------------------
DROP PROCEDURE IF EXISTS `ana_cx_qtr_bank_card`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `ana_cx_qtr_bank_card`(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.ana_cx_qtr_bank_card.PRC
     Functions : 交易偏好-银行卡受理市场建设情况
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'adm.ana_cx_qtr_bank_card.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_RESULT        INT           DEFAULT 0;
    DECLARE V_DATES         VARCHAR(20)   DEFAULT 0;
    DECLARE V_STATE CHAR(1);
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_AREA_ID,V_ORG_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_DATES = CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
    SET V_STEP_ID = 1;
    DELETE FROM adm.ana_cx_qtr_bank_dq_card WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   SET V_STEP_ID = 2;
  -- 银行卡受理市场建设情况 当期数据
INSERT INTO adm.ana_cx_qtr_bank_dq_card 
SELECT
DATA_DATE,      
QUARTER,        
CITY_CODE,      
CITY_NAME,      
COUNTY_CODE,    
COUNTY_NAME,    
AREA_TYPE_CODE, 
BCARD_TYPE_DSCR,
SUM(NUMBER),         
SUM(COUNT),          
SUM(MONEY)            
FROM
(SELECT 
  DATE_FORMAT(V_DATES, '%Y-%m-%d') AS data_date,
  data_date AS QUARTER,
CASE WHEN AREA_ID LIKE '%4401%' THEN '440100' ELSE AREA_ID END AS CITY_CODE,    
CASE WHEN AREA_NAME LIKE '%区%' THEN '广州市' ELSE AREA_NAME END AS CITY_NAME,   
'' AS COUNTY_CODE,
'' AS COUNTY_NAME, 
  CASE
    WHEN AREA_TYPE_CODE = '1' 
    THEN '农村' 
    ELSE '贫困' 
  END AS AREA_TYPE_CODE,
  CASE
    BCARD_TYPE_DSCR 
    WHEN '04' 
    THEN 'ATM' 
    WHEN '05' 
    THEN 'POS' 
    WHEN '06' 
    THEN '其他银行卡受理终端' 
  END AS BCARD_TYPE_DSCR,
  NUMBER,
  COUNT,
  MONEY 
FROM
  edw.py_cx_envbld_rural_cards_mkt 
WHERE data_date = SUBSTR(V_ACCT_ID, 1, 6) 
  AND BCARD_TYPE_DSCR IN ('04', '05', '06') 
  AND area_id != '' ) m
  GROUP BY DATA_DATE,      
QUARTER,        
CITY_CODE,      
CITY_NAME,      
COUNTY_CODE,    
COUNTY_NAME,    
AREA_TYPE_CODE, 
BCARD_TYPE_DSCR ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
     DELETE FROM adm.ana_cx_qtr_bank_card WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
  -- 取银行卡受理市场建设情况 同比
  INSERT INTO adm.ana_cx_qtr_bank_card 
SELECT 
  a.DATA_DATE,
  -- 账期
  a.QUARTER,
  -- 季度
  a.CITY_CODE,
  -- 地市编码
  a.CITY_NAME,
  -- 地市名称
  a.COUNTY_CODE,
  -- 区县编码
  a.COUNTY_NAME,
  -- 区县名称
  a.AREA_TYPE_CODE,
  -- 农村贫困地区标准
  a.BUSINESS_DSCR_2,
  -- 业务量描述/支付类型
  a.NUMBER,
  a.COUNT,
  b.COUNT,
  a.MONEY,
  b.MONEY 
FROM
  adm.ana_cx_qtr_bank_dq_card a 
  LEFT JOIN 
    (SELECT 
      * 
    FROM
      adm.ana_cx_qtr_bank_dq_card 
    WHERE QUARTER = DATE_FORMAT(
        DATE_SUB(V_DATES, INTERVAL 12 MONTH),
        '%Y%m'
      )) b 
    ON a.city_code = b.city_code 
    AND a.area_type_code = b.area_type_code 
    AND a.BUSINESS_DSCR_2 = b.BUSINESS_DSCR_2 
WHERE a.QUARTER = SUBSTR(V_ACCT_ID, 1, 6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
    
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ana_cx_qtr_bank_cards
-- ----------------------------
DROP PROCEDURE IF EXISTS `ana_cx_qtr_bank_cards`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `ana_cx_qtr_bank_cards`(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 宋楠
     Name      : adm.ana_cx_qtr_bank_cards.PRC
     Functions : 
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'adm.ana_cx_qtr_bank_cards.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_RESULT        INT           DEFAULT 0;
    DECLARE V_DATES         VARCHAR(20)   DEFAULT 0;
    DECLARE V_STATE CHAR(1);
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
       CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_DATES = V_ACCT_ID;
    /* ------------------------------------------------------------------------ */
    SET V_STEP_ID = 1;
    DELETE FROM adm.ana_cx_qtr_bank_cards WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    
   SET V_STEP_ID = 2;
  -- 取非支付现金业务 当期数据 市-市
INSERT INTO adm.`ana_cx_qtr_bank_cards`
SELECT 
DATA_DATE,
QUARTER,
d.AREA_NO_ID_2 AS CITY_CODE,     
d.AREA_DSCR_2 AS CITY_NAME,
COUNTY_CODE,
COUNTY_NAME,
AREA_TYPE_CODE,
TYPE,
SUM(CARD)
FROM 
(SELECT 
DATE_FORMAT(CONCAT(t.DATA_DATE,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.DATA_DATE AS QUARTER,           
t.AREA_ID  AS CITY_CODE,    
t.AREA_NAME  AS CITY_NAME,   
t.AREA_ID AS COUNTY_CODE,
t.AREA_NAME AS COUNTY_NAME, 
CASE WHEN t.AREA_TYPE_CODE='1' THEN '农村'
      WHEN t.AREA_TYPE_CODE='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'借记卡' AS TYPE,
t.DEBIT_CARD AS CARD
FROM  edw.`py_cx_envbld_rural_bnk_cards` t
 WHERE t.DATA_DATE = SUBSTR(V_ACCT_ID,1,6)
 UNION ALL
 
SELECT 
DATE_FORMAT(CONCAT(t.DATA_DATE,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.DATA_DATE AS QUARTER,           
t.AREA_ID  AS CITY_CODE,    
t.AREA_NAME  AS CITY_NAME,   
t.AREA_ID AS COUNTY_CODE,
t.AREA_NAME AS COUNTY_NAME,
CASE WHEN t.AREA_TYPE_CODE='1' THEN '农村'
      WHEN t.AREA_TYPE_CODE='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'信用卡' AS TYPE,    
t.CREDIT_CARD AS CARD
FROM  edw.`py_cx_envbld_rural_bnk_cards` t  
    WHERE t.DATA_DATE = SUBSTR(V_ACCT_ID,1,6)
UNION ALL
 
SELECT 
DATE_FORMAT(CONCAT(t.DATA_DATE,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.DATA_DATE AS QUARTER,           
t.AREA_ID  AS CITY_CODE,    
t.AREA_NAME  AS CITY_NAME,   
t.AREA_ID AS COUNTY_CODE,
t.AREA_NAME AS COUNTY_NAME,
CASE WHEN t.AREA_TYPE_CODE='1' THEN '农村'
      WHEN t.AREA_TYPE_CODE='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'借贷合一卡' AS TYPE,    
t.DEBIT_CREDIT AS CARD
FROM  edw.`py_cx_envbld_rural_bnk_cards` t 
 WHERE t.DATA_DATE = SUBSTR(V_ACCT_ID,1,6)) t 
      LEFT JOIN dmcode.t_area_code d
  ON t.COUNTY_CODE=d.AREA_NO_ID   
GROUP BY DATA_DATE,
QUARTER,
CITY_CODE,
CITY_NAME,
COUNTY_CODE,
COUNTY_NAME,
AREA_TYPE_CODE,
TYPE;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
   
   -- 取非支付现金业务 当期数据 省-市
INSERT INTO adm.`ana_cx_qtr_bank_cards`
SELECT 
DATA_DATE,
QUARTER,
CITY_CODE,
CITY_NAME,
d.AREA_NO_ID_2 ,     
d.AREA_DSCR_2 ,
AREA_TYPE_CODE,
TYPE,
SUM(CARD)
FROM 
(SELECT 
DATE_FORMAT(CONCAT(t.DATA_DATE,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.DATA_DATE AS QUARTER,           
(SELECT DISTINCT zone_code FROM edw.`py_cx_area_code`)  AS CITY_CODE,    
(SELECT DISTINCT zone_name FROM edw.`py_cx_area_code`)  AS CITY_NAME,   
t.AREA_ID AS COUNTY_CODE,
t.AREA_NAME AS COUNTY_NAME, 
CASE WHEN t.AREA_TYPE_CODE='1' THEN '农村'
      WHEN t.AREA_TYPE_CODE='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'借记卡' AS TYPE,
t.DEBIT_CARD AS CARD
FROM  edw.`py_cx_envbld_rural_bnk_cards` t
 WHERE t.DATA_DATE = SUBSTR(V_ACCT_ID,1,6)
 UNION ALL
 
SELECT 
DATE_FORMAT(CONCAT(t.DATA_DATE,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.DATA_DATE AS QUARTER,           
(SELECT DISTINCT zone_code FROM edw.`py_cx_area_code`)  AS CITY_CODE,    
(SELECT DISTINCT zone_name FROM edw.`py_cx_area_code`)  AS CITY_NAME,    
t.AREA_ID AS COUNTY_CODE,
t.AREA_NAME AS COUNTY_NAME,
CASE WHEN t.AREA_TYPE_CODE='1' THEN '农村'
      WHEN t.AREA_TYPE_CODE='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'信用卡' AS TYPE,    
t.CREDIT_CARD AS CARD
FROM  edw.`py_cx_envbld_rural_bnk_cards` t  
    WHERE t.DATA_DATE = SUBSTR(V_ACCT_ID,1,6)
UNION ALL
 
SELECT 
DATE_FORMAT(CONCAT(t.DATA_DATE,'01'), '%Y-%m-%d') AS DATA_DATE,      
t.DATA_DATE AS QUARTER,           
(SELECT DISTINCT zone_code FROM edw.`py_cx_area_code`)  AS CITY_CODE,    
(SELECT DISTINCT zone_name FROM edw.`py_cx_area_code`)  AS CITY_NAME,    
t.AREA_ID AS COUNTY_CODE,
t.AREA_NAME AS COUNTY_NAME,
CASE WHEN t.AREA_TYPE_CODE='1' THEN '农村'
      WHEN t.AREA_TYPE_CODE='2' THEN '贫困' ELSE '' END AS AREA_TYPE_CODE, 
'借贷合一卡' AS TYPE,    
t.DEBIT_CREDIT AS CARD
FROM  edw.`py_cx_envbld_rural_bnk_cards` t 
 WHERE t.DATA_DATE = SUBSTR(V_ACCT_ID,1,6)) t   
       LEFT JOIN dmcode.t_area_code d
  ON t.COUNTY_CODE=d.AREA_NO_ID   
GROUP BY DATA_DATE,
QUARTER,
CITY_CODE,
CITY_NAME,
COUNTY_CODE,
COUNTY_NAME,
AREA_TYPE_CODE,
TYPE;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
     
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ana_cx_qtr_cls
-- ----------------------------
DROP PROCEDURE IF EXISTS `ana_cx_qtr_cls`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `ana_cx_qtr_cls`(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.ana_cx_qtr_cls.PRC
     Functions : 交易偏好-支付清算大小额系统
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'adm.ana_cx_qtr_cls.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_RESULT        INT           DEFAULT 0;
    DECLARE V_DATES         VARCHAR(20)   DEFAULT 0;
    DECLARE V_STATE CHAR(1);
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_DATES = V_ACCT_ID;
    /* ------------------------------------------------------------------------ */
    SET V_STEP_ID = 1;
    DELETE FROM adm.ana_cx_qtr_dq_cls WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- edw汇总到adm，添加地区名称，区分地区类型--插入农村数据
   SET V_STEP_ID = 2;
  -- 取非支付现金业务 当期数据
INSERT INTO adm.ana_cx_qtr_dq_cls 
SELECT
DATA_DATE,     
QUARTER,       
d.AREA_NO_ID_2 AS CITY_CODE,     
d.AREA_DSCR_2 AS CITY_NAME,      
COUNTY_CODE,   
COUNTY_NAME,   
AREA_TYPE_CODE,
SUM(BANK_BRANCH),
SUM(AGENCY_BRANCH),
SUM(COUNT),
SUM(MONEY)
FROM 
(SELECT 
  DATE_FORMAT(CONCAT(data_date,'01'), '%Y-%m-%d') AS DATA_DATE,
  data_date AS QUARTER,
  '' AS CITY_CODE,    
  '' AS CITY_NAME, 
  area_id AS COUNTY_CODE,
  area_name AS COUNTY_NAME,
  CASE
    WHEN AREA_TYPE_CODE = '1' 
    THEN '农村' 
    ELSE '贫困' 
  END AS AREA_TYPE_CODE,
  BANK_BRANCH,
  AGENCY_BRANCH,
  COUNT,
  MONEY 
FROM
  edw.py_cx_envbld_rural_cls) c
    LEFT JOIN dmcode.t_area_code d
  ON c.COUNTY_CODE=d.AREA_NO_ID 
WHERE QUARTER = SUBSTR(V_ACCT_ID, 1, 6) 
GROUP BY DATA_DATE,     
QUARTER,       
CITY_CODE,     
CITY_NAME,     
COUNTY_CODE,   
COUNTY_NAME,   
AREA_TYPE_CODE;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
     DELETE FROM adm.ana_cx_qtr_cls WHERE QUARTER = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
  -- 取非支付现金业务 同比数据 市-市
  INSERT INTO adm.ana_cx_qtr_cls 
SELECT 
  a.DATA_DATE,
  -- 账期
  a.QUARTER,
  -- 季度
  a.CITY_CODE,
  -- 地市编码
  a.CITY_NAME,
  -- 地市名称
  a.COUNTY_CODE,
  -- 区县编码
  a.COUNTY_NAME,
  -- 区县名称
  a.AREA_TYPE_CODE,
  -- 农村贫困地区标准
  a.BANK_BRANCH,
  a.AGENCY_BRANCH,
  a.COUNT,
  b.COUNT,
  a.MONEY,
  b.MONEY 
FROM
  adm.ana_cx_qtr_dq_cls a 
  LEFT JOIN 
    (SELECT 
      * 
    FROM
      adm.ana_cx_qtr_dq_cls 
    WHERE QUARTER = DATE_FORMAT(
        DATE_SUB(V_DATES, INTERVAL 12 MONTH),
        '%Y%m'
      )) b 
    ON a.city_code = b.city_code 
    AND a.area_type_code = b.area_type_code 
WHERE a.QUARTER = SUBSTR(V_DATES, 1, 6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
  -- 取非支付现金业务 同比数据 省-市
  INSERT INTO adm.ana_cx_qtr_cls 
SELECT 
  a.DATA_DATE,
  -- 账期
  a.QUARTER,
  -- 季度
(SELECT DISTINCT zone_code FROM edw.`py_cx_area_code`),
 (SELECT DISTINCT zone_name FROM edw.`py_cx_area_code`),
  a.CITY_CODE,
  -- 区县编码
  a.CITY_NAME,
  -- 区县名称
  a.AREA_TYPE_CODE,
  -- 农村贫困地区标准
  a.BANK_BRANCH,
  a.AGENCY_BRANCH,
  a.COUNT,
  b.COUNT,
  a.MONEY,
  b.MONEY 
FROM
  adm.ana_cx_qtr_dq_cls a 
  LEFT JOIN 
    (SELECT 
      * 
    FROM
      adm.ana_cx_qtr_dq_cls 
    WHERE QUARTER = DATE_FORMAT(
        DATE_SUB(V_DATES, INTERVAL 12 MONTH),
        '%Y%m'
      )) b 
    ON a.city_code = b.city_code 
    AND a.area_type_code = b.area_type_code 
WHERE a.QUARTER = SUBSTR(V_DATES, 1, 6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
       
END
;;
delimiter ;

