PAY_CODE,         
SUM(COUNT),          
SUM(MONEY)            
FROM
(SELECT 
   DATE_FORMAT(CONCAT(SUBSTR(V_ACCT_ID,1,6),'01'), '%Y-%m-%d') AS data_date,  
  data_date AS QUARTER,
AREA_ID AS CITY_CODE,    
AREA_NAME AS CITY_NAME,   
