-- ----------------------------
-- Procedure structure for py_cx_advt_train
-- ----------------------------
DROP PROCEDURE IF EXISTS `py_cx_advt_train`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `py_cx_advt_train`(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.py_cx_advt_train.PRC
     Functions : 表9 农村地区支付结算宣传培训情况
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.py_cx_advt_train.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_RESULT        INT           DEFAULT 0;
    DECLARE V_DATES         VARCHAR(20)   DEFAULT 0;
    DECLARE V_STATE CHAR(1);
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_DATES = CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
    SET V_STEP_ID = 1;
    DELETE FROM edw.py_cx_advt_train WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- ods汇总到edw，添加地区名称，区分地区类型  --插入农村数据
   SET V_STEP_ID = 2; 
  INSERT INTO edw.py_cx_advt_train
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID         , -- 地区代码                
                 AREA_NAME            , -- 地区名称                
                 ORG_ID               , -- 填报单位 
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 PUBL_TIME           , -- 宣传次数
                 PUBL_NUM          , -- 发放宣传品数量     
                 OFF_TIME         , -- 非现场宣传    
                 TRAIN_TIME           , -- 培训次数  
                 TRAIN_NUM,       --  培训人次
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    b.AREA_NAME,
    a.ORG_ID,
    '1',
    a.COUN_PUBL_TIME,
    a.COUN_PUBL_NUM,
    a.COUN_OFF_TIME,
    a.COUN_TRAIN_TIME ,
    a.COUN_TRAIN_NUM,
    a.REMARKS
    FROM ods.py_cx_advt_train  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.AREA_ID=b.AREA_ID 
    WHERE b.AREA_TYPE_CODE='1'  AND a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
   
    -- ods汇总到edw，添加地区名称，区分地区类型  --插入贫困数据
   SET V_STEP_ID = 3; 
  INSERT INTO edw.py_cx_advt_train
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID         , -- 地区代码                
                 AREA_NAME            , -- 地区名称                
                 ORG_ID               , -- 填报单位 
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 PUBL_TIME           , -- 宣传次数
                 PUBL_NUM          , -- 发放宣传品数量     
                 OFF_TIME         , -- 非现场宣传    
                 TRAIN_TIME           , -- 培训次数  
                 TRAIN_NUM,       --  培训人次
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    b.AREA_NAME,
    a.ORG_ID,
    '2',
    a.POVE_PUBL_TIME,
    a.POVE_PUBL_NUM,
    a.POVE_OFF_TIME,
    a.POVE_TRAIN_TIME ,
    a.POVE_TRAIN_NUM,
    a.REMARKS
    FROM ods.py_cx_advt_train  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.AREA_ID=b.AREA_ID 
    WHERE b.AREA_TYPE_CODE='2'  AND a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  SET V_STEP_ID = 4;
    DELETE FROM adm.py_cx_advt_train WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- edw汇总到adm，生成报表展示adm表，同时生成 异动分析结果表
   SET V_STEP_ID = 5;
  INSERT INTO adm.py_cx_advt_train
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位   
                 ORG_NAME             , -- 填报单位名称           
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 PUBL_TIME           , -- 宣传次数  
                 COMPARE_PUBL_TIME, -- 对比宣传次数
                 PUBL_NUM   , -- 发放宣传品数量  
                 COMPARE_PUBL_NUM,-- 对比发放宣传品数量
                 OFF_TIME  , -- 非现场宣传   
                 COMPARE_OFF_TIME,-- 对比非现场宣传
                 TRAIN_TIME         , -- 培训次数   
                 COMPARE_TRAIN_TIME, -- 对比培训次数
                 TRAIN_NUM , -- 培训人次   
                 COMPARE_TRAIN_NUM           , -- 对比培训人次  
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    a.AREA_NAME,
    a.ORG_ID,
    c.org_dscr,
    a.AREA_TYPE_CODE,
    '1' AS COMPARE_TYPE_CODE,
    a.PUBL_TIME,
    b.PUBL_TIME,
    a.PUBL_NUM,
    b.PUBL_NUM,
    a.OFF_TIME,
    b.OFF_TIME,
    a.TRAIN_TIME ,
    b.TRAIN_TIME,
    a.TRAIN_NUM,
    b.TRAIN_NUM,
    a.REMARKS
    FROM edw.py_cx_advt_train  a
    LEFT JOIN 
    (SELECT * FROM edw.py_cx_advt_train 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 12 MONTH),'%Y%m') )b
    ON a.AREA_ID=b.AREA_ID AND a.ORG_ID=b.ORG_ID AND  a.AREA_TYPE_CODE=b.AREA_TYPE_CODE 
    left join dmcode.`t_big_org` c
    on a.org_id=c.org_id
    WHERE a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  SET V_STEP_ID = 6;
 INSERT INTO adm.py_cx_advt_train
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位   
                 ORG_NAME             , -- 填报单位名称           
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 PUBL_TIME           , -- 宣传次数  
                 COMPARE_PUBL_TIME, -- 对比宣传次数
                 PUBL_NUM   , -- 发放宣传品数量  
                 COMPARE_PUBL_NUM,-- 对比发放宣传品数量
                 OFF_TIME  , -- 非现场宣传   
                 COMPARE_OFF_TIME,-- 对比非现场宣传
                 TRAIN_TIME         , -- 培训次数   
                 COMPARE_TRAIN_TIME, -- 对比培训次数
                 TRAIN_NUM , -- 培训人次   
                 COMPARE_TRAIN_NUM           , -- 对比培训人次                     
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    a.AREA_NAME,
    a.ORG_ID,
    c.org_dscr,
    a.AREA_TYPE_CODE,
    '2' AS COMPARE_TYPE_CODE,
    a.PUBL_TIME,
    b.PUBL_TIME,
    a.PUBL_NUM,
    b.PUBL_NUM,
    a.OFF_TIME,
    b.OFF_TIME,
    a.TRAIN_TIME ,
    b.TRAIN_TIME,
    a.TRAIN_NUM,
    b.TRAIN_NUM,
    a.REMARKS
    FROM edw.py_cx_advt_train  a
    LEFT JOIN 
    (SELECT * FROM edw.py_cx_advt_train 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 3 MONTH),'%Y%m') )b
    ON a.AREA_ID=b.AREA_ID AND a.ORG_ID=b.ORG_ID AND  a.AREA_TYPE_CODE=b.AREA_TYPE_CODE 
    LEFT JOIN dmcode.`t_big_org` c
    ON a.org_id=c.org_id
    WHERE a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
END
;;
delimiter ;

