-- ----------------------------
-- Procedure structure for py_cx_cash_servinfo
-- ----------------------------
DROP PROCEDURE IF EXISTS `py_cx_cash_servinfo`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `py_cx_cash_servinfo`(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.py_cx_cash_servinfo.PRC
     Functions : 服务网点数据入库,服务网点多维生成
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'adm.py_cx_cash_servinfo.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_RESULT        INT           DEFAULT 0;
    DECLARE V_DATES         VARCHAR(20)   DEFAULT 0;
    DECLARE V_STATE CHAR(1);
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_DATES = V_ACCT_ID;
    /* ------------------------------------------------------------------------ */
     SET V_STEP_ID = 1; 
DELETE FROM edw.py_cx_cash_servinfo WHERE insert_type='2';
INSERT INTO edw.py_cx_cash_servinfo
SELECT
 NULL,
 b.PUT_ORG_TYPE, -- 布设网点机构类型
 b.ORG_ID, -- 网点代码/商户号
 a.MAR_NUM, -- 机具编号
 b.PUT_ORG_NAME, -- 布设网点机构名称
 b.PUT_ORG_ID , -- 布设网点机构代码
 b.ORG_TYPE	,	-- 网点类型
 b.ORG_NAME,		-- 网点名称/商户名称
 b.MERCHANT_CARD_NUM,	-- 商户卡号
 b.AREA_NO_ID AS VILLAGE_CODE,	-- 	所在农村地区代码
 b.ADDRESS,	-- 	所在农村地区名称
 c.area_no_id ,  -- 所在地区代码
 c.area_dscr,  -- 所在地区名称
 c.area_no_id_2, -- 所在市代码
 c.area_dscr_2,  -- 所在市名称
 b.ADDRESS	,	-- 详细地址
 b.LONGITUDE,	-- 	地址坐标经度
 b.LATITUDE	,	-- 地址坐标纬度
 b.SITE_LEARDER,		-- 网点负责人
 b.SITE_LEARDER_ID,	-- 负责人身份证号
 b.TEL	,	-- 联系电话
 b.IS_LOAD_ELECTRICITY	,	-- 是否加载电商功能
 b.IS_OPEN_INTERBANK,	-- 	是否开通跨行功能
 b.ACCORD_DOOR,	-- 	门头照
 b.CREATE_DATE,	-- 	建成日期
 b.ABOLISH_DATE,	-- 废止日期
 b.UPDATE_DATE,	-- 	更新日期
 a.MAR_STATE,
 a.MAR_TYPE,
 '2'
  FROM (SELECT * FROM ods.py_cx_website_info
GROUP BY ORG_ID
HAVING DATA_DATE=MAX(DATA_DATE)
) b
 LEFT JOIN (SELECT * FROM ods.py_cx_tools_info
GROUP BY ORG_ID
HAVING DATA_DATE=MAX(DATA_DATE))  a ON 
 b.ORG_ID=a.ORG_ID
 LEFT JOIN dmcode.t_org_biz_lvl l
 ON b.PUT_ORG_NAME=l.ORG_DSCR
 LEFT JOIN dmcode.t_area_code c
 ON SUBSTR(b.AREA_NO_ID,1,6)=c.area_no_id ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   SET V_STEP_ID = 2; 
     TRUNCATE TABLE adm.py_cx_dw_cash_servinfo_tmp;
INSERT INTO adm.py_cx_dw_cash_servinfo_tmp   
SELECT SUBSTR(INSTALL_DATE,1,6) AS data_date,
VILLAGE_CODE AS AREA_NO,
ORG_NUM AS ORG_NO,
SUBSTR(ORG_NUM,1,6) AS BANK_TYPE,
CASE WHEN STATE='1' THEN '正常' ELSE '撤销' END AS STATE,
COUNT(shop_num) AS WD_NUM
FROM edw.py_cx_cash_servinfo
GROUP BY SUBSTR(INSTALL_DATE,1,6),
VILLAGE_CODE,ORG_NUM,SUBSTR(ORG_NUM,1,6),CASE WHEN STATE='1' THEN '正常' ELSE '撤销' END ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
       
          SET V_STEP_ID = 3; 
TRUNCATE TABLE adm.py_cx_dw_cash_servinfo  ;
INSERT INTO adm.py_cx_dw_cash_servinfo
(DATA_DATE, -- 数据日期
AREA_NO,-- 地区编码
ORG_NO,-- 金融机构编码
BANK_TYPE,-- 银行性质编码
STATE,-- 状态
WD_NUM,-- 服务点数量
TQ_WD_NUM,-- 同期服务点数量
SQ_WD_NUM)-- 上期服务点数量)
SELECT a.*,IFNULL(b.WD_NUM,0),IFNULL(c.WD_NUM,0)
FROM adm.py_cx_dw_cash_servinfo_tmp a
LEFT JOIN adm.py_cx_dw_cash_servinfo_tmp b
ON a.AREA_NO=b.AREA_NO AND a.ORG_NO=b.ORG_NO 
AND a.BANK_TYPE=b.BANK_TYPE AND a.STATE=b.STATE AND DATE_FORMAT(DATE_SUB(CONCAT(a.DATA_DATE,'01'),INTERVAL 1 MONTH),'%Y%m')=b.DATA_DATE
LEFT JOIN adm.py_cx_dw_cash_servinfo_tmp c
ON a.AREA_NO=c.AREA_NO AND a.ORG_NO=c.ORG_NO 
AND a.BANK_TYPE=c.BANK_TYPE AND a.STATE=c.STATE AND DATE_FORMAT(DATE_SUB(CONCAT(a.DATA_DATE,'01'),INTERVAL 1 MONTH),'%Y%m')=c.DATA_DATE ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
       
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for py_cx_envbld_agent_issue
-- ----------------------------
DROP PROCEDURE IF EXISTS `py_cx_envbld_agent_issue`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `py_cx_envbld_agent_issue`(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.py_cx_envbld_agent_issue.PRC
     Functions : 表8:代理发放
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'adm.py_cx_envbld_agent_issue.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_RESULT        INT           DEFAULT 0;
    DECLARE V_DATES         VARCHAR(20)   DEFAULT 0;
    DECLARE V_STATE CHAR(1);
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_AREA_ID,V_ORG_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_DATES = CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
    SET V_STEP_ID = 1;
    DELETE FROM edw.py_cx_envbld_agent_issue WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- ods汇总到edw，添加地区名称，区分地区类型  --插入农村数据
   SET V_STEP_ID = 2; 
  INSERT INTO edw.py_cx_envbld_agent_issue
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID         , -- 地区代码                
                 AREA_NAME            , -- 地区名称                
                 ORG_ID               , -- 填报单位 
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 RETIREMENT_COUNT           , -- 养老发放笔数
                 RETIREMENT_MONEY          , -- 养老发放金额     
                 MERGE_COUNT         , -- 新农合发放笔数    
                 MERGE_MONEY           , -- 新农合发放金额  
                 SUBSIDY_COUNT,       --  补贴发放笔数
                 SUBSIDY_MONEY,       -- 补贴发放金额
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    b.AREA_NAME,
    a.ORG_ID,
    '1',
    a.RETIREMENT_COUNT_COUNTRY,
    a.RETIREMENT_MONEY_COUNTRY,
    a.MERGE_COUNT_COUNTRY,
    a.MERGE_MONEY_COUNTRY ,
    a.SUBSIDY_COUNT_COUNTRY,
    a.SUBSIDY_MONEY_COUNTRY,
    a.REMARKS
    FROM ods.py_cx_envbld_agent_issue  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.AREA_ID=b.AREA_ID 
    WHERE b.AREA_TYPE_CODE='1'  AND a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
   
    -- ods汇总到edw，添加地区名称，区分地区类型  --插入贫困数据
   SET V_STEP_ID = 3; 
  INSERT INTO edw.py_cx_envbld_agent_issue
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID         , -- 地区代码                
                 AREA_NAME            , -- 地区名称                
                 ORG_ID               , -- 填报单位 
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 RETIREMENT_COUNT           , -- 养老发放笔数
                 RETIREMENT_MONEY          , -- 养老发放金额     
                 MERGE_COUNT         , -- 新农合发放笔数    
                 MERGE_MONEY           , -- 新农合发放金额  
                 SUBSIDY_COUNT,       --  补贴发放笔数
                 SUBSIDY_MONEY,       -- 补贴发放金额
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    b.AREA_NAME,
    a.ORG_ID,
    '2',
    a.RETIREMENT_COUNT_POOR,
    a.RETIREMENT_MONEY_POOR,
    a.MERGE_COUNT_POOR,
    a.MERGE_MONEY_POOR ,
    a.SUBSIDY_COUNT_POOR,
    a.SUBSIDY_MONEY_POOR,
    a.REMARKS
    FROM ods.py_cx_envbld_agent_issue  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.AREA_ID=b.AREA_ID 
    WHERE b.AREA_TYPE_CODE='2'  AND a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  SET V_STEP_ID = 4;
    DELETE FROM adm.py_cx_envbld_agent_issue WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- edw汇总到adm，生成报表展示adm表，同时生成 异动分析结果表
   SET V_STEP_ID = 5;
  INSERT INTO adm.py_cx_envbld_agent_issue
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位   
                 ORG_NAME             , -- 填报单位名称           
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 RETIREMENT_COUNT           , -- 养老发放笔数
                 COMPARE_RETIREMENT_COUNT,  
                 RETIREMENT_MONEY   , -- 养老发放金额  
                 COMPARE_RETIREMENT_MONEY,
                 MERGE_COUNT  , -- 新农合发放笔数  
                  COMPARE_MERGE_COUNT,
                 MERGE_MONEY         , -- 新农合发放金额   
                 COMPARE_MERGE_MONEY,
                 SUBSIDY_COUNT , -- 补贴发放笔数 
                  COMPARE_SUBSIDY_COUNT, 
                 SUBSIDY_MONEY           , -- 补贴发放金额    
                 COMPARE_SUBSIDY_MONEY,                   
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    a.AREA_NAME,
    a.ORG_ID,
    c.org_dscr,
    a.AREA_TYPE_CODE,
    '1' AS COMPARE_TYPE_CODE,
    a.RETIREMENT_COUNT,
    b.RETIREMENT_COUNT,
    a.RETIREMENT_MONEY,
    b.RETIREMENT_MONEY,
    a.MERGE_COUNT,
    b.MERGE_COUNT,
    a.MERGE_MONEY ,
    b.MERGE_MONEY,
    a.SUBSIDY_COUNT,
    b.SUBSIDY_COUNT,
    a.SUBSIDY_MONEY,
    a.SUBSIDY_MONEY,
    a.REMARKS
    FROM edw.py_cx_envbld_agent_issue  a
    LEFT JOIN 
    (SELECT * FROM edw.py_cx_envbld_agent_issue 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_ACCT_ID,INTERVAL 12 MONTH),'%Y%m') )b
    ON a.AREA_ID=b.AREA_ID AND a.ORG_ID=b.ORG_ID AND  a.AREA_TYPE_CODE=b.AREA_TYPE_CODE 
    left join dmcode.`t_big_org` c
    on a.org_id=c.org_id
    WHERE a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  SET V_STEP_ID = 6;
 INSERT INTO adm.py_cx_envbld_agent_issue
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位   
                 ORG_NAME             , -- 填报单位名称           
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 RETIREMENT_COUNT           , -- 养老发放笔数
                 COMPARE_RETIREMENT_COUNT,  
                 RETIREMENT_MONEY   , -- 养老发放金额  
                 COMPARE_RETIREMENT_MONEY,
                 MERGE_COUNT  , -- 新农合发放笔数  
                 COMPARE_MERGE_COUNT,
                 MERGE_MONEY         , -- 新农合发放金额   
                 COMPARE_MERGE_MONEY,
                 SUBSIDY_COUNT , -- 补贴发放笔数 
                 COMPARE_SUBSIDY_COUNT, 
                 SUBSIDY_MONEY           , -- 补贴发放金额    
                 COMPARE_SUBSIDY_MONEY,                   
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    a.AREA_NAME,
    a.ORG_ID,
    c.org_dscr,
    a.AREA_TYPE_CODE,
    '2' AS COMPARE_TYPE_CODE,
    a.RETIREMENT_COUNT,
    b.RETIREMENT_COUNT,
    a.RETIREMENT_MONEY,
    b.RETIREMENT_MONEY,
    a.MERGE_COUNT,
    b.MERGE_COUNT,
    a.MERGE_MONEY ,
    b.MERGE_MONEY,
    a.SUBSIDY_COUNT,
    b.SUBSIDY_COUNT,
    a.SUBSIDY_MONEY,
    a.SUBSIDY_MONEY,
    a.REMARKS
    FROM edw.py_cx_envbld_agent_issue  a
    LEFT JOIN 
    (SELECT * FROM edw.py_cx_envbld_agent_issue 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_ACCT_ID,INTERVAL 3 MONTH),'%Y%m') )b
    ON a.AREA_ID=b.AREA_ID AND a.ORG_ID=b.ORG_ID AND  a.AREA_TYPE_CODE=b.AREA_TYPE_CODE 
    LEFT JOIN dmcode.`t_big_org` c
    ON a.org_id=c.org_id
    WHERE a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
END
;;
delimiter ;

