    ON w.AREA_ID=b.AREA_ID 
    WHERE w.DATA_DATE=SUBSTR(V_ACCT_ID,1,6)    
   UNION ALL  
    
SELECT
w.DATA_DATE       	                 -- 数据日期，账期            
,w.AREA_ID         	                 -- 地区代码                  
,b.AREA_NAME       	                 -- 地区名称                  
,w.ORG_ID          	                 -- 填报单位                  
