,0          	                     -- 金额（万元）              
,w.REMARKS         	                 -- 备注      
FROM ODS.`py_cx_envbld_hf_wd1` w INNER JOIN edw.py_cx_area_ncpk_code b
    ON w.AREA_ID=b.AREA_ID 
    WHERE w.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) 
 
 UNION ALL
    
 SELECT
w.DATA_DATE       	               -- 数据日期，账期            
,w.AREA_ID         	               -- 地区代码                  
,b.AREA_NAME       	               -- 地区名称                  
,w.ORG_ID          	               -- 填报单位                  
,'2'  			                   -- 地区类型编码1农村/2贫困   
,'30'			                   -- 助农取款服务类型代码      
,w.BLANK_VILLAGE_NUMBER_POOR       -- 数量(个)                  
,''         	                   -- 村级行政区覆盖率（百分比）
