,PEN               -- 笔数（万笔）
,COMPARE_PEN       -- 对比笔数（万笔）       
,AMOUNT            -- 金额（万元）                           
,COMPARE_AMOUNT    -- 对比金额（万元）            
,REMARKS           -- 备注                    
		     
		   
		     
)                         
SELECT                    
w.DATA_DATE               
,w.AREA_ID                
,w.AREA_NAME 
,w.ORG_ID
,c.org_dscr
,w.AREA_TYPE_CODE      
,'1' AS COMPARE_TYPE_CODE
,w.FARM_DRAWAL_CODE
,w.COUNT   
,b.COUNT
,w.PERCENT
,b.PERCENT
,w.PEN                  
,b.PEN	
,w.AMOUNT		
,b.AMOUNT               
,w.REMARKS              
FROM EDW.py_cx_envbld_hf_wd w  
LEFT JOIN 
    (SELECT * FROM edw.py_cx_envbld_hf_wd 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_ACCT_ID,INTERVAL 12 MONTH),'%Y%m') )b
    ON w.AREA_ID=b.AREA_ID AND w.ORG_ID=b.ORG_ID AND  w.AREA_TYPE_CODE=b.AREA_TYPE_CODE 
        LEFT JOIN dmcode.t_big_org c
    ON w.org_id=c.org_id
    WHERE w.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) 
    
     UNION ALL
    
    SELECT  
w.DATA_DATE
,w.AREA_ID   
,w.AREA_NAME 
,w.ORG_ID
,c.org_dscr
,w.AREA_TYPE_CODE     
,'1' AS COMPARE_TYPE_CODE
,w.FARM_DRAWAL_CODE
,w.COUNT   
,b.COUNT
,w.PERCENT
,b.PERCENT
,w.PEN                  
,b.PEN	
,w.AMOUNT		
,b.AMOUNT               
,w.REMARKS              
FROM EDW.py_cx_envbld_hf_wd w  
LEFT JOIN 
    (SELECT * FROM edw.py_cx_envbld_hf_wd 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_ACCT_ID,INTERVAL 3 MONTH),'%Y%m'))b
    ON w.AREA_ID=b.AREA_ID AND w.ORG_ID=b.ORG_ID AND  w.AREA_TYPE_CODE=b.AREA_TYPE_CODE 
        LEFT JOIN dmcode.t_big_org c
    ON w.org_id=c.org_id
    WHERE  w.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
         
      CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());    
    END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for py_cx_envbld_hf_wd_mid
-- ----------------------------
DROP PROCEDURE IF EXISTS `py_cx_envbld_hf_wd_mid`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `py_cx_envbld_hf_wd_mid`(
    IN  P_DATA_DATE VARCHAR(8)
    ,OUT P_RESULT    INT)
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 宋楠
     Name      : edw.py_cx_envbld_hf_wd_mid.PRC
     Functions : 广东省银行卡助农取款服务业务发展统计表
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
	DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.py_cx_envbld_hf_wd_mid.PRC';
	DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
	DECLARE V_STEP_ID       INT           DEFAULT 0;
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    /* ------------------------------------------------------------------------ */
    
    SET V_STEP_ID = 1;
    DELETE FROM ADM.py_cx_envbld_hf_wd_mid WHERE DATA_DATE = SUBSTR(P_DATA_DATE,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    SET V_STEP_ID = 2; 
    INSERT INTO ADM.py_cx_envbld_hf_wd_mid_cs(
    
	DATA_DATE,                 -- 账期          
        city_name,                -- 地区代码      
        service_point_count,       -- 取款类型描ID  
        nh_bank,                   -- 农行          
        yc_bank,                  --  邮储          
        nxs_bank,                 --  农信社        
        qt_bank,                   -- 其他金融机构  
        zf_bank,                   -- 支付机构      
	xj_bank                  --  小计          
    )
    
   SELECT
	SUBSTR(t.trade_date,1,6),
	s.city_name AS '地区',
	'助农取款服务点数量' AS '取款类型描ID',
	CASE WHEN SUBSTR(s.ORG_NUM,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='农行') THEN COUNT(DISTINCT s.SERVICE_POINT_NAME) ELSE 0 END AS '农行',
	CASE WHEN SUBSTR(s.ORG_NUM,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='邮储银行') THEN COUNT(DISTINCT s.SERVICE_POINT_NAME) ELSE 0 END AS '邮储',
	CASE WHEN SUBSTR(s.ORG_NUM,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='农村商业银行') THEN COUNT(DISTINCT s.SERVICE_POINT_NAME) ELSE 0 END AS '农村商业',
	CASE WHEN SUBSTR(s.ORG_NUM,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='支付机构') THEN COUNT(DISTINCT s.SERVICE_POINT_NAME) ELSE 0 END AS '支付机构',		
	CASE WHEN SUBSTR(s.ORG_NUM,4,3) NOT IN (SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME IN ('农行','邮储银行','农村商业银行','支付机构') )THEN COUNT(DISTINCT s.SERVICE_POINT_NAME) ELSE 0 END AS '其他银行',
	COUNT(DISTINCT s.SERVICE_POINT_NAME) AS '小计'
FROM EDW.py_cx_cash_servinfo s
LEFT JOIN EDW.`py_cx_cash_tradelog` t 
ON s.ORG_NUM=t.col_org_num AND t.termina_num=s.TERMINA_NUM
WHERE SUBSTR(t.trade_date,1,6)=SUBSTR(P_DATA_DATE,1,6)
GROUP BY s.city_name
UNION ALL
SELECT	SUBSTR(t.trade_date,1,6),
        s.city_name,
        
	'累计布放受理终端数量',
	CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='农行') THEN COUNT(DISTINCT t.termina_num) ELSE 0 END AS '农行',
	CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='邮储银行') THEN COUNT(DISTINCT t.termina_num) ELSE 0 END AS '邮储',
	CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='农村商业银行') THEN COUNT(DISTINCT t.termina_num) ELSE 0 END AS '农村商业',
	CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='支付机构') THEN COUNT(DISTINCT t.termina_num) ELSE 0 END AS '支付机构',		
	CASE WHEN SUBSTR(t.col_org_num,4,3) NOT IN (SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME IN ('农行','邮储银行','农村商业银行','支付机构') )THEN COUNT(DISTINCT t.termina_num) ELSE 0 END AS '其他银行',
	COUNT(DISTINCT t.termina_num) AS '小计'
FROM EDW.py_cx_cash_servinfo s
LEFT JOIN EDW.`py_cx_cash_tradelog` t 
ON s.ORG_NUM=t.col_org_num AND t.termina_num=s.TERMINA_NUM
WHERE  DATE_FORMAT(t.trade_date,'%Y%m')=SUBSTR(P_DATA_DATE,1,6)
GROUP BY s.city_name
UNION ALL
SELECT	SUBSTR(t.trade_date,1,6),
        s.city_name,
         
	'本月取款交易笔数',
	CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='农行') THEN COUNT(t.trade_num) ELSE 0 END AS '农行',
	CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='邮储银行') THEN COUNT(t.trade_num) ELSE 0 END AS '邮储',
	CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='农村商业银行') THEN COUNT( t.trade_num) ELSE 0 END AS '农村商业',
	CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='支付机构') THEN COUNT( t.trade_num) ELSE 0 END AS '支付机构',		
	CASE WHEN SUBSTR(t.col_org_num,4,3) NOT IN (SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME IN ('农行','邮储银行','农村商业银行','支付机构') )THEN COUNT( t.trade_num) ELSE 0 END AS '其他银行',
	COUNT( t.trade_num) AS '小计'
FROM EDW.py_cx_cash_servinfo s
LEFT JOIN EDW.`py_cx_cash_tradelog` t 
ON s.ORG_NUM=t.col_org_num AND t.termina_num=s.TERMINA_NUM
WHERE  t.trade_type LIKE '%助农取款%'  AND DATE_FORMAT(t.trade_date,'%Y%m')=SUBSTR(P_DATA_DATE,1,6)
GROUP BY s.city_name
UNION ALL
SELECT	SUBSTR(t.trade_date,1,6),
        s.city_name,
         
