	SUM(CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='邮储银行') THEN t.trade_amount ELSE 0 END )AS '邮储',
	SUM(CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='农村商业银行') THEN t.trade_amount ELSE 0 END )AS '农村商业',
	SUM(CASE WHEN SUBSTR(t.col_org_num,4,3)=(SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME='支付机构') THEN t.trade_amount ELSE 0 END )AS '支付机构',		
	SUM(CASE WHEN SUBSTR(t.col_org_num,4,3) NOT IN (SELECT cm.PUT_ORG_TYPE FROM edw.py_cx_put_org_type cm WHERE cm.PUT_ORG_TYPE_NAME  IN ('农行','邮储银行','农村商业银行','支付机构') )THEN t.trade_amount ELSE 0 END )AS '其他银行',
	SUM(t.trade_amount) AS '合计'
FROM EDW.py_cx_cash_servinfo s
LEFT JOIN EDW.`py_cx_cash_tradelog` t 
ON s.ORG_NUM=t.col_org_num AND t.termina_num=s.TERMINA_NUM
WHERE trade_type  NOT LIKE '%转账%' AND trade_type  NOT LIKE '%查询%' AND trade_type  NOT LIKE '%助农取款%' 
 AND (DATE_FORMAT(t.trade_date,'%Y%m') BETWEEN CONCAT(SUBSTR(P_DATA_DATE,1,4),'01') AND
 SUBSTR(P_DATA_DATE,1,6)) 
GROUP BY s.city_name ;
CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    SET V_STEP_ID = 3; 
INSERT INTO ADM.py_cx_envbld_hf_wd_mid(
    
	DATA_DATE,                 -- 账期          
        city_name,                -- 地区代码      
        village_count,             -- 全部行政村数量
        service_point_count,       -- 取款类型描ID  
        nh_bank,                   -- 农行          
        yc_bank,                  --  邮储          
        nxs_bank,                 --  农信社        
        qt_bank,                   -- 其他金融机构  
        zf_bank,                   -- 支付机构      
	xj_bank                  --  小计          
    )
    select 
    DATA_DATE,                 -- 账期          
        city_name,                -- 地区代码      
        count(distinct VILLAGE_NAME),             -- 全部行政村数量
        service_point_count,       -- 取款类型描ID  
        nh_bank,                   -- 农行          
        yc_bank,                  --  邮储          
        nxs_bank,                 --  农信社        
        qt_bank,                   -- 其他金融机构  
        zf_bank,                   -- 支付机构      
	xj_bank                  --  小计 
   from  ADM.py_cx_envbld_hf_wd_mid_cs m left JOIN EDW.py_cx_cash_servinfo s on m.city_name=s.city_name
   group by city_name;
CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
   SET V_STEP_ID = 4; 
INSERT INTO ADM.py_cx_envbld_hf_wd_mid(
    
	DATA_DATE,                 -- 账期          
        city_name,                -- 地区代码      
        village_count,             -- 全部行政村数量
        service_point_count,       -- 取款类型描ID  
        nh_bank,                   -- 农行          
        yc_bank,                  --  邮储          
        nxs_bank,                 --  农信社        
        qt_bank,                   -- 其他金融机构  
        zf_bank,                   -- 支付机构      
	xj_bank                  --  小计          
    )
   SELECT
	DATA_DATE,
	'合计',
	SUM(village_count),
	service_point_count,
	SUM(nh_bank),
	SUM(yc_bank),
	SUM(nxs_bank),
	SUM(qt_bank),
	SUM(zf_bank),
	SUM(xj_bank)
	 
FROM ADM.`py_cx_envbld_hf_wd_mid`
WHERE DATA_DATE=SUBSTR('20141001',1,6)
GROUP BY service_point_count;
CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());	
	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for py_cx_envbld_nonbnk_innet_pay
-- ----------------------------
DROP PROCEDURE IF EXISTS `py_cx_envbld_nonbnk_innet_pay`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `py_cx_envbld_nonbnk_innet_pay`(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.py_cx_envbld_nonbnk_innet_pay.PRC
     Functions : 表10 非银行支付机构农村网络支付业务
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'adm.py_cx_envbld_nonbnk_innet_pay.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_RESULT        INT           DEFAULT 0;
    DECLARE V_DATES         VARCHAR(20)   DEFAULT 0;
    DECLARE V_STATE CHAR(1);
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_DATES = CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
    SET V_STEP_ID = 1;
    DELETE FROM edw.py_cx_envbld_nonbnk_innet_pay WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- ods汇总到edw，添加地区名称，区分地区类型  --插入农村数据
   SET V_STEP_ID = 2; 
  INSERT INTO edw.py_cx_envbld_nonbnk_innet_pay
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID         , -- 地区代码                
                 AREA_NAME            , -- 地区名称                
                 ORG_ID               , -- 填报单位 
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 ONLINE_PAY_COUNT           , -- 互联网支付笔数(万笔)
                 ONLINE_PAY_MONEY          , -- 互联网支付金额(亿元)     
                 MOVE_PHONE_COUNT         , -- 移动电话支付(笔数)    
                 MOVE_PHONE_MONEY           , -- 移动电话支付金额(亿元)  
                 ONLINE_RETAIL_COUNT,       --  电商业务量笔数(万笔)
                 ONLINE_RETAIL_MONEY,      -- 电商业务量金额(亿元)
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    b.AREA_NAME,
    a.ORG_ID,
    '1',
    a.ONLINE_PAY_COUNT_COUNTRY,
    a.ONLINE_PAY_MONEY_COUNTRY,
    a.MOVE_PHONE_COUNT_COUNTRY,
    a.MOVE_PHONE_MONEY_COUNTRY ,
    a.ONLINE_RETAIL_COUNT_COUNTRY,
    a.ONLINE_RETAIL_MONEY_COUNTRY,
    a.REMARKS
    FROM ods.py_cx_envbld_nonbnk_innet_pay  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.AREA_NO=b.AREA_ID 
    WHERE b.AREA_TYPE_CODE='1'  AND a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
   
    -- ods汇总到edw，添加地区名称，区分地区类型  --插入贫困数据
   SET V_STEP_ID = 3; 
  INSERT INTO edw.py_cx_envbld_nonbnk_innet_pay
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID         , -- 地区代码                
                 AREA_NAME            , -- 地区名称                
                 ORG_ID               , -- 填报单位 
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 ONLINE_PAY_COUNT           , -- 互联网支付笔数(万笔)
                 ONLINE_PAY_MONEY          , -- 互联网支付金额(亿元)     
                 MOVE_PHONE_COUNT         , -- 移动电话支付(笔数)    
                 MOVE_PHONE_MONEY           , -- 移动电话支付金额(亿元)  
                 ONLINE_RETAIL_COUNT,       --  电商业务量笔数(万笔)
                 ONLINE_RETAIL_MONEY,      -- 电商业务量金额(亿元)
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    b.AREA_NAME,
    a.ORG_ID,
    '2',
    a.ONLINE_PAY_COUNT_POOR,
    a.ONLINE_PAY_MONEY_POOR,
    a.MOVE_PHONE_COUNT_POOR,
    a.MOVE_PHONE_MONEY_POOR ,
    a.ONLINE_RETAIL_COUNT_POOR,
    a.ONLINE_RETAIL_MONEY_POOR,
    a.REMARKS
    FROM ods.py_cx_envbld_nonbnk_innet_pay  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.AREA_NO=b.AREA_ID 
    WHERE b.AREA_TYPE_CODE='2'  AND a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6)  ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  SET V_STEP_ID = 4;
    DELETE FROM adm.py_cx_envbld_nonbnk_innet_pay WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- edw汇总到adm，生成报表展示adm表，同时生成 异动分析结果表
   SET V_STEP_ID = 5;
  INSERT INTO adm.py_cx_envbld_nonbnk_innet_pay
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位   
                 ORG_NAME             , -- 填报单位名称           
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 ONLINE_PAY_COUNT           , -- 互联网支付笔数(万笔)  
                 COMPARE_ONLINE_PAY_COUNT, -- 对比互联网支付笔数(万笔)
                 ONLINE_PAY_MONEY   , -- 互联网支付金额(亿元)  
                 COMPARE_ONLINE_PAY_MONEY,-- 对比互联网支付金额(亿元)
                 MOVE_PHONE_COUNT  , -- 移动电话支付(笔数)   
                 COMPARE_MOVE_PHONE_COUNT,-- 对比移动电话支付(笔数)
                 MOVE_PHONE_MONEY         , -- 移动电话支付金额(亿元)   
                 COMPARE_MOVE_PHONE_MONEY, -- 对比移动电话支付金额(亿元)
                 ONLINE_RETAIL_COUNT , -- 电商业务量笔数(万笔)   
                 COMPARE_ONLINE_RETAIL_COUNT           , -- 对比电商业务量笔数(万笔)      
                 ONLINE_RETAIL_MONEY , -- 电商业务量金额(亿元)   
                 COMPARE_ONLINE_RETAIL_MONEY           , -- 对比电商业务量金额(亿元)                  
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    a.AREA_NAME,
    a.ORG_ID,
    c.org_dscr,
    a.AREA_TYPE_CODE,
    '1' AS COMPARE_TYPE_CODE,
    a.ONLINE_PAY_COUNT,
    b.ONLINE_PAY_COUNT,
    a.ONLINE_PAY_MONEY,
    b.ONLINE_PAY_MONEY,
    a.MOVE_PHONE_COUNT,
    b.MOVE_PHONE_COUNT,
    a.MOVE_PHONE_MONEY ,
    b.MOVE_PHONE_MONEY,
    a.ONLINE_RETAIL_COUNT,
    b.ONLINE_RETAIL_COUNT,
    a.ONLINE_RETAIL_MONEY,
    b.ONLINE_RETAIL_MONEY,
    a.REMARKS
    FROM edw.py_cx_envbld_nonbnk_innet_pay  a
    LEFT JOIN 
    (SELECT * FROM edw.py_cx_envbld_nonbnk_innet_pay 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_ACCT_ID,INTERVAL 12 MONTH),'%Y%m') )b
    ON a.AREA_ID=b.AREA_ID AND a.ORG_ID=b.ORG_ID AND  a.AREA_TYPE_CODE=b.AREA_TYPE_CODE 
    left join dmcode.`t_big_org` c
    on a.org_id=c.org_id
    WHERE a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  SET V_STEP_ID = 6;
  INSERT INTO adm.py_cx_envbld_nonbnk_innet_pay
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位   
                 ORG_NAME             , -- 填报单位名称           
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 ONLINE_PAY_COUNT           , -- 互联网支付笔数(万笔)  
                 COMPARE_ONLINE_PAY_COUNT, -- 对比互联网支付笔数(万笔)
                 ONLINE_PAY_MONEY   , -- 互联网支付金额(亿元)  
                 COMPARE_ONLINE_PAY_MONEY,-- 对比互联网支付金额(亿元)
                 MOVE_PHONE_COUNT  , -- 移动电话支付(笔数)   
                 COMPARE_MOVE_PHONE_COUNT,-- 对比移动电话支付(笔数)
                 MOVE_PHONE_MONEY         , -- 移动电话支付金额(亿元)   
                 COMPARE_MOVE_PHONE_MONEY, -- 对比移动电话支付金额(亿元)
                 ONLINE_RETAIL_COUNT , -- 电商业务量笔数(万笔)   
                 COMPARE_ONLINE_RETAIL_COUNT           , -- 对比电商业务量笔数(万笔)      
                 ONLINE_RETAIL_MONEY , -- 电商业务量金额(亿元)   
                 COMPARE_ONLINE_RETAIL_MONEY           , -- 对比电商业务量金额(亿元)                  
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    a.AREA_NAME,
    a.ORG_ID,
    c.org_dscr,
    a.AREA_TYPE_CODE,
    '2' AS COMPARE_TYPE_CODE,
    a.ONLINE_PAY_COUNT,
    b.ONLINE_PAY_COUNT,
    a.ONLINE_PAY_MONEY,
    b.ONLINE_PAY_MONEY,
    a.MOVE_PHONE_COUNT,
    b.MOVE_PHONE_COUNT,
    a.MOVE_PHONE_MONEY ,
    b.MOVE_PHONE_MONEY,
    a.ONLINE_RETAIL_COUNT,
    b.ONLINE_RETAIL_COUNT,
    a.ONLINE_RETAIL_MONEY,
    b.ONLINE_RETAIL_MONEY,
    a.REMARKS
    FROM edw.py_cx_envbld_nonbnk_innet_pay  a
    LEFT JOIN 
    (SELECT * FROM edw.py_cx_envbld_nonbnk_innet_pay 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_ACCT_ID,INTERVAL 3 MONTH),'%Y%m') )b
    ON a.AREA_ID=b.AREA_ID AND a.ORG_ID=b.ORG_ID AND  a.AREA_TYPE_CODE=b.AREA_TYPE_CODE 
    LEFT JOIN dmcode.`t_big_org` c
    ON a.org_id=c.org_id
    WHERE a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
END
;;
