 /* ------------------------------------------------------------------------ */
   
    -- ods汇总到edw，添加地区名称，区分地区类型  --插入贫困数据
   SET V_STEP_ID = 3; 
  INSERT INTO edw.py_cx_envbld_rural_bnk_accts
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                
