     -- ods.py_cx_envbld_rural_cards_mkt2汇总到edw，添加地区名称，区分地区类型  --插入贫困数据
   SET V_STEP_ID = 5;   
INSERT INTO edw.py_cx_envbld_rural_cards_mkt (
