AREA_ID        ,-- 地区代码                                                                                               
AREA_NAME      ,-- 地区名称                                                                                               
ORG_ID         ,-- 填报单位                                                                                               
AREA_TYPE_CODE ,-- 地区类型编码1农村/2贫困                                                                                
BCARD_TYPE_DSCR,-- 银行卡业务类型描述(04ATM业务量,05POS业务量,06其他银行卡受理终端业务量,10各类银行卡受理终端业务量合计)  
SPECIAL_MERCH  ,-- 特约商户（户）                                                                                         
NUMBER         ,-- 数量(台)                                                                                               
COUNT          ,-- 笔数（万笔）                                                                                           
MONEY          ,-- 金额（万元）                                                                                           
TRANSFER_PHONE ,  -- 其中转账电话（台）                                                                                     
REMARKS         --  备注                                                                                                   
 )    
SELECT 
 m.DATA_DATE 
,m.AREA_ID 
,b.AREA_NAME     
,m.ORG_ID 
,'2'  
,t.BUSINESS_CODE
,0
,m.NUMBER_POOR
,m.COUNT_POOR 
,m.MONRY_POOR 
,m.TRANSFER_POOR
,'' 
FROM ods.`py_cx_envbld_rural_cards_mkt2` m LEFT JOIN edw.py_cx_area_ncpk_code b
 ON m.AREA_ID=b.AREA_ID  LEFT JOIN EDW.`py_cx_bus_type` t ON m.BCARD_TYPE_DSCR=t.BUSINESS_TYPE
 WHERE b.AREA_TYPE_CODE='2' AND m.DATA_DATE=SUBSTR(V_ACCT_ID,1,6);       
   
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   -- edw汇总到adm，生成报表展示adm表，同时生成 异动分析结果表
     SET V_STEP_ID = 6;  
     
     INSERT INTO adm.py_cx_envbld_rural_cards_mkt (
