    ON m.AREA_ID=b.AREA_ID AND m.ORG_ID=b.ORG_ID AND  m.AREA_TYPE_CODE=b.AREA_TYPE_CODE  AND m.BCARD_TYPE_DSCR=b.BCARD_TYPE_DSCR
        LEFT JOIN dmcode.`t_big_org` c
