    a.ORG_ID,
    '2',
    a.COUNT_POOR,
    a.MONEY_POOR,
    a.BANK_BRANCH_POOR,
    a.AGENCY_BRANCH_POOR ,
    a.COVERAGE_POOR,
    a.REMARKS
    FROM ods.py_cx_envbld_rural_cls  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.AREA_ID=b.AREA_ID 
    WHERE b.AREA_TYPE_CODE='2'  AND a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  SET V_STEP_ID = 4;
    DELETE FROM adm.py_cx_envbld_rural_cls WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- edw汇总到adm，生成报表展示adm表，同时生成 异动分析结果表
   SET V_STEP_ID = 5;
  INSERT INTO adm.py_cx_envbld_rural_cls
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位  
                 org_name,              
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 COUNT           , -- 借记卡在用发卡数量  
                 COMPARE_COUNT   , -- 对比借记卡在用发卡数量  
                 MONEY  , -- 对比信用卡在用发卡数量   
                 COMPARE_MONEY         , -- 借贷合一卡在用发卡量   
                 BANK_BRANCH , -- 对比借贷合一卡在用发卡量   
                 COMPARE_BANK_BRANCH           , -- 人均持卡量    
                 AGENCY_BRANCH   , -- 对比人均持卡量  
                 COMPARE_AGENCY_BRANCH   , -- 对比人均持卡量   
                 COVERAGE   , -- 对比人均持卡量  
                 COMPARE_COVERAGE   , -- 对比人均持卡量                     
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    a.AREA_NAME,
    a.ORG_ID,
    c.org_dscr,
    a.AREA_TYPE_CODE,
    '1' AS COMPARE_TYPE_CODE,
    a.COUNT,
    b.COUNT,
    a.MONEY,
    b.MONEY,
    a.BANK_BRANCH,
    b.BANK_BRANCH,
    a.AGENCY_BRANCH ,
    b.AGENCY_BRANCH,
    a.COVERAGE,
    b.COVERAGE,
    a.REMARKS
    FROM edw.py_cx_envbld_rural_cls  a
    LEFT JOIN 
    (SELECT * FROM edw.py_cx_envbld_rural_cls 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 12 MONTH),'%Y%m') )b
    ON a.AREA_ID=b.AREA_ID AND a.ORG_ID=b.ORG_ID AND  a.AREA_TYPE_CODE=b.AREA_TYPE_CODE 
        LEFT JOIN dmcode.`t_big_org` c
    ON a.org_id=c.org_id
    WHERE a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  SET V_STEP_ID = 6;
  INSERT INTO adm.py_cx_envbld_rural_cls
               (
                  DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位  
                 org_name,              
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困 
                 COMPARE_TYPE_CODE    , -- 对比类型编码1同比/2环比
                 COUNT           , -- 借记卡在用发卡数量  
                 COMPARE_COUNT   , -- 对比借记卡在用发卡数量  
                 MONEY  , -- 对比信用卡在用发卡数量   
                 COMPARE_MONEY         , -- 借贷合一卡在用发卡量   
                 BANK_BRANCH , -- 对比借贷合一卡在用发卡量   
                 COMPARE_BANK_BRANCH           , -- 人均持卡量    
                 AGENCY_BRANCH   , -- 对比人均持卡量  
                 COMPARE_AGENCY_BRANCH   , -- 对比人均持卡量   
                 COVERAGE   , -- 对比人均持卡量  
                 COMPARE_COVERAGE   , -- 对比人均持卡量                     
                 REMARKS               -- 备注  
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
