ORG_ID         ,-- 填报单位                                            
AREA_TYPE_CODE ,-- 地区类型编码1农村/2贫困                             
PAY_CODE       ,-- 支付类型(07网上支付,08移动支付,09电话支付)          
BUSINESS_CODE  ,-- 业务量类型(01银行卡业务量,02票据业务量,03电商业务量)
ACCOUNT_NUMBER ,-- 开户数量（万户）                                    
COUNT          ,-- 笔数（万笔）                                        
MONEY          ,-- 金额（万元）                                        
REMARKS         -- 备注                                                
 )
SELECT 
 t.DATA_DATE 
,t.AREA_ID 
,b.AREA_NAME     
,t.ORG_ID 
,'1'  
,t.PAY_DSCR    
,''
,t.ACCOUNT_NUMBER_COUNTRY
,t.COUNT_COUNTRY   
,t.MONEY_COUNTRY 
,''
FROM ods.`py_cx_envbld_rural_ncpi_tltyp2` t LEFT JOIN edw.py_cx_area_ncpk_code b
 ON t.AREA_ID=b.AREA_ID    
 WHERE b.AREA_TYPE_CODE='1' AND t.DATA_DATE=SUBSTR(V_ACCT_ID,1,6); 
   
 
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
     /* ------------------------------------------------------------------------ */
      -- ods.py_cx_envbld_rural_ncpi_tltyp2汇总到edw，添加地区名称，区分地区类型  --插入贫困数据
   SET V_STEP_ID = 5;
   INSERT INTO edw.py_cx_envbld_rural_ncpi_tltyp (
DATA_DATE      ,-- 数据日期，账期                                      
AREA_ID        ,-- 地区代码                                            
AREA_NAME      ,-- 地区名称                                            
ORG_ID         ,-- 填报单位                                            
AREA_TYPE_CODE ,-- 地区类型编码1农村/2贫困                             
PAY_CODE       ,-- 支付类型(07网上支付,08移动支付,09电话支付)          
BUSINESS_CODE  ,-- 业务量类型(01银行卡业务量,02票据业务量,03电商业务量)
ACCOUNT_NUMBER ,-- 开户数量（万户）                                    
COUNT          ,-- 笔数（万笔）                                        
MONEY          ,-- 金额（万元）                                        
REMARKS         -- 备注                                                
 )
 SELECT 
 t.DATA_DATE 
,t.AREA_ID 
,b.AREA_NAME     
,t.ORG_ID 
,'2'  
,t.PAY_DSCR    
,''
,t.ACCOUNT_NUMBER_POOR
,t.COUNT_POOR   
,t.MONEY_POOR
,''
FROM ods.`py_cx_envbld_rural_ncpi_tltyp2` t LEFT JOIN edw.py_cx_area_ncpk_code b
    ON t.AREA_ID=b.AREA_ID    
   WHERE b.AREA_TYPE_CODE='2' AND t.DATA_DATE=SUBSTR(V_ACCT_ID,1,6); 
   
   
   
          
     -- edw汇总到adm，生成报表展示adm表，同时生成 异动分析结果表
     SET V_STEP_ID = 6;
     INSERT INTO adm.py_cx_envbld_rural_ncpi_tltyp (
DATA_DATE              ,
AREA_ID                ,
AREA_NAME              ,
ORG_ID                 ,
ORG_NAME               ,
AREA_TYPE_CODE         ,
COMPARE_TYPE_CODE      ,
PAY_CODE               ,
BUSINESS_CODE          ,
ACCOUNT_NUMBER         ,
COMPARE_ACCOUNT_NUMBER ,
COUNT                  ,
COMPARE_COUNT         ,
MONEY                 ,
COMPARE_MONEY         ,
REMARKS               
 )
SELECT  
SUBSTR(V_ACCT_ID,1,6), 
t.AREA_ID   ,
t.AREA_NAME ,
t.ORG_ID,
c.org_dscr,
t.AREA_TYPE_CODE,           
'1' AS COMPARE_TYPE_CODE,
t.PAY_CODE                        ,
t.BUSINESS_CODE      		,
t.ACCOUNT_NUMBER     		,
b.ACCOUNT_NUMBER,
t.COUNT                    ,
b.COUNT                    ,
t.MONEY         ,
b.MONEY         ,
t. REMARKS                 
FROM edw.py_cx_envbld_rural_ncpi_tltyp t  
LEFT JOIN 
    (SELECT * FROM edw.py_cx_envbld_rural_ncpi_tltyp 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 12 MONTH),'%Y%m') )b
    ON t.AREA_ID=b.AREA_ID AND t.ORG_ID=b.ORG_ID AND  t.AREA_TYPE_CODE=b.AREA_TYPE_CODE AND t.BUSINESS_CODE=b.BUSINESS_CODE AND t.PAY_CODE=b.PAY_CODE
    LEFT JOIN dmcode.`t_big_org` c
    ON t.org_id=c.org_id
    WHERE t.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
   CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
SET V_STEP_ID = 7;
 INSERT INTO adm.py_cx_envbld_rural_ncpi_tltyp (
DATA_DATE              ,
AREA_ID                ,
AREA_NAME              ,
ORG_ID                 ,
ORG_NAME               ,
AREA_TYPE_CODE         ,
COMPARE_TYPE_CODE      ,
PAY_CODE               ,
BUSINESS_CODE          ,
ACCOUNT_NUMBER         ,
COMPARE_ACCOUNT_NUMBER ,
COUNT                  ,
COMPARE_COUNT         ,
MONEY                 ,
COMPARE_MONEY         ,
REMARKS               
 )   
SELECT  
SUBSTR(V_ACCT_ID,1,6), 
t.AREA_ID   ,
t.AREA_NAME ,
t.ORG_ID,
t.ORG_ID,
t.AREA_TYPE_CODE,           
'2' AS COMPARE_TYPE_CODE,
t.PAY_CODE                        ,
t.BUSINESS_CODE      		,
t.ACCOUNT_NUMBER     		,
b.ACCOUNT_NUMBER,
t.COUNT                    ,
b.COUNT                    ,
t.MONEY         ,
b.MONEY         ,
t. REMARKS                 
FROM edw.py_cx_envbld_rural_ncpi_tltyp t  
LEFT JOIN 
    (SELECT * FROM edw.py_cx_envbld_rural_ncpi_tltyp 
    WHERE DATA_DATE=DATE_FORMAT(DATE_SUB(V_DATES,INTERVAL 3 MONTH),'%Y%m') )b
    ON t.AREA_ID=b.AREA_ID AND t.ORG_ID=b.ORG_ID AND  t.AREA_TYPE_CODE=b.AREA_TYPE_CODE AND t.BUSINESS_CODE=b.BUSINESS_CODE AND t.PAY_CODE=b.PAY_CODE
    LEFT JOIN dmcode.`t_big_org` c
    ON t.org_id=c.org_id
    WHERE t.DATA_DATE=SUBSTR(V_ACCT_ID,1,6);
    
   CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
END
;;
