-- ----------------------------
-- Procedure structure for py_cx_envbld_rural_static
-- ----------------------------
DROP PROCEDURE IF EXISTS `py_cx_envbld_rural_static`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `py_cx_envbld_rural_static`(
     IN V_ACCT_ID    VARCHAR(8),
     IN V_ORG_ID     VARCHAR(14),
     IN V_PARM_TYPE  VARCHAR(1),
     IN V_AREA_ID    VARCHAR(14)
)
BEGIN
    /*[DEFINER = { user | CURRENT_USER }]*/
/*
     Author    : 杨开泰
     Name      : adm.py_cx_envbld_rural_static.PRC
     Functions : 表1 农村地区基本情况
     Purpose   : 
     Revisions or Comments
     VER        DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-01-09  姓名           1.CREATE THE PROCEDURE
*/
    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'adm.py_cx_envbld_rural_static.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_RESULT        INT           DEFAULT 0;
    DECLARE V_DATES         VARCHAR(20)   DEFAULT 0;
    DECLARE V_STATE CHAR(1);
    /* ------------------------------------------------------------------------ */
    /* EXCEPTION HANDLER  */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_DATES = CONCAT(V_ACCT_ID,'01');
    /* ------------------------------------------------------------------------ */
    SET V_STEP_ID = 1;
    DELETE FROM edw.py_cx_envbld_rural_static WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- ods汇总到edw，添加地区名称，区分地区类型--插入农村数据
   SET V_STEP_ID = 2;
  INSERT INTO edw.py_cx_envbld_rural_static
               (
                 DATA_DATE      , -- 数据日期，账期         
                 AREA_ID        , -- 地区代码               
                 AREA_NAME      , -- 地区名称               
                 ORG_ID         , -- 填报单位               
                 AREA_TYPE_CODE , -- 地区类型编码1农村/2贫困
                 COUNTY_NUM     , -- 县级行政区总数         
                 COUNTRY_NUM    , -- 乡级行政区总数         
                 VILLAGE_NUM    , -- 村级行政区总数         
                 POPULATION_NUM , -- 人口数量               
                 OUTLETS_NUM    , -- 银行网点数量           
                 REMARKS         -- 备注                   
                )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    b.AREA_NAME,
    a.ROWS_ID,
    '1',
    a.COUNTY_NUM_COUNTRY,
    a.COUNTRY_NUM_COUNTRY,
    a.VILLAGE_NUM_COUNTRY,
    a.POPULATION_NUM_COUNTRY ,
    a.OUTLETS_NUM_COUNTRY,
    a.REMARKS
    FROM ods.py_cx_envbld_rural_static  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.AREA_ID=b.AREA_ID 
    where  b.AREA_TYPE_CODE='1'  AND a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6) ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
   
   -- ods汇总到edw，添加地区名称，区分地区类型--插入贫困数据
   SET V_STEP_ID = 3;
  INSERT INTO edw.py_cx_envbld_rural_static
               (
                 DATA_DATE      , -- 数据日期，账期         
                 AREA_ID        , -- 地区代码               
                 AREA_NAME      , -- 地区名称               
                 ORG_ID         , -- 填报单位               
                 AREA_TYPE_CODE , -- 地区类型编码1农村/2贫困
                 COUNTY_NUM     , -- 县级行政区总数         
                 COUNTRY_NUM    , -- 乡级行政区总数         
                 VILLAGE_NUM    , -- 村级行政区总数         
                 POPULATION_NUM , -- 人口数量               
                 OUTLETS_NUM    , -- 银行网点数量           
                 REMARKS         -- 备注                   
                )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    b.AREA_NAME,
    a.ROWS_ID,
    '2',
    a.COUNTY_NUM_ROOP,
    a.COUNTRY_NUM_POOR,
    a.VILLAGE_NUM_POOR,
    a.POPULATION_NUM_POOR ,
    a.OUTLETS_NUM_POOR,
    a.REMARKS
    FROM ods.py_cx_envbld_rural_static  a
    INNER JOIN edw.py_cx_area_ncpk_code b
    ON a.AREA_ID=b.AREA_ID 
    WHERE  b.AREA_TYPE_CODE='2'   AND a.DATA_DATE=SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
 
  SET V_STEP_ID = 3;
    DELETE FROM adm.py_cx_envbld_rural_static WHERE DATA_DATE = SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
    -- edw汇总到adm，生成报表展示adm表 
   SET V_STEP_ID = 4;
  INSERT INTO adm.py_cx_envbld_rural_static
               (
                 DATA_DATE            , -- 数据日期，账期          
                 AREA_ID              , -- 地区代码                
                 AREA_NAME            , -- 地区名称                 
                 ORG_ID               , -- 填报单位 
                 ORG_NAME             , -- 填报单位名称             
                 AREA_TYPE_CODE       , -- 地区类型编码1农村/2贫困
                 COUNTY_NUM           , -- 县级行政区总数  
                 COUNTRY_NUM          , -- 乡级行政区总数  
                 VILLAGE_NUM          , -- 村级行政区总数  
                 POPULATION_NUM       , -- 人口数量   
                 OUTLETS_NUM          , -- 银行网点数量   
                 REMARKS                -- 备注   
               )
                  SELECT
    SUBSTR(V_ACCT_ID,1,6),  
    a.AREA_ID,
    a.AREA_NAME,
    a.ORG_ID,
    c.org_dscr,
    a.AREA_TYPE_CODE,
    a.COUNTY_NUM,
    a.COUNTRY_NUM,
    a.VILLAGE_NUM,
    a.POPULATION_NUM,
    a.OUTLETS_NUM,
    a.REMARKS
    FROM edw.py_cx_envbld_rural_static  a
        LEFT JOIN dmcode.`t_big_org` c
    ON a.org_id=c.org_id
    where a.data_date=SUBSTR(V_ACCT_ID,1,6);
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
    
END
;;
