b.AREA_NO, -- 地市编码
a.model_area, -- 地市名称
a.ORG_NO,-- 行号
' ', -- 行名
CASE shop_type WHEN '01' THEN '手机PAY商户'  
               WHEN '02' THEN '二维码商户' 
               WHEN '03' THEN '双免商户'
               WHEN '04' THEN '手机PAY或二维码' END, -- 商户类型
a.new_trade_num, -- 单月交易总笔数      
new_trade_amout, -- 单月交易额      
tot_trade_num   , -- 累计交易总笔数
tot_trade_amout  -- 累计交易额      
FROM edw.py_cx_mod_trade a 
left join edw.py_cx_mod_trade_order b 
ON a.model_area=b.model_area
WHERE  b.area_no IS NOT NULL  
and shop_type in ('01','02','03','04')
and DATA_DATE=SUBSTR(V_ACCT_ID,1,6)    ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 /* ------------------------------------------------------------------------ */
    
    
    
END
;;
