-- ----------------------------
-- Procedure structure for py_cx_mth_cash_active_area
-- ----------------------------
DROP PROCEDURE IF EXISTS `py_cx_mth_cash_active_area`;
delimiter ;;
CREATE DEFINER=`dwbi`@`%` PROCEDURE `py_cx_mth_cash_active_area`(
     IN  V_ACCT_ID VARCHAR(8)
    ,OUT P_RESULT    INT
)
BEGIN
    

    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.py_cx_mth_cash_active_area.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    
    SET V_STEP_ID = 1;
    DELETE FROM adm.py_cx_mth_cash_active_area ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    
   SET V_STEP_ID = 2;
 INSERT INTO adm.`py_cx_mth_cash_active_area` 
SELECT 
  a.trade_date,
  b.area_code,
  b.city_code,
  SUM(num) AS num,
  SUM(act_num) AS act_num,
  SUM(no_act_num) AS no_act_num 
FROM
  (SELECT 
    trade_date,
    village_code,
    '0' AS num,
    COUNT(DISTINCT shop_num) AS act_num,
    '0' AS no_act_num 
  FROM
    adm.px_cx_mth_cash_servinfo 
  WHERE trade_num >= 20 
  GROUP BY trade_date,
    village_code,TRADE_TYPE 
  UNION
  ALL 
  SELECT 
    trade_date,
    village_code,
    '0' AS num,
    '0'AS act_num,
    COUNT(DISTINCT shop_num) AS no_act_num 
  FROM
    adm.px_cx_mth_cash_servinfo 
  GROUP BY village_code,
    trade_date 
  HAVING (sum(trade_num) < 5)
 UNION ALL
 SELECT 
    trade_date,
    village_code,
    COUNT(DISTINCT shop_num) AS num,
    '0'AS act_num,
    '0' AS no_act_num 
  FROM
    adm.px_cx_mth_cash_servinfo 
  WHERE  trade_num < 20 
  GROUP BY village_code,
    trade_date 
  HAVING MAX(trade_num) > 5  
  ) a 
  INNER JOIN edw.py_cx_area_code b 
    ON a.village_code = b.nbh_code
    WHERE  a.trade_date=(SELECT MAX(trade_date) FROM adm.px_cx_mth_cash_servinfo )
GROUP BY a.trade_date,
  b.area_code,
  b.city_code ;
    CALL ETL.EDW_PROC_TRACE_LOG(V_ACCT_ID,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for PY_CX_MTH_CASH_SERVINFO_active
-- ----------------------------
