DROP PROCEDURE IF EXISTS `P_ANA_SMALL_MICRO_ENTERPRISE`;
delimiter ;;
CREATE DEFINER=`dwbi`@`%` PROCEDURE `P_ANA_SMALL_MICRO_ENTERPRISE`(IN P_DATA_DATE VARCHAR(8),OUT P_RESULT   INT)
BEGIN
/*
| Author :严锦涛
| Name :ADM.ana_glr_mth_small_micro_map
| FUNCTION:
| Purpose:货币信贷-专题分析-小微企业分析-小微企业分析
|         EDW.GLR_MPA_CBRC_3302|MPA大中小企业贷款统计表|ADM.ANA_GLR_MTH_SMALL_MICRO
| VER         DATE        AUTHOR           DESCRIPTION
| ---------  ----------  ---------------  ------------------------------------
| 1.0        2019-01-02     严锦涛        1.CREATES THE PROCEDURE
*/     
    DECLARE V_PROC_NAME VARCHAR(200) DEFAULT 'ADM.P_ANA_SMALL_MICRO_ENTERPRISE.prc';
    DECLARE V_STEP INT DEFAULT 0;
    DECLARE V_START_TIME VARCHAR(20) DEFAULT NOW();
    DECLARE V_DATA_DATE VARCHAR(6) DEFAULT SUBSTR(P_DATA_DATE,1,6);    
    DECLARE V_DATA_DATE_P VARCHAR(6) DEFAULT SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 1 MONTH),'%Y%m%d'),1,6);
    
    DECLARE V_DATA_DATE_L VARCHAR(6) DEFAULT SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 12 MONTH),'%Y%m%d'),1,6);
    DECLARE V_DATA_DATE_L_P VARCHAR(6) DEFAULT SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 13 MONTH),'%Y%m%d'),1,6);
    
    DECLARE V_DATA_END_Y VARCHAR(6) DEFAULT CONCAT(SUBSTR(P_DATA_DATE,1,4)-1,'01');          #上年末
    DECLARE V_DATA_END_Y_L VARCHAR(6) DEFAULT CONCAT(SUBSTR(P_DATA_DATE,1,4)-2,'01');        #上上年末
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    SET V_STEP:='1';
    DELETE  FROM ADM.ANA_GLR_MTH_SMALL_MICRO WHERE FISCAL_MTH = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='2';
    insert into ADM.ANA_GLR_MTH_SMALL_MICRO (
	 FISCAL_DATE             #月份_date
	,FISCAL_MTH              #月份
	,CITY_ID                 #市编码
	,CITY_NAME               #市名称
	,AREA_NO_ID              #县编码
	,AREA_DSCR               #县名称
	,DIM_CODE                #纬度编码
	,DIM_DSCR                #纬度描述
	,DIM_TYPE                #纬度类型
	,SERVICE_TYPE
	,LOAN_AMOUNT             #贷款余额
	,LOAN_AMOUNT_LY          #同期贷款余额
     )
    #1. 01 分行业投向(一级)
    select 
        CONCAT(V_DATA_DATE,'01')       AS    FISCAL_DATE
       ,V_DATA_DATE                    AS    FISCAL_MTH
       ,'50000'                        AS    CITY_ID
       ,'重庆市'                       as    CITY_NAME
       ,R.AREA_NO_ID                   AS    AREA_NO_ID
       ,R.AREA_DSCR                    AS    AREA_DSCR
       ,D.DIM_ID                       as    DIM_CODE
       ,D.DIM_DESC                     as    DIM_DSCR
       ,'行业类型'                     as    DIM_TYPE
       ,'贷款余额'
       ,sum(case when t.data_date = v_data_date then ifnull(t.balance_cny,0) else 0 end )/10000   as    LOAN_REMAIN_LM
       ,SUM(CASE WHEN t.data_date = V_DATA_DATE_L THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 as    LOAN_REMAIN_LY
    from EDW.GLR_MPA_CBRC_3302 T 
    LEFT JOIN DMCODE.t_org_biz_lvl O 
    ON T.ORG_NO = O.ORG_ID
    LEFT JOIN DMCODE.T_AREA_CODE R
    on O.area_no_id = R.area_no_id
    INNER JOIN EDW.RPT_INDUST_GUARN_MAS_MAPPING D
    ON T.KPI_CODE = D.MAPPING_ID
    WHERE t.kpi_code IN ('33421','33422','33423','33424','33425','33426','33427','33428','33429','33430','33431','33432','33433','33434','33435','33436','33437','33438','33439','33440','33441','33442','33443','33444','33471','33472','33473','33474','33475','33476','33477','33478','33479','33480','33481','33482','33483','33484','33485','33486','33487','33488','33489','33490','33491','33492','33493','33494')
    and length(D.dim_id)=1    
    GROUP BY 
         D.DIM_ID             
	,D.DIM_DESC     
	,R.AREA_NO_ID  
	,R.AREA_DSCR   
    
    UNION ALL
    
    SELECT 
        CONCAT(V_DATA_DATE,'01')       AS    FISCAL_DATE
       ,V_DATA_DATE                    AS    FISCAL_MTH
       ,'50000'                        AS    CITY_ID
       ,'重庆市'                       AS    CITY_NAME
       ,R.AREA_NO_ID                   AS    AREA_NO_ID
       ,R.AREA_DSCR                    AS    AREA_DSCR
       ,D.DIM_ID                       AS    DIM_CODE
       ,D.DIM_DESC                     AS    DIM_DSCR
       ,'行业类型'                     AS    DIM_TYPE
       ,'当月新增'
