    LEFT JOIN DMCODE.T_AREA_CODE R
    ON O.area_no_id = R.area_no_id
    INNER JOIN EDW.RPT_INDUST_GUARN_MAS_MAPPING D
    ON T.KPI_CODE = D.MAPPING_ID
    #分担保方式
    WHERE t.kpi_code IN ('33565','33566','33567','33573','33574','33575')
    GROUP BY 
	 D.DIM_ID             
	,D.DIM_DESC     
	,R.AREA_NO_ID  
	,R.AREA_DSCR    
    union all
    
    SELECT 
        CONCAT(V_DATA_DATE,'01')       AS    FISCAL_DATE
       ,V_DATA_DATE                    AS    FISCAL_MTH
       ,'50000'                        AS    CITY_ID
       ,'重庆市'                       AS    CITY_NAME
       ,R.AREA_NO_ID                   AS    AREA_NO_ID
       ,R.AREA_DSCR                    AS    AREA_DSCR
       ,D.DIM_ID                       AS    DIM_CODE
       ,D.DIM_DESC                     AS    DIM_DSCR
       ,'担保方式'                     AS    DIM_TYPE
       ,'当年新增'
       ,SUM(CASE WHEN t.data_date = v_data_date THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 -SUM(CASE WHEN t.data_date = v_data_date THEN IFNULL(t.BALANCE_BEGIN_Y,0) ELSE 0 END )/10000         AS    LOAN_REMAIN_LM
       ,SUM(CASE WHEN t.data_date = V_DATA_DATE_L THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 - SUM(CASE WHEN t.data_date = V_DATA_DATE_L THEN IFNULL(t.BALANCE_BEGIN_Y,0) ELSE 0 END )/10000    AS    LOAN_REMAIN_LY
    FROM EDW.GLR_MPA_CBRC_3302 T 
    LEFT JOIN DMCODE.t_org_biz_lvl O 
