       ,V_DATA_DATE                    AS    FISCAL_MTH
       ,'50000'                        AS    CITY_ID
       ,'重庆市'                       AS    CITY_NAME
       ,R.AREA_NO_ID                   AS    AREA_NO_ID
       ,R.AREA_DSCR                    AS    AREA_DSCR
       ,D.DIM_ID                       AS    DIM_CODE
       ,D.DIM_DESC                     AS    DIM_DSCR
       ,'贷款质量'                     AS    DIM_TYPE
       ,'当月新增'
       ,SUM(CASE WHEN t.data_date = v_data_date THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 -SUM(CASE WHEN t.data_date = v_data_date_p THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000        AS    LOAN_REMAIN_LM
       ,SUM(CASE WHEN t.data_date = V_DATA_DATE_L THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 - SUM(CASE WHEN t.data_date = V_DATA_DATE_L_P THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000   AS    LOAN_REMAIN_LY
    FROM EDW.GLR_MPA_CBRC_3302 T 
    LEFT JOIN DMCODE.t_org_biz_lvl O 
    ON T.ORG_NO = O.ORG_ID
    LEFT JOIN DMCODE.T_AREA_CODE R
    ON O.area_no_id = R.area_no_id
    INNER JOIN EDW.RPT_INDUST_GUARN_MAS_MAPPING D
    ON T.KPI_CODE = D.MAPPING_ID
    #分贷款质量
    WHERE t.kpi_code IN ('33533','33534','33535','33536','33537','33545','33546','33547','33548','33549')
     GROUP BY 
        D.DIM_ID             
	,D.DIM_DESC     
	,R.AREA_NO_ID  
	,R.AREA_DSCR   
    
    union all
    
    SELECT 
        CONCAT(V_DATA_DATE,'01')       AS    FISCAL_DATE
       ,V_DATA_DATE                    AS    FISCAL_MTH
       ,'50000'                        AS    CITY_ID
       ,'重庆市'                       AS    CITY_NAME
       ,R.AREA_NO_ID                   AS    AREA_NO_ID
       ,R.AREA_DSCR                    AS    AREA_DSCR
       ,D.DIM_ID                       AS    DIM_CODE
       ,D.DIM_DESC                     AS    DIM_DSCR
       ,'贷款质量'                     AS    DIM_TYPE
       ,'当年新增'
       ,SUM(CASE WHEN t.data_date = v_data_date THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 -SUM(CASE WHEN t.data_date = v_data_date THEN IFNULL(t.BALANCE_BEGIN_Y,0) ELSE 0 END )/10000         AS    LOAN_REMAIN_LM
       ,SUM(CASE WHEN t.data_date = V_DATA_DATE_L THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 - SUM(CASE WHEN t.data_date = V_DATA_DATE_L THEN IFNULL(t.BALANCE_BEGIN_Y,0) ELSE 0 END )/10000    AS    LOAN_REMAIN_LY
   FROM EDW.GLR_MPA_CBRC_3302 T 
    LEFT JOIN DMCODE.t_org_biz_lvl O 
    ON T.ORG_NO = O.ORG_ID
    LEFT JOIN DMCODE.T_AREA_CODE R
    ON O.area_no_id = R.area_no_id
    INNER JOIN EDW.RPT_INDUST_GUARN_MAS_MAPPING D
    ON T.KPI_CODE = D.MAPPING_ID
    #分贷款质量
    WHERE t.kpi_code IN ('33533','33534','33535','33536','33537','33545','33546','33547','33548','33549')
    GROUP BY 
        D.DIM_ID             
	,D.DIM_DESC     
	,R.AREA_NO_ID  
	,R.AREA_DSCR   
    ;
    
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    
    #====================================================================================================================================
    SET V_STEP:='3';    
    DELETE  FROM ADM.ANA_GLR_MTH_SMALL_MICRO_MAP WHERE FISCAL_MTH = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='4';    
    insert into ADM.ANA_GLR_MTH_SMALL_MICRO_MAP (
	 FISCAL_DATE             #月份_date
	,FISCAL_MTH              #月份
	,ISO_ID                  #区域代码
	,AREA_NO_ID              #县编码
	,AREA_DSCR               #县名称
	,SERVICE_TYPE            #业务统计类型
	,LOAN_AMOUNT             #贷款余额
	,LOAN_AMOUNT_LY          #去年同期贷款余额
    )
    SELECT 
        CONCAT(V_DATA_DATE,'01')       AS    FISCAL_DATE
       ,V_DATA_DATE                    AS    FISCAL_MTH
       ,case when R.AREA_NO_ID = '500000' then '5000'        
             else R.AREA_NO_ID end     AS    ISO_ID
       ,R.AREA_NO_ID 
       ,R.AREA_DSCR  
       ,'贷款余额'
       ,SUM(CASE WHEN T.DATA_DATE = V_DATA_DATE THEN IFNULL(balance_cny,0) ELSE 0 END )/10000      AS LOAN_AMOUNT
       ,SUM(CASE WHEN T.DATA_DATE = V_DATA_DATE_L THEN IFNULL(balance_cny,0) ELSE 0 END )/10000    AS LOAN_AMOUNT_LY
    
    FROM EDW.GLR_MPA_CBRC_3302 T 
    LEFT JOIN DMCODE.t_org_biz_lvl O 
    ON T.ORG_NO = O.ORG_ID
    LEFT JOIN DMCODE.T_AREA_CODE R
    ON O.area_no_id = R.area_no_id
    WHERE T.KPI_CODE IN ('33533','33534','33535','33536','33537','33545','33546','33547','33548','33549')
    
    union all
    
    SELECT 
       CONCAT(V_DATA_DATE,'01')        AS    FISCAL_DATE
       ,V_DATA_DATE                    AS    FISCAL_MTH
       ,CASE WHEN R.AREA_NO_ID = '500000' THEN '5000'        
             ELSE R.AREA_NO_ID END     AS    ISO_ID
       ,R.AREA_NO_ID 
       ,R.AREA_DSCR  
       ,'当月新增'
       ,SUM(CASE WHEN t.data_date = v_data_date THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 -SUM(CASE WHEN t.data_date = v_data_date_p THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000        AS    LOAN_REMAIN_LM
       ,SUM(CASE WHEN t.data_date = V_DATA_DATE_L THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 - SUM(CASE WHEN t.data_date = V_DATA_DATE_L_P THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000   AS    LOAN_REMAIN_LY
   
    FROM EDW.GLR_MPA_CBRC_3302 T 
    LEFT JOIN DMCODE.t_org_biz_lvl O 
    ON T.ORG_NO = O.ORG_ID
    LEFT JOIN DMCODE.T_AREA_CODE R
    ON O.area_no_id = R.area_no_id
    WHERE T.KPI_CODE IN ('33533','33534','33535','33536','33537','33545','33546','33547','33548','33549')
    
    union all
    
    SELECT 
       CONCAT(V_DATA_DATE,'01')        AS    FISCAL_DATE
       ,V_DATA_DATE                    AS    FISCAL_MTH
       ,CASE WHEN R.AREA_NO_ID = '500000' THEN '5000'        
             ELSE R.AREA_NO_ID END     AS    ISO_ID
       ,R.AREA_NO_ID 
       ,R.AREA_DSCR  
       ,'当年新增'
       ,SUM(CASE WHEN t.data_date = v_data_date THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 -SUM(CASE WHEN t.data_date = v_data_date THEN IFNULL(t.BALANCE_BEGIN_Y,0) ELSE 0 END )/10000        AS    LOAN_REMAIN_LM
       ,SUM(CASE WHEN t.data_date = V_DATA_DATE_L THEN IFNULL(t.balance_cny,0) ELSE 0 END )/10000 - SUM(CASE WHEN t.data_date = V_DATA_DATE_L THEN IFNULL(t.BALANCE_BEGIN_Y,0) ELSE 0 END )/10000   AS    LOAN_REMAIN_L
    FROM EDW.GLR_MPA_CBRC_3302 T 
    LEFT JOIN DMCODE.t_org_biz_lvl O 
    ON T.ORG_NO = O.ORG_ID
    LEFT JOIN DMCODE.T_AREA_CODE R
    ON O.area_no_id = R.area_no_id
    WHERE T.KPI_CODE IN ('33533','33534','33535','33536','33537','33545','33546','33547','33548','33549')
    ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    
    
    #===========================================================================================
    
    SET V_STEP:='5';    
    DELETE  FROM ADM.ANA_GLR_MTH_SMALL_MICRO_BAD WHERE FISCAL_MTH = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='6';    
    insert into ADM.ANA_GLR_MTH_SMALL_MICRO_BAD(
	 FISCAL_DATE           #月份_date
	,FISCAL_MTH            #月份
	,ORG_ID                #金融机构编码
	,ORG_NAME              #金融机构名称
	,BAD_LOAN_RATE         #不良贷款率
	,BAD_LOAN_RATE_RANK    #不良贷款率排序
	,RANK_DSCR             #排序描述
	)
	
    select 
        result.FISCAL_DATE
       ,result.FISCAL_MTH
       ,result.ORG_ID
       ,result.ORG_NAME
       ,result.BAD_LOAN
       ,CASE WHEN result.rank=0 THEN 1 ELSE result.rank END 
       ,CONCAT('排名:',result.rank) 
    
    from (
	    SELECT 
		tmp.FISCAL_DATE
	       ,tmp.FISCAL_MTH
	       ,tmp.ORG_ID
	       ,tmp.ORG_NAME
	       ,tmp.BAD_LOAN
	       ,CASE WHEN @rowtotal = tmp.BAD_LOAN  THEN @rownum
		     WHEN @rowtotal := tmp.BAD_LOAN THEN @rownum :=@rownum + 1
		     WHEN @rowtotal = 0 THEN @rownum :=@rownum + 1
	        END AS rank
	    
	    FROM (
		    SELECT 
		       CONCAT(V_DATA_DATE,'01')        AS    FISCAL_DATE
		       ,V_DATA_DATE                    AS    FISCAL_MTH
		       ,T.ORG_NO                       AS    ORG_ID
		       ,O.ORG_DSCR                     AS    ORG_NAME
		       ,CASE WHEN SUM(IFNULL(balance_cny,0)) = 0 THEN 0 ELSE 
		       SUM(CASE WHEN M.DIM_ID IN ('ZA3','ZA4','ZA5') THEN ifnull(balance_cny,0) ELSE 0 END)/SUM(IFNULL(balance_cny,0))  END   AS    BAD_LOAN
		    
		    FROM EDW.GLR_MPA_CBRC_3302 T 
		    LEFT JOIN EDW.RPT_INDUST_GUARN_MAS_MAPPING M
		    ON T.KPI_CODE = M.MAPPING_ID
		    left join DMCODE.t_org_biz_lvl O
		    ON T.ORG_NO = O.ORG_ID
		    WHERE T.KPI_CODE IN ('33533','33534','33535','33536','33537','33545','33546','33547','33548','33549')
		    AND T.DATA_DATE = V_DATA_DATE 
		    GROUP BY V_DATA_DATE
			,T.ORG_NO      
			,O.ORG_DSCR    
		    ORDER BY SUM(IFNULL(balance_cny,0)) DESC   #必须加排序
	    ) TMP ,
	    (SELECT @rownum := 0 ,@rowtotal := NULL) r
    
    ) result 
    ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    
    #==========================================小微企业贷款余额占比分析表=================================================    
    SET V_STEP:='7';    
    DELETE  FROM ADM.ANA_GLR_MTH_SMALL_MICRO_RATE WHERE FISCAL_MTH = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='8';
    insert into ADM.ANA_GLR_MTH_SMALL_MICRO_RATE (
	 FISCAL_DATE            #日期
	,FISCAL_MTH             #月份
	,SERVICE_TYPE           #业务统计类型
	,LOANS_COUNT            #小微企业贷款金额
	,LOANS_TOTAL            #各项贷款金额
	)
    SELECT 
         DS1.FISCAL_DATE
        ,DS1.FISCAL_MTH
        ,DS1.SERVICE_TYPE
        ,DS1.LOANS_COUNT
        ,DS2.loan_all
    FROM (
    select
         CONCAT(V_DATA_DATE,'01') AS FISCAL_DATE
	,V_DATA_DATE              AS FISCAL_MTH
	,'贷款余额'               AS SERVICE_TYPE
	,sum(IFNULL(BALANCESMALL,0)+IFNULL(BALANCELITTLE,0)) AS LOANS_COUNT
    FROM EDW.SMALL_AND_MEDIUM_SIZED_ENTERPRISES
    WHERE ROWS_ID = 4
    AND DATA_DATE = V_DATA_DATE 
    ) DS1 
    JOIN 
    (
       SELECT 
         SUM(IFNULL(loan_balance,0)) AS loan_all
       FROM EDW.GLR_MPA_ALL_CNY_CREDIT T    #重庆市全金融机构人民币信贷收支合并表 各项贷款
       WHERE t.rows_id = 3
        AND data_date = v_data_date 
    )DS2
    
    UNION ALL
    
    SELECT 
         DS3.FISCAL_DATE
        ,DS3.FISCAL_MTH
        ,DS3.SERVICE_TYPE
        ,DS3.LOANS_COUNT
        ,DS4.loan_all
    FROM (
    SELECT
         CONCAT(V_DATA_DATE,'01') AS FISCAL_DATE
	,V_DATA_DATE              AS FISCAL_MTH
	,'当月新增'               AS SERVICE_TYPE
	,SUM(case when data_date = v_data_date then IFNULL(BALANCESMALL,0)+IFNULL(BALANCELITTLE,0) else 0 end ) - SUM(CASE WHEN data_date = v_data_date_p THEN IFNULL(BALANCESMALL,0)+IFNULL(BALANCELITTLE,0) ELSE 0 END ) AS LOANS_COUNT
    FROM EDW.SMALL_AND_MEDIUM_SIZED_ENTERPRISES
    WHERE ROWS_ID = 4
    ) DS3
    JOIN 
    (
       SELECT 
         SUM(CASE WHEN data_date = v_data_date THEN IFNULL(loan_balance,0) else 0 end ) - SUM(CASE WHEN data_date = v_data_date_p THEN IFNULL(loan_balance,0) ELSE 0 END ) AS loan_all
       FROM EDW.GLR_MPA_ALL_CNY_CREDIT T    #重庆市全金融机构人民币信贷收支合并表 各项贷款
       WHERE t.rows_id = 3
    )DS4
        
    union  all 
    
        SELECT 
         DS5.FISCAL_DATE
        ,DS5.FISCAL_MTH
        ,DS5.SERVICE_TYPE
        ,DS5.LOANS_COUNT
        ,DS6.loan_all
    FROM (
    SELECT
         CONCAT(V_DATA_DATE,'01') AS FISCAL_DATE
	,V_DATA_DATE              AS FISCAL_MTH
	,'当年新增'               AS SERVICE_TYPE
	,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(BALANCESMALL,0)+IFNULL(BALANCELITTLE,0) ELSE 0 END ) - SUM(CASE WHEN data_date = V_DATA_END_Y THEN IFNULL(BALANCESMALL,0)+IFNULL(BALANCELITTLE,0) ELSE 0 END ) AS LOANS_COUNT
    FROM EDW.SMALL_AND_MEDIUM_SIZED_ENTERPRISES
    WHERE ROWS_ID = 4
    ) DS5
    JOIN 
    (
       SELECT 
         SUM(CASE WHEN data_date = v_data_date THEN IFNULL(loan_balance,0) ELSE 0 END ) - SUM(CASE WHEN data_date = V_DATA_END_Y THEN IFNULL(loan_balance,0) ELSE 0 END ) AS loan_all
       FROM EDW.GLR_MPA_ALL_CNY_CREDIT T    #重庆市全金融机构人民币信贷收支合并表 各项贷款
       WHERE t.rows_id = 3
    )DS6
    ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    
    
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_ANA_SUST_MTH_CREDIT_RECE_PAY_AREA
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_ANA_SUST_MTH_CREDIT_RECE_PAY_AREA`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_ANA_SUST_MTH_CREDIT_RECE_PAY_AREA`(in V_DATA_DATE varchar(10))
BEGIN
/*信贷收支总览   地图*/
delete FROM adm.ana_sust_mth_credit_rece_pay_area WHERE DATA_DATE=DATE_FORMAT(V_DATA_DATE,'%Y%m');
insert into adm.ana_sust_mth_credit_rece_pay_area
SELECT 
	DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-01')      AS DATA_DATE,
	DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y%m')          AS DATA_MTH,
	REVERSE(cast(REVERSE(b.AREA_ID) as signed))           AS ISO_ID,
	b.AREA_DSCR					      AS AREA_DSCR,
	100000000*(a.DEPB_BAL)				      as DEPB_BAL,
	100000000*(a.LOAN_BAL)				      as LOAN_BAL
FROM
	ods.glr_mpa_all_dist_depb_loan_dtl1 a
LEFT JOIN 
	dmcode.t_area_code_temp b
ON a.ORG_NAME = b.AREA_DSCR 
WHERE a.DATA_DATE = date_format(V_DATA_DATE,'%Y%m');
	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_ANA_SUST_MTH_CREDIT_RECE_PAY_STRUC
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_ANA_SUST_MTH_CREDIT_RECE_PAY_STRUC`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_ANA_SUST_MTH_CREDIT_RECE_PAY_STRUC`(in v_data_date varchar(10))
BEGIN
/*存贷主要项目在各期余额*/
DELETE FROM adm.ana_sust_mth_credit_rece_pay_struc WHERE DATA_DATE=DATE_FORMAT(V_DATA_DATE,'%Y%m');
insert into adm.ana_sust_mth_credit_rece_pay_struc
SELECT 
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-01')      AS DATA_DATE,
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y%m')          AS DATA_MTH,
b.SERVICE_TYPE 					      AS SERVICE_TYPE,
b.ITEM_CATEGORY_CODE				      AS ITEM_CATEGORY_CODE,
b.ITEM_CATEGORY,
(a.DEPB_BALANCE)*100000000			      AS DEPB_BALANCE
FROM ods.glr_mpa_all_cny_credit_dtl1 a
LEFT JOIN 
adm.ana_sust_cm_service_type b
ON a.PROJECT1 LIKE CONCAT('%',b.ITEM_CATEGORY)
WHERE a.DATA_DATE = DATE_FORMAT(v_data_date,'%Y%m')
AND (a.PROJECT1 LIKE '%住户存款'
OR a.PROJECT1 LIKE '%非金融企业存款'
OR a.PROJECT1 LIKE '%机关团体存款'
OR a.PROJECT1 LIKE '%财政性存款'
OR a.PROJECT1 LIKE '%非银行业金融机构存款'
OR a.PROJECT1 LIKE '%境外存款')
UNION ALL
SELECT 
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-01')      AS DATA_DATE,
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y%m')          AS DATA_MTH,
b.SERVICE_TYPE 					      AS SERVICE_TYPE,
b.ITEM_CATEGORY_CODE				      AS ITEM_CATEGORY_CODE,
b.ITEM_CATEGORY,
(a.LOAN_BALANCE)*100000000			      AS LOAN_BALANCE
FROM ods.glr_mpa_all_cny_credit_dtl1 a
LEFT JOIN 
adm.ana_sust_cm_service_type b
ON a.PROJECT2 LIKE CONCAT('%',b.ITEM_CATEGORY)
WHERE a.DATA_DATE = DATE_FORMAT(v_data_date,'%Y%m')
AND (a.PROJECT2 LIKE '%住户贷款'
OR a.PROJECT2 LIKE '%非金融企业及机关团体贷款'
OR a.PROJECT2 LIKE '%非银行业金融机构贷款'
OR a.PROJECT2 LIKE '%境外贷款'
)
UNION ALL
SELECT 
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-01')      AS DATA_DATE,
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y%m')          AS DATA_MTH,
b.SERVICE_TYPE 					      AS SERVICE_TYPE,
b.ITEM_CATEGORY_CODE				      AS ITEM_CATEGORY_CODE,
b.ITEM_CATEGORY,
(a.BALANCE)*100000000				      AS BALANCE
FROM ods.GLR_EDS_SPE_DATA_INDUS_DTL1 a
LEFT JOIN 
adm.ana_sust_cm_service_type b
ON a.PROJECT LIKE CONCAT('%',b.ITEM_CATEGORY)
WHERE a.DATA_DATE = DATE_FORMAT(v_data_date,'%Y%m')
UNION ALL
SELECT 
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-01')      AS DATA_DATE,
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y%m')          AS DATA_MTH,
b.SERVICE_TYPE 					      AS SERVICE_TYPE,
b.ITEM_CATEGORY_CODE				      AS ITEM_CATEGORY_CODE,
b.ITEM_CATEGORY,
(a.BALANCE)*100000000				      AS BALANCE
FROM ods.sust_institutions_containing_foreign_capital a
JOIN 
adm.ana_sust_cm_service_type b
ON a.PROJECT_DESC LIKE CONCAT('%',b.ITEM_CATEGORY)
WHERE a.DATA_DATE = DATE_FORMAT(v_data_date,'%Y%m');
	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_ANA_SUST_MTH_CREDIT_RECE_PAY_TIMES
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_ANA_SUST_MTH_CREDIT_RECE_PAY_TIMES`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_ANA_SUST_MTH_CREDIT_RECE_PAY_TIMES`(in v_data_date varchar(10))
BEGIN
/*信贷总览  收支时序表*/
DELETE FROM adm.ana_sust_mth_credit_rece_pay_times WHERE DATA_DATE=DATE_FORMAT(V_DATA_DATE,'%Y%m');
insert into adm.ana_sust_mth_credit_rece_pay_times
SELECT 
	DATE_FORMAT(CONCAT(c.DATA_DATE,'01'),'%Y-%m-01') 	 AS  data_date,        -- 数据账期
	DATE_FORMAT(CONCAT(c.DATA_DATE,'01'),'%Y%m')       	 AS  date_mth,	       -- 月份
	c.BWB_BALANCE*100000000				         AS  DEP_BAL,	       -- 各项存款（本外币）本期余额（元）
	c.BWB_LAST_MONTH*100000000				 AS  DEP_BAL_LM,       -- 存款比上月（元）
	c.BWB_YEAR_ON_YEAR*100000000				 AS  DEP_BAL_LY_E,     -- 存款比年初（元）
	c.BWB_OF_YEAR/100					 AS  DEP_BAL_TB_RATE,  -- 存款同比增速
	d.BWB_BALANCE*100000000					 AS  LOAN_BAL,         -- 各项贷款（本外币）本期余额（元）
	d.BWB_LAST_MONTH*100000000				 AS  LOAN_BAL_LM,      -- 贷款比上月（元）
	d.BWB_YEAR_ON_YEAR*100000000	   			 AS  LOAN_BAL_LY_E,    -- 贷款比年初（元）
	d.BWB_OF_YEAR/100					 AS  LOAN_BAL_TB_RATE  -- 贷款同比增速
FROM
	ods.major_deposit_items_new  c
JOIN ods.main_securities_projects d
ON c.ROWS_ID = d.ROWS_ID
WHERE c.data_date = date_format(V_DATA_DATE,'%Y%m')
and d.data_date = DATE_FORMAT(V_DATA_DATE,'%Y%m')
AND c.PROJECT = '各项存款'
AND d.PROJECT = '各项贷款';
	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_ANA_SUST_MTH_ENTERPRISE_SURVEY
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_ANA_SUST_MTH_ENTERPRISE_SURVEY`;
delimiter ;;
CREATE DEFINER=`dis`@`%` PROCEDURE `P_ANA_SUST_MTH_ENTERPRISE_SURVEY`(
IN V_DATA_DATE VARCHAR(6), 
IN E_ID VARCHAR(8), 
IN N_ID VARCHAR(5) 
)
BEGIN

         

	DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.P_ANA_SUST_MTH_ENTERPRISE_SURVEY.PRC';
	DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
	DECLARE V_STEP_ID       INT           DEFAULT 0;
	DECLARE P_DATA_DATE     VARCHAR(8)    DEFAULT V_DATA_DATE;

	DECLARE DONE            INT DEFAULT FALSE;	
	DECLARE V_NORM_ID       VARCHAR(100);		
	DECLARE V_NORM_NAME     VARCHAR(100);		
	DECLARE V_PLAN_ID       VARCHAR(100);		
	DECLARE ENT_ID          VARCHAR(100);		
	DECLARE ENT_NAME        VARCHAR(100);           
	DECLARE V_SQL_INSERT    LONGTEXT  DEFAULT '';	
	DECLARE CUR_ENTERPRISE  CURSOR FOR SELECT ENTERPRISE_ID,ENTERPRISE_name FROM ADM.SUST_ENTERPRISE_VIEW where ENTERPRISE_name is not null; 
	DECLARE CUR_NORM        CURSOR FOR SELECT NORM_ID,NORM_NAME FROM ADM.SUST_STANDARD_NORM_VIEW where norm_id is not null; 
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET DONE:= TRUE;
	

	
	   DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN
	GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
	UPDATE transfer.tf_business_launch_record SET RUN_STATUS = 3 WHERE ACCT_DATE = P_DATA_DATE;
	CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_NORM_ID,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
	END;
	
	
	SET V_STEP_ID = 1;
	DROP VIEW IF EXISTS ADM.SUST_ENTERPRISE_VIEW;
	
	SET V_STEP_ID = 2;
	SET @SQLSTR = "CREATE VIEW ADM.SUST_ENTERPRISE_VIEW AS ";
	
	IF E_ID = '' 
	THEN
	SET @SQLSTR = CONCAT(@SQLSTR,"SELECT DISTINCT ENTERPRISE_ID,ENTERPRISE_name FROM ADM.ANA_SUST_MTH_ENTERPRISE_SURVEY_TEMP "," WHERE DATA_DATE = ",V_DATA_DATE,";");
	ELSE 
	SET @SQLSTR = CONCAT(@SQLSTR,"SELECT DISTINCT ENTERPRISE_ID,ENTERPRISE_name FROM ADM.ANA_SUST_MTH_ENTERPRISE_SURVEY_TEMP WHERE ENTERPRISE_ID = '",E_ID,"';");
	END IF;
	
	PREPARE SQLSTR FROM @SQLSTR;
	
	EXECUTE SQLSTR;
	
	DEALLOCATE PREPARE SQLSTR;
	
	set V_STEP_ID = 3;
	
	DROP VIEW IF EXISTS ADM.SUST_STANDARD_NORM_VIEW;
	
	SET V_STEP_ID = 4;
	SET @SQLTXT = "CREATE VIEW ADM.SUST_STANDARD_NORM_VIEW AS ";
	IF N_ID = ''
	THEN 
	SET @SQLTXT = CONCAT(@SQLTXT,"SELECT NORM_ID,NORM_NAME FROM ADM.SUST_STANDARD_NORM ORDER BY ID;");
	ELSE 
	SET @SQLTXT = CONCAT(@SQLTXT,"SELECT NORM_ID,NORM_NAME FROM ADM.SUST_STANDARD_NORM WHERE NORM_ID = '",N_ID,"'ORDER BY ID;");
	END IF;
	
	PREPARE SQLTXT FROM @SQLTXT;
	EXECUTE SQLTXT;
	DEALLOCATE PREPARE SQLTXT;
	
	SET V_STEP_ID = 5;
	
	
	OPEN CUR_ENTERPRISE;
		ENTLOOP:LOOP
			FETCH CUR_ENTERPRISE INTO ENT_ID,ENT_NAME;
			IF DONE THEN
			LEAVE ENTLOOP;
			END IF;
			
			OPEN CUR_NORM;
				NORMLOOP:LOOP
					FETCH CUR_NORM INTO V_NORM_ID,V_NORM_NAME;
					IF DONE THEN
					LEAVE NORMLOOP;
					END IF;

					
					SET @DATA_DATE = V_DATA_DATE;
					SET @E_ID = ENT_ID;
					SET @E_NAME = ENT_NAME;
					SET @NORM_ID = V_NORM_ID;
					SET @NORM_NAME = V_NORM_NAME;
										
					
					DELETE FROM ADM.ANA_SUST_MTH_ENTERPRISE_SURVEY 
					WHERE DATA_DATE = @DATA_DATE 
					AND ENTERPRISE_ID = @E_ID 
					AND STANDARD_CODE = @NORM_ID;
					
					
					







					
					SELECT
					  PLAN_SQL INTO V_SQL_INSERT
					FROM
					  ADM.SUST_PLAN
					WHERE indicators_id = V_NORM_ID;

					
					SET @V_SQLTXT = V_SQL_INSERT;
					PREPARE V_SQLTXT FROM @V_SQLTXT;
					EXECUTE V_SQLTXT;
					DEALLOCATE PREPARE V_SQLTXT;

			END LOOP NORMLOOP;
			CLOSE CUR_NORM;

			SET DONE = FALSE;
	END LOOP ENTLOOP;
	CLOSE CUR_ENTERPRISE;

	


	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_ANA_SUST_MTH_ENTERPRISE_SURVEY_TEMP
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_ANA_SUST_MTH_ENTERPRISE_SURVEY_TEMP`;
delimiter ;;
CREATE DEFINER=`dis`@`%` PROCEDURE `P_ANA_SUST_MTH_ENTERPRISE_SURVEY_TEMP`(in V_DATA_DATE varchar(6))
BEGIN
	DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.P_ANA_SUST_MTH_ENTERPRISE_SURVEY_TEMP.PRC';
	DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
	DECLARE V_STEP_ID       INT           DEFAULT 0;
	DECLARE P_DATA_DATE     VARCHAR(8)    DEFAULT V_DATA_DATE;
	
	
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN
	GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
	UPDATE transfer.tf_business_launch_record SET RUN_STATUS = 3 WHERE ACCT_DATE = P_DATA_DATE;
	CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
	END;
	
SET V_STEP_ID = 1;
delete from ADM.ANA_SUST_MTH_ENTERPRISE_SURVEY_TEMP WHERE DATA_DATE = V_DATA_DATE;
SET V_STEP_ID = 2;
INSERT INTO ADM.ANA_SUST_MTH_ENTERPRISE_SURVEY_TEMP( 
  DATA_DATE,
  ENTERPRISE_ID,
  ENTERPRISE_NAME,
  NORM_NAME,
  MONEY
)
SELECT
  DATA_DATE             		AS DATA_DATE,
  E_CODE 				AS ENTERPRISE_ID,
  N2.ENTERPRISE_NAME			AS ENTERPRISE_NAME,
  TRIM(NUM_CHAR(ASSETS)) 		AS NORM_NAME,
  MONEY_1/10000				AS MONEY
FROM
  ODS.SUST_ENTERPRISE_REPORT N1
  LEFT JOIN ADM.SUST_ENTERPRISE N2
    ON N1.E_CODE = N2.ENTERPRISE_ID
WHERE N1.DATA_DATE = V_DATA_DATE
    AND N1.ASSETS <> ''
    and LENGTH(MONEY_1) = CHAR_LENGTH(MONEY_1)
    and RIGHT(MONEY_1,1) <> '-'
    AND MONEY_1 <> '.'
UNION ALL 
SELECT
  DATA_DATE 				AS DATA_DATE,
  E_CODE				AS ENTERPRISE_ID,
  N2.ENTERPRISE_NAME			AS ENTERPRISE_NAME,
  TRIM(NUM_CHAR(N1.LIABILITIES))  	AS NORM_NAME,
  MONEY_2/10000				AS MONEY	
FROM
  ODS.SUST_ENTERPRISE_REPORT N1
  LEFT JOIN ADM.SUST_ENTERPRISE N2
    ON N1.E_CODE = N2.ENTERPRISE_ID
WHERE N1.DATA_DATE = V_DATA_DATE
    AND N1.LIABILITIES <> ''
    AND LENGTH(MONEY_2) = CHAR_LENGTH(MONEY_2)
    AND RIGHT(MONEY_2,1) <> '-'
    AND MONEY_2 <> '.';
SET V_STEP_ID = 3;
DELETE FROM ADM.ana_sust_mth_enterprise_survey_temp WHERE DATA_DATE = V_DATA_DATE AND LENGTH(money) <> CHAR_LENGTH(money); 
SET V_STEP_ID = 4;
DELETE FROM ADM.ana_sust_mth_enterprise_survey_temp WHERE DATA_DATE = V_DATA_DATE AND (MONEY = '0' OR MONEY IS NULL OR MONEY = '' OR RIGHT(MONEY,1) = '-' or money = '42');
SET V_STEP_ID = 5;
CALL adm.P_ANA_SUST_MTH_ENTERPRISE_SURVEY(V_DATA_DATE,'','');
	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_ANA_SUST_MTH_SPECIAL_STRUC_AGRICU
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_ANA_SUST_MTH_SPECIAL_STRUC_AGRICU`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_ANA_SUST_MTH_SPECIAL_STRUC_AGRICU`(in v_data_date varchar(10))
BEGIN
DELETE FROM adm.ana_sust_mth_special_struc_agricu WHERE DATA_DATE=DATE_FORMAT(V_DATA_DATE,'%Y%m');
insert into adm.ana_sust_mth_special_struc_agricu
SELECT
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-01')      AS DATA_DATE,
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y%m')          AS DATA_MTH,
substr(a.PROJECT,4)				      AS ITEM_CATEGORY,
a.BAL_CUR*10000					      AS LOAN_BAL
FROM
ods.glr_lfc_spe_data_agri_dtl1 a
WHERE a.DATA_DATE = DATE_FORMAT(v_data_date,'%Y%m')
AND (a.PROJECT = '（一）农林牧渔业贷款'
OR a.PROJECT = '（二）农用物资和农副产品流通贷款'
OR a.PROJECT = '（三）农村基础设施建设贷款'
OR a.PROJECT = '（四）农产品加工贷款'
OR a.PROJECT = '（五）农业生产资料制造贷款'
OR a.PROJECT = '（六）农田基本建设贷款'
OR a.PROJECT = '（七）农业科技贷款'
OR a.PROJECT = '（八）其他');
	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_ANA_SUST_MTH_SPECIAL_STRUC_ENTER_SCALE
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_ANA_SUST_MTH_SPECIAL_STRUC_ENTER_SCALE`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_ANA_SUST_MTH_SPECIAL_STRUC_ENTER_SCALE`(in v_data_date varchar(10))
BEGIN
DELETE FROM adm.ana_sust_mth_special_struc_enter_scale WHERE DATA_DATE=DATE_FORMAT(V_DATA_DATE,'%Y%m');
insert into adm.ana_sust_mth_special_struc_enter_scale
SELECT 
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-01')      AS DATA_DATE,
DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y%m')          AS DATA_MTH,
CASE WHEN a.INDUSTRY_NAME LIKE '%境内大型企业贷款合计' THEN '大型企业'						      
     WHEN a.INDUSTRY_NAME LIKE '%境内中型企业贷款合计' THEN '中型企业'
     WHEN a.INDUSTRY_NAME LIKE '%境内小型企业贷款合计' THEN '小型企业'
     WHEN a.INDUSTRY_NAME LIKE '%境内微型企业贷款合计' THEN '微型企业'
     ELSE NULL
     END
						      AS ENTER_SCALE,
a.BWBBALANCELOAN				      AS LOAN_BAL
FROM ods.small_and_medium_sized_enterprises a
WHERE a.DATA_DATE = DATE_FORMAT(V_DATA_DATE,'%Y%m')
AND (a.INDUSTRY_NAME LIKE '%境内大型企业贷款合计' 
OR a.INDUSTRY_NAME LIKE '%境内中型企业贷款合计'
OR a.INDUSTRY_NAME LIKE '%境内小型企业贷款合计'
OR a.INDUSTRY_NAME LIKE '%境内微型企业贷款合计');
	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_ANA_SUST_MTH_SPECIAL_STRUC_REALTY
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_ANA_SUST_MTH_SPECIAL_STRUC_REALTY`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_ANA_SUST_MTH_SPECIAL_STRUC_REALTY`(in v_data_date varchar(10))
BEGIN
DELETE FROM adm.ana_sust_mth_special_struc_realty WHERE DATA_DATE=DATE_FORMAT(V_DATA_DATE,'%Y%m');
INSERT INTO adm.ana_sust_mth_special_struc_realty
SELECT
	DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-01')      AS DATA_DATE,
	DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y%m')          AS DATA_MTH,
	RIGHT(a.PROJECT,6)				      AS ITEM_CATEGORY,
	(a.LOAN_BALANCE)*10000				      AS LOAN_BAL
FROM
	ODS.GLR_REL_ESTATE_LOAN_MONITOR_DTL1 a
WHERE a.DATA_DATE = date_format(v_data_date,'%Y%m')
	AND (a.PROJECT = '1．地产开发贷款'
	OR a.PROJECT = '2．房产开发贷款');
	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_ANA_SUST_MTH_SPECIAL_TIMES
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_ANA_SUST_MTH_SPECIAL_TIMES`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_ANA_SUST_MTH_SPECIAL_TIMES`(in v_data_date varchar(10))
BEGIN
DELETE FROM adm.ana_sust_mth_special_times WHERE DATA_DATE=DATE_FORMAT(V_DATA_DATE,'%Y%m');
insert into adm.ana_sust_mth_special_times
SELECT 
	DATA_DATE,
	DATA_MTH,
	SUM(REALTY_LOAN_BAL),
	SUM(REALTY_LOAN_BAL_TB),
	SUM(AGRICU_LOAN_BAL),
	SUM(AGRICU_LOAN_BAL_TB)
FROM
(
-- 房地产贷款余额、同比增速
SELECT
	DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y-%m-01')      AS DATA_DATE,
	DATE_FORMAT(CONCAT(a.DATA_DATE,'01'),'%Y%m')          AS DATA_MTH,
	(a.LOAN_BALANCE)*10000 				      AS REALTY_LOAN_BAL,
	(a.LOAN_BALANCE-b.LOAN_BALANCE)/b.LOAN_BALANCE        AS REALTY_LOAN_BAL_TB,
	''						      AS AGRICU_LOAN_BAL,
	''						      AS AGRICU_LOAN_BAL_TB
FROM ods.glr_rel_estate_loan_monitor_dtl1 a
LEFT JOIN ods.glr_rel_estate_loan_monitor_dtl1 b
ON a.DATA_DATE = CONCAT(LEFT(b.DATA_DATE,4)-1,RIGHT(b.DATA_DATE,2))
AND a.PROJECT = b.PROJECT
WHERE a.DATA_DATE = DATE_FORMAT(v_data_date,'%Y%m')
AND a.PROJECT LIKE '合%计'
UNION ALL
-- 涉农贷款余额、同比增速
SELECT
	DATE_FORMAT(v_data_date,'%Y-%m-01')      	      AS DATA_DATE,
	DATE_FORMAT(v_data_date,'%Y%m')          	      AS DATA_MTH,
	'' 					              AS REALTY_LOAN_BAL,
	''                       			      AS REALTY_LOAN_BAL_TB,
	(SUM(a.BAL_CUR))*10000			              AS AGRICU_LOAN_BAL,
	(a.YOY_GROWTH)/100			              AS AGRICU_LOAN_BAL_TB
FROM ods.GLR_LFC_SPE_DATA_AGRI_DTL1 a
WHERE a.DATA_DATE = DATE_FORMAT(v_data_date,'%Y%m')
AND a.PROJECT = '涉农贷款'
) s 
GROUP BY s.DATA_DATE;
	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_ANA_SUST_UPDATE
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_ANA_SUST_UPDATE`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_ANA_SUST_UPDATE`(IN V_DATA_DATE VARCHAR(10))
BEGIN
-- 维度表更新
CALL EDW.P_CM_SUST_UPDATE();
-- EDW层
CALL EDW.p_transDataFromOdsToEdw_main();
CALL EDW.p_sust_source_of_funds_detailed_a01();
CALL EDW.P_SUST_SOURCE_OF_FUNDS_DETAILED_A02();
call EDW.P_SUST_SCIENCE_TECHNOLOGY_AND_FINANCE(data_format(v_DATA_DATE,'%Y%m%d'));
-- ADM层
CALL ADM.P_ANA_SUST_MTH_CREDIT_RECE_PAY_AREA(V_DATA_DATE);
CALL ADM.P_ANA_SUST_MTH_CREDIT_RECE_PAY_STRUC(V_DATA_DATE);
CALL ADM.P_ANA_SUST_MTH_CREDIT_RECE_PAY_TIMES(V_DATA_DATE);
CALL ADM.P_ANA_SUST_MTH_SPECIAL_STRUC_AGRICU(V_DATA_DATE);
CALL ADM.P_ANA_SUST_MTH_SPECIAL_STRUC_ENTER_SCALE(V_DATA_DATE);
CALL ADM.P_ANA_SUST_MTH_SPECIAL_STRUC_REALTY(V_DATA_DATE);
CALL ADM.P_ANA_SUST_MTH_SPECIAL_TIMES(V_DATA_DATE);
    END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_BIG_All
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_BIG_All`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_BIG_All`(
IN V_DATA_DATE VARCHAR(10)
,IN V_ID   CHAR(19)
)
BEGIN
    
    DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'adm.P_BIG_All.PRC';
    DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
    DECLARE V_STEP_ID       INT           DEFAULT 0;
    DECLARE P_DATA_DATE     VARCHAR(8)	DEFAULT	DATE_FORMAT(CONCAT(V_DATA_DATE,'01'),'%Y-%m');
   
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
        
        UPDATE  adm.`exec_shell_task` SET STATUS='500' WHERE id=V_ID;    --   修改状态跑批失败
    END;
  
	SET V_DATA_DATE = DATE_FORMAT(CONCAT(V_DATA_DATE, '01'), '%Y-%m') ;
	SET V_STEP_ID = 1 ;
	UPDATE 
	  adm.`exec_shell_task` 
	SET
	  STATUS = '1' 
	WHERE id=V_ID;  --   修改状态跑批正在运行
	SET V_STEP_ID = 2 ;
-- 	CALL `indicators_lib`.`p_xunhuan_formula_new`(V_DATA_DATE);
	
	CALL visual_screen.P_task_vscreen(V_DATA_DATE);
	SET V_STEP_ID = 3 ;
	UPDATE 
	  adm.`exec_shell_task` 
	SET
	  STATUS = '200' 
	WHERE   id=V_ID; --   修改状态跑批成功
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_EXECUTE_DATE_PROCESSING
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_EXECUTE_DATE_PROCESSING`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_EXECUTE_DATE_PROCESSING`(
IN P_DATA_DATE CHAR(10)
)
BEGIN
  -- DECLARE  P_DAY_DATE  CHAR(10) DEFAULT '';
    -- 定义跑数日期（当前时间的7天前）
   -- SET P_DAY_DATE = CONCAT(DATE_SUB(DATE_FORMAT(NOW(),'%Y-%m-%d'),INTERVAL 7 DAY));
   SET P_DATA_DATE=DATE_FORMAT(P_DATA_DATE,'%Y-%m-%d');
  -- SET P_DAY_DATE = P_DATA_DATE;
    -- 定义跑数日期的本月最后一天日期
    SET @P_LASTDAY_DAYE=CONCAT(LAST_DAY(P_DATA_DATE));
    -- 执行报表数据加工过程
  --  CALL ADM.P_GUOKU_REPORT_PROCESSING(P_DAY_DATE);
    -- 执行多维数据加工过程
    CALL ADM.P_GUOKU_SAIKU_PROCESSING(P_DATA_DATE);
    IF P_DATA_DATE=@P_LASTDAY_DAYE 
    THEN
         -- 执行专题按日跑的数据加工过程
         CALL ADM.P_GUOKU_DAY_ANA_PROCESSING(P_DATA_DATE);
         -- 执行专题按每月最后一天跑的数据加工过程
         CALL ADM.P_GUOKU_LASTDAY_ANA_PROCESSING(P_DATA_DATE);
    ELSE
         -- 执行专题按日跑的数据加工过程
         CALL ADM.P_GUOKU_DAY_ANA_PROCESSING(P_DATA_DATE);
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_EXECUTE_DATE_PROCESSING1
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_EXECUTE_DATE_PROCESSING1`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_EXECUTE_DATE_PROCESSING1`(
IN P_DATA_DATE CHAR(10)
)
BEGIN
  -- DECLARE  P_DAY_DATE  CHAR(10) DEFAULT '';
    -- 定义跑数日期（当前时间的7天前）
   -- SET P_DAY_DATE = CONCAT(DATE_SUB(DATE_FORMAT(NOW(),'%Y-%m-%d'),INTERVAL 7 DAY));
   SET P_DATA_DATE=DATE_FORMAT(P_DATA_DATE,'%Y-%m-%d');
  -- SET P_DAY_DATE = P_DATA_DATE;
    -- 定义跑数日期的本月最后一天日期
    SET @P_LASTDAY_DAYE=CONCAT(LAST_DAY(P_DATA_DATE));
    -- 执行报表数据加工过程
  --  CALL ADM.P_GUOKU_REPORT_PROCESSING(P_DAY_DATE);
    -- 执行多维数据加工过程
    
    IF P_DATA_DATE=@P_LASTDAY_DAYE 
    THEN
         -- 执行专题按日跑的数据加工过程
         CALL ADM.P_GUOKU_DAY_ANA_PROCESSING(P_DATA_DATE);
         -- 执行专题按每月最后一天跑的数据加工过程
         CALL ADM.P_GUOKU_LASTDAY_ANA_PROCESSING(P_DATA_DATE);
    ELSE
         -- 执行专题按日跑的数据加工过程
         CALL ADM.P_GUOKU_DAY_ANA_PROCESSING(P_DATA_DATE);
    END IF;
    END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_GUOKU_DAY_ANA_PROCESSING
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_GUOKU_DAY_ANA_PROCESSING`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_GUOKU_DAY_ANA_PROCESSING`(
    IN P_DATA_DATE CHAR(10)
)
BEGIN
/******************
过程跑数频率：按日
过程跑数内容：执行专题加工所有按日跑的过程
*******************/
    DECLARE V_PROC_NAME     VARCHAR(50)     DEFAULT 'ADM.P_GUOKU_DAY_ANA_PROCESSING.PRC';
    DECLARE V_START_TIME    CHAR(19)        DEFAULT NOW();
    DECLARE V_STEP_ID       INT             DEFAULT 0;  -- 步骤编号
    DECLARE V_STEP_NAME     VARCHAR(100)    DEFAULT ''; -- 步骤信息
    DECLARE V_SQL_ID        INT             DEFAULT 0;  -- 查询SQL的ID
    DECLARE V_TABLE_NAME    VARCHAR(50)     DEFAULT ''; -- 操作表名
    DECLARE V_SQL_DELETE    VARCHAR(100)    DEFAULT ''; -- 删除语句SQL
    DECLARE V_SQL_INSERT    LONGTEXT        DEFAULT ''; -- 插数语句SQL
    DECLARE V_SQLTXT        LONGTEXT        DEFAULT ''; -- 执行SQL
    DECLARE DONE            INT             DEFAULT FALSE; -- 自定义控制游标循环变量,默认false
    DECLARE PROC_CURSOR     CURSOR FOR (
                                       SELECT ID FROM ADM.TRS_GUOKU_ANALYSIS_PROCESSING
                                       WHERE FREQUENCY_CODE = '1' and IS_ACTIVE='1'
                                       AND REPLACE(P_DATA_DATE,'-','') BETWEEN START_DATE AND END_DATE
                                       ); -- 定义游标并输入结果集
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET DONE = TRUE; -- 绑定控制变量到游标,游标循环结束自动转true
    /* EXCEPTION HANDLER */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,@V_RETURN_CODE,@V_ERROR_MSG);
    END;
    
    OPEN PROC_CURSOR; -- 打开游标
    PROC_CURSOR: LOOP -- 开始循环体,PROC_CURSOR为自定义循环名,结束循环时用到
    FETCH PROC_CURSOR INTO V_SQL_ID; -- 将游标当前读取行的数据顺序赋予自定义变量-查询SQL的ID
    IF DONE THEN -- 判断是否继续循环
      LEAVE PROC_CURSOR; -- 结束循环
    END IF;
    -- 自己要做的事情,在 sql 中直接使用自定义变量即可
    
    -- 每日日期
    SET @DAY_DATE = CONCAT(P_DATA_DATE);
    -- 上月日期
    SET @LASTMTH_DATE = CONCAT(DATE_ADD(@DAY_DATE, INTERVAL -1 MONTH));
    -- 去年同期日期
    SET @LASTYEAR_DATE = CONCAT(DATE_ADD(@DAY_DATE, INTERVAL -1 YEAR));
    -- 年初日期
    SET @LASTYEAR_DATE = CONCAT(DATE_SUB(@DAY_DATE,INTERVAL DAYOFYEAR(@DAY_DATE) DAY));
    -- 获取表名
    SELECT TABLE_NAME INTO V_TABLE_NAME FROM ADM.TRS_GUOKU_ANALYSIS_PROCESSING WHERE  ID=V_SQL_ID;
    -- 获取删除语句SQL
    SELECT SQL_DELETE INTO V_SQL_DELETE FROM ADM.TRS_GUOKU_ANALYSIS_PROCESSING WHERE  ID=V_SQL_ID;
    -- 获取插数语句SQL
    SELECT SQL_INSERT INTO V_SQL_INSERT FROM ADM.TRS_GUOKU_ANALYSIS_PROCESSING WHERE  ID=V_SQL_ID;
    
    -- 删除步骤开始
    SET V_STEP_ID = V_STEP_ID + 1;
    -- 更新步骤信息
    SET V_STEP_NAME = CONCAT('删除',V_TABLE_NAME,'该日期下的数据');
    -- 封装删除语句
    SET @V_SQLTXT = CONCAT(V_SQL_DELETE);
    -- 准备删除
    PREPARE V_SQLTXT FROM @V_SQLTXT;
    -- 执行删除
    EXECUTE V_SQLTXT;
    -- ETL记录删除结果
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    -- 删除步骤结束
    
    -- 插数步骤开始
    SET V_STEP_ID = V_STEP_ID + 1;
    -- 更新步骤信息
    SET V_STEP_NAME=CONCAT('增加',V_TABLE_NAME,'该日期下的数据');
    -- 封装插数语句
    SET @V_SQLTXT = CONCAT(V_SQL_INSERT);
    -- 准备插数
    PREPARE V_SQLTXT FROM @V_SQLTXT;
    -- 执行插数
    EXECUTE V_SQLTXT;
    -- ETL记录插数结果
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
    -- 插数步骤结束
    
    COMMIT; -- 提交事务  
    END LOOP PROC_CURSOR; -- 结束自定义循环体  
    CLOSE PROC_CURSOR; -- 关闭游标
END
;;
