		ELSE '9999'
	END AS ORG_ID 
	,T.ORG_NAME
	,'贷款余额'
	,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN  IFNULL(LOAN_BAL_TOTAL,0) ELSE 0 END)/10000  AS LOAN_AMOUNT
     FROM EDW.GLR_REL_ESTATE_LOAN_DIRECT_ORG  T
     GROUP BY 
        CASE ORG_NAME 
		WHEN  '中国工商银行'                   THEN     'C1010211000012'
