	,LOAN_AMOUNT                   #贷款金额
	,LOAN_AMOUNT_LY                #去年同期贷款金额
	)
    #1.1(合计)  余额当月新增  
    SELECT 
         CONCAT(V_DATA_DATE,'01')
	,V_DATA_DATE
	,CASE  
	   WHEN ORG_NAME = '重庆市'   THEN    '500000'     
	   WHEN ORG_NAME = '万州区'   THEN    '500101'     
	   WHEN ORG_NAME = '涪陵区'   THEN    '500102'     
	   WHEN ORG_NAME = '渝中区'   THEN    '500103'     
	   WHEN ORG_NAME = '大渡口区' THEN    '500104'     
	   WHEN ORG_NAME = '江北区'   THEN    '500105'     
	   WHEN ORG_NAME = '沙坪坝区' THEN    '500106'     
	   WHEN ORG_NAME = '九龙坡区' THEN    '500107'     
	   WHEN ORG_NAME = '南岸区'   THEN    '500108'     
	   WHEN ORG_NAME = '北碚区'   THEN    '500109'     
	   WHEN ORG_NAME = '綦江区'   THEN    '500110'     
	   WHEN ORG_NAME = '大足区'   THEN    '500111'     
	   WHEN ORG_NAME = '渝北区'   THEN    '500112'     
	   WHEN ORG_NAME = '巴南区'   THEN    '500113'     
	   WHEN ORG_NAME = '黔江区'   THEN    '500114'     
	   WHEN ORG_NAME = '长寿区'   THEN    '500115'     
	   WHEN ORG_NAME = '江津区'   THEN    '500116'     
	   WHEN ORG_NAME = '合川区'   THEN    '500117'     
	   WHEN ORG_NAME = '永川区'   THEN    '500118'     
	   WHEN ORG_NAME = '南川区'   THEN    '500119'     
	   WHEN ORG_NAME = '璧山区'   THEN    '500120'     
	   WHEN ORG_NAME = '铜梁区'   THEN    '500151'     
	   WHEN ORG_NAME = '潼南区'   THEN    '500152'     
	   WHEN ORG_NAME = '荣昌区'   THEN    '500153'     
