	,ORG_NAME
	,'3'
	,'证券化的房地产贷款'
	,'其他证券化房地产贷款'
	,SUM(CASE WHEN DATA_DATE=V_DATA_DATE   THEN  IFNULL(LOAN_BAL_STOCK_O,0) ELSE 0 END ) AS LOAN_REMAIN
	,SUM(CASE WHEN DATA_DATE=V_DATA_DATE_L THEN  IFNULL(LOAN_BAL_STOCK_O,0) ELSE 0 END ) AS LOAN_REMAIN_LY
	FROM EDW.GLR_REL_ESTATE_LOAN_DIRECT_ORG 
	GROUP BY 
	CASE ORG_NAME 
	WHEN  '中国工商银行'                               THEN     'C1010211000012'
	WHEN  '中国农业银行'                               THEN     'C1010311000014'
