-- ----------------------------
-- Procedure structure for P_NAN_SUMMARY
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_NAN_SUMMARY`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_NAN_SUMMARY`(IN P_DATA_DATE VARCHAR(8),OUT P_RESULT   INT)
BEGIN
/*
| Author :严锦涛
| Name :ADM.ana_glr_mth_small_micro_map
| FUNCTION:
| Purpose:货币信贷-专题分析-总览分析
|         EDW.GLR_EDS_SPE_DATA_INDUS|重庆市全金融机构(含外资)贷款按行业|ADM.ANA_GLR_MTH_LOAN_SUMMARY  (只有本外币贷款余额有值)
|         EDW.GLR_MPA_ALL_FOREGN_CNY_CREDIT|重庆市全金融机构本外币信贷收支合并表|ADM.ANA_GLR_MTH_DEPOSIT_SUMMARY
|         EDW.GLR_MPA_ALL_CNY_CREDIT_DTL1|重庆市全金融机构人民币信贷收支合并表|ADM.ANA_GLR_MTH_DEPOSIT_SUMMARY
|
|
| VER         DATE        AUTHOR           DESCRIPTION
| ---------  ----------  ---------------  ------------------------------------
| 1.0        2019-01-03     严锦涛        1.CREATES THE PROCEDURE
*/     
    DECLARE V_PROC_NAME VARCHAR(200) DEFAULT 'ADM.P_NAN_SUMMARY.prc';
    DECLARE V_STEP INT DEFAULT 0;
    DECLARE V_START_TIME VARCHAR(20) DEFAULT NOW();
    DECLARE V_DATA_DATE VARCHAR(6) DEFAULT SUBSTR(P_DATA_DATE,1,6);    
    DECLARE V_DATA_DATE_P VARCHAR(6) DEFAULT SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 1 MONTH),'%Y%m%d'),1,6);       -- 上月
    
    DECLARE V_DATA_DATE_L VARCHAR(6) DEFAULT SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 12 MONTH),'%Y%m%d'),1,6);       -- 去年同期
    DECLARE V_DATA_DATE_L_P VARCHAR(6) DEFAULT SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 13 MONTH),'%Y%m%d'),1,6);     -- 去年同期上月
    
    DECLARE V_DATA_END_Y VARCHAR(6) DEFAULT CONCAT(SUBSTR(P_DATA_DATE,1,4),'01');                                                                   -- 年末
    DECLARE V_DATA_END_Y_L VARCHAR(6) DEFAULT CONCAT(SUBSTR(P_DATA_DATE,1,4)-1,'01');                                                               -- 上年末
    
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    
    SET V_STEP:='1';
    DELETE  FROM ADM.ANA_GLR_MTH_LOAN_SUMMARY WHERE FISCAL_MTH = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='2';
    #本外币贷款余额
    INSERT INTO ADM.ANA_GLR_MTH_LOAN_SUMMARY (
	 FISCAL_DATE                             #日期
	,FISCAL_MTH                              #月份
	,CITY_ID                                 #市编码
	,CITY_NAME                               #市名称
	,DIRECTION_INDUSTRY_ID                   #行业投向编码
	,DIRECTION_INDUSTRY_NAME                 #行业投向名称
	,LOAN_REMAIN                             #人民币贷款余额
	,LOAN_REMAIN_LY                          #去年同期人民币贷款余额
	,LOAN_REMAIN_ZDM                         #人民币贷款余额当月增量
	,LOAN_REMAIN_ZDM_LY                      #去年同期人民币贷款余额当月增量
	,LOAN_REMAIN_ZBY                         #人民币贷款余额比年初增量
	,LOAN_REMAIN_ZBY_LY                      #去年同期人民币贷款余额比年初增量
	,LOAN_REMAINT                            #本外币贷款余额
	,LOAN_REMAINT_LY                         #去年同期本外币贷款余额
	,LOAN_REMAIN_ZDMT                        #本外币贷款余额当月增量(本月-上月)
	,LOAN_REMAIN_ZDMT_LY                     #去年同期本外币贷款余额当月增量
	,LOAN_REMAIN_ZBYT                        #本外币贷款余额比年初增量(减去年12月)
	,LOAN_REMAIN_ZBYT_LY                     #去年同期本外币贷款余额比年初增量
	)
     SELECT 
          CONCAT(V_DATA_DATE,'01')   
         ,V_DATA_DATE
         ,'50000'
         ,'重庆市'
         ,TRIM(SUBSTRING_INDEX(project,'.',1)) AS DIRECTION_INDUSTRY_ID
         ,TRIM(SUBSTRING_INDEX(project,'.',-1)) AS  DIRECTION_INDUSTRY_NAME
         ,0
         ,0
         ,0
         ,0
         ,0
         ,0
         ,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(BALANCE,0) ELSE 0 END ) AS  LOAN_REMAINT
         ,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(BALANCE,0) ELSE 0 END ) AS  LOAN_REMAINT_LY
         ,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(BALANCE,0) ELSE 0 END ) - SUM(CASE WHEN data_date = v_data_date_p THEN IFNULL(BALANCE,0) ELSE 0 END ) AS LOAN_REMAIN_ZDMT_LY
         ,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(BALANCE,0) ELSE 0 END ) - SUM(CASE WHEN data_date = V_DATA_DATE_L_P THEN IFNULL(BALANCE,0) ELSE 0 END ) AS LOAN_REMAIN_ZDMT_LY
         ,SUM(CASE WHEN data_date = v_data_date THEN IFNULL(BALANCE,0) ELSE 0 END ) - SUM(CASE WHEN data_date = V_DATA_END_Y THEN IFNULL(BALANCE,0) ELSE 0 END )  AS LOAN_REMAIN_ZBYT
         ,SUM(CASE WHEN data_date = v_data_date_l THEN IFNULL(BALANCE,0) ELSE 0 END ) - SUM(CASE WHEN data_date = V_DATA_END_Y_L THEN IFNULL(BALANCE,0) ELSE 0 END )
     FROM EDW.GLR_EDS_SPE_DATA_INDUS T
     WHERE TRIM(SUBSTRING_INDEX(project,'.',1)) REGEXP '[A-Z]'
       AND T.DATA_DATE IN (V_DATA_DATE,V_DATA_DATE_L,V_DATA_DATE_P,V_DATA_DATE_L_P,V_DATA_END_Y,V_DATA_END_Y_L) 
       GROUP BY  V_DATA_DATE
               ,'50000'
               ,'重庆市'
               ,TRIM(SUBSTRING_INDEX(project,'.',1))
               , TRIM(SUBSTRING_INDEX(project,'.',-1)) 
      
     ;
     CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
 SET V_STEP:='3';
    DELETE  FROM ADM.ANA_GLR_MTH_DEPOSIT_SUMMARY WHERE FISCAL_MTH = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
     
    SET V_STEP:='4';
  #本外币存款余额分类型
 INSERT INTO ADM.ANA_GLR_MTH_LOAN_SUMMARY_1 (
	 FISCAL_DATE                                #日期
	,FISCAL_MTH                                 #月份
	,CITY_ID                                    #市编码
	,CITY_NAME                                  #市名称
	,DEPOSIT_REMAIN                             #人民币贷款余额
	,DEPOSIT_REMAIN_LY                          #去年同期人民币贷款余额
	,DEPOSIT_REMAIN_ZDM                         #人民币贷款余额当月增量
	,DEPOSIT_REMAIN_ZDM_LY                      #去年同期人民币贷款余额当月增量
	,DEPOSIT_REMAIN_ZBY                         #人民币贷款余额比年初增量
	,DEPOSIT_REMAIN_ZBY_LY                      #去年同期人民币贷款余额比年初增量
	,DEPOSIT_REMAINT                            #本外币贷款余额
	,DEPOSIT_REMAINT_LY                         #去年同期本外币贷款余额
	,DEPOSIT_REMAIN_ZDMT                        #本外币贷款余额当月增量(本月-上月)
	,DEPOSIT_REMAIN_ZDMT_LY                     #去年同期本外币贷款余额当月增量
	,DEPOSIT_REMAIN_ZBYT                        #本外币贷款余额比年初增量(减去年12月)
	,DEPOSIT_REMAIN_ZBYT_LY                     #去年同期本外币贷款余额比年初增量
	)
     SELECT 
          CONCAT(V_DATA_DATE,'01')   
         ,V_DATA_DATE
         ,'50000'
         ,'重庆市'
         ,0                                      AS DEPOSIT_REMAIN       
         ,0                                      AS DEPOSIT_REMAIN_LY    
         ,0                                      AS DEPOSIT_REMAIN_ZDM   
         ,0                                      AS DEPOSIT_REMAIN_ZDM_LY
         ,0                                      AS DEPOSIT_REMAIN_ZBY   
         ,0                                      AS DEPOSIT_REMAIN_ZBY_LY
         ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BALANCE,0) ELSE 0 END ) AS DEPOSIT_REMAINT
         ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE_L THEN IFNULL(LOAN_BALANCE,0) ELSE 0 END ) AS DEPOSIT_REMAINT_LY
         ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BALANCE_SUB_P,0) ELSE 0 END )  AS DEPOSIT_REMAIN_ZDMT
         ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BALANCE_SUB_L_P,0) ELSE 0 END ) AS DEPOSIT_REMAIN_ZDMT_LY
         ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BALANCE_SUB_BGY,0) ELSE 0 END ) AS DEPOSIT_REMAIN_ZBYT
         ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BALANCE_SUB_BGY_L,0) ELSE 0 END )  AS DEPOSIT_REMAIN_ZBYT_LY
      FROM EDW.GLR_MPA_ALL_FOREGN_CNY_CREDIT T
      WHERE ROWS_ID = '3'
	  AND T.DATA_DATE IN (V_DATA_DATE,V_DATA_DATE_L) 
     GROUP BY  V_DATA_DATE
               ,'50000'
               ,'重庆市'
UNION ALL 
  #人民币存款余额分类型
SELECT 
      CONCAT(V_DATA_DATE,'01')   
     , V_DATA_DATE
     ,'50000'
     ,'重庆市'
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BALANCE,0) ELSE 0 END ) AS DEPOSIT_REMAIN
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE_L THEN IFNULL(LOAN_BALANCE,0) ELSE 0 END ) AS DEPOSIT_REMAIN_LY
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BALANCE_SUB_P,0) ELSE 0 END )  AS DEPOSIT_REMAIN_ZDM
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BALANCE_SUB_L_P,0) ELSE 0 END ) AS DEPOSIT_REMAIN_ZDM_LY
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BALANCE_SUB_BGY,0) ELSE 0 END )  AS DEPOSIT_REMAIN_ZBY
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BALANCE_SUB_BGY_L,0) ELSE 0 END )  AS DEPOSIT_REMAIN_ZBY_LY
     ,0
     ,0
     ,0
     ,0
     ,0
     ,0
     FROM EDW.GLR_MPA_ALL_CNY_CREDIT T
     WHERE ROWS_ID = '3'
      AND T.DATA_DATE IN (V_DATA_DATE,V_DATA_DATE_L)
      GROUP BY  V_DATA_DATE
               ,'50000'
               ,'重庆市'
     ;
     CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
     
     	 
	 
 
     
    SET V_STEP:='4';
    DELETE  FROM ADM.ANA_GLR_MTH_DEPOSIT_SUMMARY WHERE FISCAL_MTH = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
     
    SET V_STEP:='5';
    INSERT INTO ADM.ANA_GLR_MTH_DEPOSIT_SUMMARY (
	 FISCAL_DATE                    #日期
	,FISCAL_MTH                     #月份
	,CITY_ID                        #市编码
	,CITY_NAME                      #市名称
	,DEPOSIT_TYPE_ID                #存款类型编码
	,DEPOSIT_TYPE                   #存款类型名称
	,DEPOSIT_REMAIN                 #人民币存款余额
	,DEPOSIT_REMAIN_LY              #去年同期人民币存款余额
	,DEPOSIT_REMAIN_ZDM             #人民币存款余额当月增量
	,DEPOSIT_REMAIN_ZDM_LY          #去年同期人民币存款余额当月增量
	,DEPOSIT_REMAIN_ZBY             #人民币存款余额比年初增量
	,DEPOSIT_REMAIN_ZBY_LY          #人民币去年人民币同期存款余额比年初增量
	,DEPOSIT_REMAINT                #本外币存款余额
	,DEPOSIT_REMAINT_LY             #去年同期本外币存款余额
	,DEPOSIT_REMAIN_ZDMT            #本外币存款余额当月增量
	,DEPOSIT_REMAIN_ZDMT_LY         #去年同期本外币存款余额当月增量
	,DEPOSIT_REMAIN_ZBYT            #本外币存款余额比年初增量
	,DEPOSIT_REMAIN_ZBYT_LY         #去年同期本外币存款余额比年初增量
	)
     #本外币存款余额分类型
          SELECT 
     CONCAT(V_DATA_DATE,'01')   
     , V_DATA_DATE
     ,'50000'
     ,'重庆市'
     ,CASE WHEN t.rows_id = 3 THEN 1
           WHEN t.rows_id = 5 THEN 2 
           WHEN t.rows_id = 8 THEN 3
           WHEN t.rows_id = 11 THEN 4
           WHEN t.rows_id = 14 THEN 5
      END AS DEPOSIT_TYPE_ID
           
     ,TRIM(SUBSTRING_INDEX(project1,'.',-1)) AS DEPOSIT_TYPE
     ,0                                      AS DEPOSIT_REMAIN       
     ,0                                      AS DEPOSIT_REMAIN_LY    
     ,0                                      AS DEPOSIT_REMAIN_ZDM   
     ,0                                      AS DEPOSIT_REMAIN_ZDM_LY
     ,0                                      AS DEPOSIT_REMAIN_ZBY   
     ,0                                      AS DEPOSIT_REMAIN_ZBY_LY
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(DEPB_BALANCE,0) ELSE 0 END ) AS DEPOSIT_REMAINT
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE_L THEN IFNULL(DEPB_BALANCE,0) ELSE 0 END ) AS DEPOSIT_REMAINT_LY
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(DEPB_BALANCE_SUB_P,0) ELSE 0 END )  AS DEPOSIT_REMAIN_ZDMT
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(DEPB_BALANCE_SUB_L_P,0) ELSE 0 END ) AS DEPOSIT_REMAIN_ZDMT_LY
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(DEPB_BALANCE_SUB_BGY,0) ELSE 0 END ) AS DEPOSIT_REMAIN_ZBYT
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(DEPB_BALANCE_SUB_BGY_L,0) ELSE 0 END )  AS DEPOSIT_REMAIN_ZBYT_LY
     FROM EDW.GLR_MPA_ALL_FOREGN_CNY_CREDIT T
     WHERE ROWS_ID IN (3,5,8,11,14)
     AND T.DATA_DATE IN (V_DATA_DATE,V_DATA_DATE_L,V_DATA_DATE_P,V_DATA_DATE_L_P,V_DATA_END_Y,V_DATA_END_Y_L)
     GROUP BY
         CASE WHEN t.rows_id = 3 THEN 1
		   WHEN t.rows_id = 5 THEN 2 
           WHEN t.rows_id = 8 THEN 3
           WHEN t.rows_id = 11 THEN 4
           WHEN t.rows_id = 14 THEN 5
          END 
         ,TRIM(SUBSTRING_INDEX(project1,'.',-1))
         
         
     UNION ALL
     
     #人民币存款余额分类型
     SELECT 
      CONCAT(V_DATA_DATE,'01')   
     , V_DATA_DATE
     ,'50000'
     ,'重庆市'
     ,CASE WHEN t.rows_id = 3 THEN 1
		   WHEN t.rows_id = 5 THEN 2 
           WHEN t.rows_id = 8 THEN 3
           WHEN t.rows_id = 11 THEN 4
           WHEN t.rows_id = 14 THEN 5
      END AS DEPOSIT_TYPE_ID
           
     ,TRIM(SUBSTRING_INDEX(project1,'.',-1)) AS DEPOSIT_TYPE
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(DEPB_BALANCE,0) ELSE 0 END ) AS DEPOSIT_REMAIN
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE_L THEN IFNULL(DEPB_BALANCE,0) ELSE 0 END ) AS DEPOSIT_REMAIN_LY
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(DEPB_BALANCE_SUB_P,0) ELSE 0 END )  AS DEPOSIT_REMAIN_ZDM
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(DEPB_BALANCE_SUB_L_P,0) ELSE 0 END ) AS DEPOSIT_REMAIN_ZDM_LY
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(DEPB_BALANCE_SUB_BGY,0) ELSE 0 END )  AS DEPOSIT_REMAIN_ZBY
     ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(DEPB_BALANCE_SUB_BGY_L,0) ELSE 0 END )  AS DEPOSIT_REMAIN_ZBY_LY
     ,0
     ,0
     ,0
     ,0
     ,0
     ,0
     FROM EDW.GLR_MPA_ALL_CNY_CREDIT T
     WHERE ROWS_ID IN (3,5,8,11,14)
     AND T.DATA_DATE IN (V_DATA_DATE,V_DATA_DATE_L,V_DATA_DATE_P,V_DATA_DATE_L_P,V_DATA_END_Y,V_DATA_END_Y_L)
     GROUP BY 
      CASE WHEN t.rows_id = 3 THEN 1
		   WHEN t.rows_id = 5 THEN 2 
           WHEN t.rows_id = 8 THEN 3
           WHEN t.rows_id = 11 THEN 4
           WHEN t.rows_id = 14 THEN 5
          END 
         ,TRIM(SUBSTRING_INDEX(project1,'.',-1))
     
     ;
    
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_NAN_TPA_POOR_RESULTS
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_NAN_TPA_POOR_RESULTS`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_NAN_TPA_POOR_RESULTS`(IN P_DATA_DATE VARCHAR(8),OUT P_RESULT   INT)
BEGIN
/*
| Author :严锦涛
| Name :ADM.ANA_GLR_MTH_FINA_JZFP
| FUNCTION:
| Purpose:货币信贷-专题分析-扶贫效果分析
|         EDW.GLR_TPA_TYPE_LOAN|全金融机构金融精准扶贫贷款统计表分类别|adm.ana_glr_mth_fina_jzfp
|    
|
| VER         DATE        AUTHOR           DESCRIPTION
| ---------  ----------  ---------------  ------------------------------------
| 1.0        2019-01-02     严锦涛        1.CREATES THE PROCEDURE
*/     
    DECLARE V_PROC_NAME VARCHAR(200) DEFAULT 'ADM.P_NAN_TPA_POOR_RESULTS.prc';
    DECLARE V_STEP INT DEFAULT 0;
    DECLARE V_START_TIME VARCHAR(20) DEFAULT NOW();
    DECLARE V_DATA_DATE VARCHAR(6) DEFAULT SUBSTR(P_DATA_DATE,1,6);
    DECLARE V_DATA_DATE_L VARCHAR(20);
    DECLARE V_QUA_DESC VARCHAR(100) DEFAULT CONCAT(DATE_FORMAT( P_DATA_DATE, '%Y' ),'年','第',QUARTER(P_DATA_DATE),'季度');
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    
     #去年同期
    SET V_DATA_DATE_L = DATE_ADD(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'), INTERVAL -12 MONTH);
    #本年季度日期处理
    SELECT CONCAT('\'',CONCAT(QUARTER(DATE_FORMAT(P_DATA_DATE,'%Y%m%d')),'Q'),'\'') INTO @v_temp_qua;
    SET @instr = CONCAT('SELECT MAX(T.MONTH) AS MONTH  INTO @V_TEMP_QUA_MONTH  FROM edw.dim_date t WHERE t.QUARTER=',@v_temp_qua,'
    AND t.YEAR = ',SUBSTR(P_DATA_DATE,1,4));
    
    PREPARE smt FROM @instr;
    EXECUTE smt;
    DEALLOCATE PREPARE smt;    
    
    
    #去年季度
    SELECT CONCAT('\'',CONCAT(QUARTER(DATE_FORMAT(V_DATA_DATE_L,'%Y%m%d')),'Q'),'\'') INTO @v_temp_qua;
    SET @instr_l = CONCAT('SELECT MAX(T.MONTH) AS MONTH  INTO @V_TEMP_QUA_MONTH_L  FROM edw.dim_date t WHERE t.QUARTER=',@v_temp_qua,'
    AND t.YEAR = ',SUBSTR(V_DATA_DATE_L,1,4));
    
    PREPARE smt FROM @instr_l;
    EXECUTE smt;
    DEALLOCATE PREPARE smt;    
    
    
    SET V_STEP:='1';
    DELETE  FROM ADM.ANA_GLR_MTH_FINA_JZFP WHERE FISCAL_MTH = @V_TEMP_QUA_MONTH;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='2';
    INSERT INTO ADM.ANA_GLR_MTH_FINA_JZFP (
	 FISCAL_DATE               #日期
	,FISCAL_MTH                #月份
	,DSCR_QUA                  #该月对应季度描述
	,CITY_ID                   #市编码
	,CITY_NAME                 #市名称
	,ORG_TYPE_ID               #金融机构类型编码
	,ORG_TYPE_NAME             #金融机构类型名称
	,ORG_ID                    #金融机构编码
	,ORG_NAME                  #金融机构名称
	,LOAN_TYPE_ID              #贷款类型ID
	,LOAN_TYPE_NAME            #贷款类型描述
	,LOAN_REMAIN               #贷款余额
	,LOAN_REMAIN_LY            #去年同期贷款余额
	,LOAN_FF                   #当年累计发放额
	,LOAN_FF_LY                #去年同期累计发放额
	,STROKE_COUNT              #贷款笔数
	,SPUR_SERV_POOR_NUM        #带动服务贫困人口数
	)
     #1. 个人精准扶贫贷款 贷款余额|去年同期贷款余额|当年累计发放额|去年同期累计发放额|贷款笔数|带动服务贫困人口数
     #个人精准扶贫贷款(建档立卡贫困人口贷款余额 +其他个人精准扶贫贷款余额)
     SELECT 
          TEMP.FISCAL_DATE
         ,TEMP.FISCAL_MTH
         ,TEMP.DSCR_QUA
         ,TEMP.CITY_ID
         ,TEMP.CITY_NAME
         ,CASE WHEN TEMP.ORG_ID='C0000000000000' THEN 'A13' ELSE R.ORG_TYPE_ID_2 END 
         ,CASE WHEN TEMP.ORG_ID='C0000000000000' THEN '村镇银行' ELSE R.ORG_TYPE_DSCR_2 END 
         ,TEMP.ORG_ID
         ,TEMP.ORG_NAME
         ,TEMP.LOAN_TYPE_ID
         ,TEMP.LOAN_TYPE_NAME
         ,TEMP.LOAN_REMAIN
         ,TEMP.LOAN_REMAIN_LY
         ,TEMP.LOAN_FF
         ,TEMP.LOAN_FF_LY
         ,TEMP.STROKE_COUNT
         ,TEMP.SPUR_SERV_POOR_NUM
     FROM(
     SELECT 
         CONCAT(@V_TEMP_QUA_MONTH,'01') AS FISCAL_DATE
	,@V_TEMP_QUA_MONTH              AS FISCAL_MTH
	,V_QUA_DESC               AS DSCR_QUA
	,'50000'                  AS CITY_ID
	,'重庆市'                 AS CITY_NAME
	,CASE ORG_NAME 
		WHEN  '中国工商银行'                   THEN     'C1010211000012'
		WHEN  '中国农业银行'                   THEN     'C1010311000014'
		WHEN  '中国银行'                       THEN     'C1010411000013'
		WHEN  '中国建设银行'                   THEN     'C1010511003703'
		WHEN  '重庆农村商业银行'               THEN     'C1126750000032'
		WHEN  '交通银行'                       THEN     'C1030131001288'
		WHEN  '中信银行'                       THEN     'C1030211000389'
		WHEN  '中国光大银行'                   THEN     'C1030311000455'
		WHEN  '华夏银行'                       THEN     'C1030411000431'
		WHEN  '广发银行'                       THEN     'C1030644021075'
		WHEN  '平安银行'                       THEN     'C1030744001296'
		WHEN  '招商银行'                       THEN     'C1030844001362'
		WHEN  '浦东发展银行'                   THEN     'C1031031001312'
		WHEN  '兴业银行'                       THEN     'C1030935001347'
		WHEN  '中国民生银行'                   THEN     'C1030511000483'
		WHEN  '恒丰银行'                       THEN     'C1031537000883'
		WHEN  '浙商银行'                       THEN     'C1031633000292'
		WHEN  '渤海银行'                       THEN     'C1031812000205'
		WHEN  '重庆银行'                       THEN     'C1093150000010'
		WHEN  '成都市商业银行'                 THEN     'C1078851000017'
		WHEN  '哈尔滨市商业银行'               THEN     'C1085523000014'
		WHEN  '广东南粤银行股份有限公司'       THEN     'C1083044000019'
		WHEN  '大连银行'                       THEN     'C1081021000044'
		WHEN  '富滇银行'                       THEN     'C1091753000015'
		WHEN  '厦门银行'                       THEN     'C1082435000010'
		WHEN  '三峡银行'                       THEN     'C1093250000011'
		WHEN  '汉口银行'                       THEN     'C1085642000133'
		WHEN  '中国邮政储蓄银行'               THEN     'C1040311005293'
		WHEN  '国家开发银行'                   THEN     'C1020111000021'
		WHEN  '进出口银行'                     THEN     'C1020211000034'
		WHEN  '农业发展银行'                   THEN     'C1020311000163'
		WHEN  '重庆富民银行股份有限公司'       THEN     'C1352150000016'
		WHEN  '村镇银行'                       THEN     'C0000000000000'
		WHEN  '新华信托投资股份有限公司'       THEN     'D1006450000011'
		WHEN  '重庆国际信托投资有限公司'       THEN     'D1006550000012'
		WHEN  '重庆化医控股集团财务有限公司'   THEN     'C5012650000014'
		WHEN  '重庆机电控股集团财务有限公司'   THEN     'C5015250000029'
		WHEN  '重庆力帆财务有限公司'           THEN     'C5018850000014'
		WHEN  '重庆市能源投资集团财务有限公司' THEN     'C5020350000017'
		WHEN  '昆仑金融租赁有限责任公司'       THEN     'D3002550000015'
		WHEN  '渝农商金融租赁有限公司'         THEN     'D3003150000017'
		WHEN  '重庆汽车金融有限公司'           THEN     'D4001550000016'
		WHEN  '重庆鈊渝金融租赁有限公司'       THEN     'D3008550000011'
		WHEN  '贷款公司'                       THEN     'Z1142850000012'
		ELSE '9999'
	END AS ORG_ID  
	,T.ORG_NAME AS ORG_NAME
	,'1' AS LOAN_TYPE_ID
	,'个人精准扶贫贷款' AS LOAN_TYPE_NAME
	,SUM(CASE WHEN data_date = @V_TEMP_QUA_MONTH THEN IFNULL(LOAN_BAL_2,0) + IFNULL(LOAN_BAL_4,0) ELSE 0 END )/10000       AS LOAN_REMAIN
	,SUM(CASE WHEN data_date = @V_TEMP_QUA_MONTH_L THEN IFNULL(LOAN_BAL_2,0) + IFNULL(LOAN_BAL_4,0) ELSE 0 END )/10000      AS LOAN_REMAIN_LY
	,SUM(CASE WHEN data_date = @V_TEMP_QUA_MONTH THEN IFNULL(LOAN_BAL_ADD_Y_2,0) + IFNULL(LOAN_BAL_ADD_Y_4,0) ELSE 0 END )/10000   AS LOAN_FF
	,SUM(CASE WHEN data_date = @V_TEMP_QUA_MONTH_L THEN IFNULL(LOAN_BAL_ADD_Y_2,0) + IFNULL(LOAN_BAL_ADD_Y_4,0) ELSE 0 END )/10000   AS LOAN_FF_LY
	,0 AS STROKE_COUNT
	,SUM(CASE WHEN data_date = @V_TEMP_QUA_MONTH_L THEN IFNULL(LOAN_COUNT_19,0) + IFNULL(LOAN_COUNT_31,0) ELSE 0 END )   AS SPUR_SERV_POOR_NUM
     FROM EDW.GLR_TPA_ORG_LOAN t
     WHERE DATA_DATE IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
     GROUP BY 
     CASE ORG_NAME 
		WHEN  '中国工商银行'                   THEN     'C1010211000012'
		WHEN  '中国农业银行'                   THEN     'C1010311000014'
		WHEN  '中国银行'                       THEN     'C1010411000013'
		WHEN  '中国建设银行'                   THEN     'C1010511003703'
		WHEN  '重庆农村商业银行'               THEN     'C1126750000032'
		WHEN  '交通银行'                       THEN     'C1030131001288'
		WHEN  '中信银行'                       THEN     'C1030211000389'
		WHEN  '中国光大银行'                   THEN     'C1030311000455'
		WHEN  '华夏银行'                       THEN     'C1030411000431'
		WHEN  '广发银行'                       THEN     'C1030644021075'
		WHEN  '平安银行'                       THEN     'C1030744001296'
		WHEN  '招商银行'                       THEN     'C1030844001362'
		WHEN  '浦东发展银行'                   THEN     'C1031031001312'
		WHEN  '兴业银行'                       THEN     'C1030935001347'
		WHEN  '中国民生银行'                   THEN     'C1030511000483'
		WHEN  '恒丰银行'                       THEN     'C1031537000883'
		WHEN  '浙商银行'                       THEN     'C1031633000292'
		WHEN  '渤海银行'                       THEN     'C1031812000205'
		WHEN  '重庆银行'                       THEN     'C1093150000010'
		WHEN  '成都市商业银行'                 THEN     'C1078851000017'
		WHEN  '哈尔滨市商业银行'               THEN     'C1085523000014'
		WHEN  '广东南粤银行股份有限公司'       THEN     'C1083044000019'
		WHEN  '大连银行'                       THEN     'C1081021000044'
		WHEN  '富滇银行'                       THEN     'C1091753000015'
		WHEN  '厦门银行'                       THEN     'C1082435000010'
		WHEN  '三峡银行'                       THEN     'C1093250000011'
		WHEN  '汉口银行'                       THEN     'C1085642000133'
		WHEN  '中国邮政储蓄银行'               THEN     'C1040311005293'
		WHEN  '国家开发银行'                   THEN     'C1020111000021'
		WHEN  '进出口银行'                     THEN     'C1020211000034'
		WHEN  '农业发展银行'                   THEN     'C1020311000163'
		WHEN  '重庆富民银行股份有限公司'       THEN     'C1352150000016'
		WHEN  '村镇银行'                       THEN     'C0000000000000'
		WHEN  '新华信托投资股份有限公司'       THEN     'D1006450000011'
		WHEN  '重庆国际信托投资有限公司'       THEN     'D1006550000012'
		WHEN  '重庆化医控股集团财务有限公司'   THEN     'C5012650000014'
		WHEN  '重庆机电控股集团财务有限公司'   THEN     'C5015250000029'
		WHEN  '重庆力帆财务有限公司'           THEN     'C5018850000014'
		WHEN  '重庆市能源投资集团财务有限公司' THEN     'C5020350000017'
		WHEN  '昆仑金融租赁有限责任公司'       THEN     'D3002550000015'
		WHEN  '渝农商金融租赁有限公司'         THEN     'D3003150000017'
		WHEN  '重庆汽车金融有限公司'           THEN     'D4001550000016'
		WHEN  '重庆鈊渝金融租赁有限公司'       THEN     'D3008550000011'
		WHEN  '贷款公司'                       THEN     'Z1142850000012'
		ELSE '9999'
	END
	,T.ORG_NAME
	)TEMP 
	LEFT JOIN DMCODE.t_org_biz_lvl R 
	ON TEMP.ORG_ID = R.ORG_ID
	
       UNION ALL
       #2.金融精准扶贫贷款贷款  余额|去年同期贷款余额|当年累计发放额|去年同期累计发放额|贷款笔数|带动服务贫困人口数
       SELECT 
          TEMP.FISCAL_DATE
         ,TEMP.FISCAL_MTH
         ,TEMP.DSCR_QUA
         ,TEMP.CITY_ID
         ,TEMP.CITY_NAME
         ,CASE WHEN TEMP.ORG_ID='C0000000000000' THEN 'A13' ELSE R.ORG_TYPE_ID_2 END 
         ,CASE WHEN TEMP.ORG_ID='C0000000000000' THEN '村镇银行' ELSE R.ORG_TYPE_DSCR_2 END 
         ,TEMP.ORG_ID
         ,TEMP.ORG_NAME
         ,TEMP.LOAN_TYPE_ID
         ,TEMP.LOAN_TYPE_NAME
         ,TEMP.LOAN_REMAIN
         ,TEMP.LOAN_REMAIN_LY
         ,TEMP.LOAN_FF
         ,TEMP.LOAN_FF_LY
         ,TEMP.STROKE_COUNT
         ,TEMP.SPUR_SERV_POOR_NUM
     FROM(
     SELECT 
         CONCAT(@V_TEMP_QUA_MONTH,'01') AS FISCAL_DATE
	,@V_TEMP_QUA_MONTH              AS FISCAL_MTH
	,V_QUA_DESC               AS DSCR_QUA
	,'50000'                  AS CITY_ID
	,'重庆市'                 AS CITY_NAME
	,CASE ORG_NAME 
		WHEN  '中国工商银行'                   THEN     'C1010211000012'
		WHEN  '中国农业银行'                   THEN     'C1010311000014'
		WHEN  '中国银行'                       THEN     'C1010411000013'
		WHEN  '中国建设银行'                   THEN     'C1010511003703'
		WHEN  '重庆农村商业银行'               THEN     'C1126750000032'
		WHEN  '交通银行'                       THEN     'C1030131001288'
		WHEN  '中信银行'                       THEN     'C1030211000389'
		WHEN  '中国光大银行'                   THEN     'C1030311000455'
		WHEN  '华夏银行'                       THEN     'C1030411000431'
		WHEN  '广发银行'                       THEN     'C1030644021075'
		WHEN  '平安银行'                       THEN     'C1030744001296'
		WHEN  '招商银行'                       THEN     'C1030844001362'
		WHEN  '浦东发展银行'                   THEN     'C1031031001312'
		WHEN  '兴业银行'                       THEN     'C1030935001347'
