    SET V_STEP:='3';
    DELETE  FROM ADM.ANA_GLR_MTH_FINA_JZFP_1 WHERE FISCAL_MTH = @V_TEMP_QUA_MONTH;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
   
    SET V_STEP:='4';
    INSERT INTO ADM.ANA_GLR_MTH_FINA_JZFP_1 (
      FISCAL_DATE                #月份_date
     ,FISCAL_MTH                 #月份
     ,DSCR_QUA                   #该月对应季度描述
     ,CITY_ID                    #市编码
     ,CITY_NAME                  #市名称
     ,LOAN_TYPE_ID               #贷款类型ID
     ,LOAN_TYPE_NAME             #贷款类型描述
     ,LOAN_REMAIN                #贷款余额
     ,LOAN_FF                    #当年累计发放额
     ,LOAN_FF_LYTB               #当年累计发放额同比增长
     )
   #1. 个人精准扶贫贷款 贷款余额|去年同期贷款余额|当年累计发放额|去年同期累计发放额|贷款笔数|带动服务贫困人口数
    SELECT 
        CONCAT(@V_TEMP_QUA_MONTH,'01') AS FISCAL_DATE
       ,@V_TEMP_QUA_MONTH              AS FISCAL_MTH
       ,V_QUA_DESC               AS DSCR_QUA
       ,'50000'                  AS CITY_ID
       ,'重庆市'                 AS CITY_NAME
       ,'1'                      AS LOAN_TYPE_ID
       ,'个人精准扶贫贷款'       AS LOAN_TYPE_NAME
       ,SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )/10000  AS LOAN_REMAIN
       ,SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )/10000  AS LOAN_FF
       ,CASE WHEN SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END )=0 THEN 0 ELSE (SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ) - SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ))
        /SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ) END      AS LOAN_FF_LYTB
    FROM edw.GLR_TPA_TYPE_LOAN T
    WHERE DATA_DATE IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
    AND T.ROWS_ID IN ('24','25','42','43')
    GROUP BY @V_TEMP_QUA_MONTH
  
    UNION ALL
    #2.金融精准扶贫贷款(一、建档立卡贫困人口贷款 +三、其他个人精准扶贫贷款+四、产业精准扶贫贷款+五、项目精准扶贫贷款)：贷款余额|去年同期贷款余额|当年累计发放额|去年同期累计发放额|贷款笔数|带动服务贫困人口数
    SELECT 
        CONCAT(@V_TEMP_QUA_MONTH,'01') AS FISCAL_DATE
       ,@V_TEMP_QUA_MONTH              AS FISCAL_MTH
       ,V_QUA_DESC               AS DSCR_QUA
       ,'50000'                  AS CITY_ID
       ,'重庆市'                 AS CITY_NAME
       ,'2'                      AS LOAN_TYPE_ID
       ,'金融精准扶贫贷款'       AS LOAN_TYPE_NAME
       ,SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )/10000  AS LOAN_REMAIN
       ,SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )/10000  AS LOAN_FF
       ,CASE WHEN SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END )=0 THEN 0 ELSE (SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ) - SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ))
        /SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ) END      AS LOAN_FF_LYTB
    FROM edw.GLR_TPA_TYPE_LOAN T
    WHERE DATA_DATE IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
    AND T.ROWS_ID IN ('24','25','42','43','56','57','77','78')
    GROUP BY @V_TEMP_QUA_MONTH
    
    UNION ALL
    
    #3. 金融精准扶贫贷款(含已脱贫人口)
    SELECT 
        CONCAT(@V_TEMP_QUA_MONTH,'01') AS FISCAL_DATE
       ,@V_TEMP_QUA_MONTH              AS FISCAL_MTH
       ,V_QUA_DESC               AS DSCR_QUA
       ,'50000'                  AS CITY_ID
       ,'重庆市'                 AS CITY_NAME
       ,'3'                      AS LOAN_TYPE_ID
       ,'金融精准扶贫贷款(含已脱贫人口)'       AS LOAN_TYPE_NAME
       ,SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )/10000  AS LOAN_REMAIN
       ,SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )/10000  AS LOAN_FF
       ,CASE WHEN SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END )=0 THEN 0 ELSE (SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ) - SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ))
        /SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ) END      AS LOAN_FF_LYTB
    FROM edw.GLR_TPA_TYPE_LOAN T
   WHERE DATA_DATE IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
    AND T.ROWS_ID IN ('11','24','25','42','43','56','57','77','78')
    GROUP BY @V_TEMP_QUA_MONTH
   
   UNION ALL
   
   #4. 产业精准扶贫贷款 贷款余额|去年同期贷款余额|当年累计发放额|去年同期累计发放额|贷款笔数|带动服务贫困人口数
   SELECT 
        CONCAT(@V_TEMP_QUA_MONTH,'01') AS FISCAL_DATE
       ,@V_TEMP_QUA_MONTH              AS FISCAL_MTH
       ,V_QUA_DESC               AS DSCR_QUA
       ,'50000'                  AS CITY_ID
       ,'重庆市'                 AS CITY_NAME
       ,'4'                      AS LOAN_TYPE_ID
       ,'产业精准扶贫贷款'       AS LOAN_TYPE_NAME
       ,SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )/10000  AS LOAN_REMAIN
       ,SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )/10000  AS LOAN_FF
       ,CASE WHEN SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END )=0 THEN 0 ELSE (SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ) - SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ))
        /SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ) END      AS LOAN_FF_LYTB
    FROM edw.GLR_TPA_TYPE_LOAN T
   WHERE DATA_DATE IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
    AND T.ROWS_ID IN ('56','57')
    GROUP BY @V_TEMP_QUA_MONTH
    
    UNION ALL 
    
    #5. 项目精准扶贫贷款  贷款余额|去年同期贷款余额|当年累计发放额|去年同期累计发放额|贷款笔数|带动服务贫困人口数
       SELECT 
        CONCAT(@V_TEMP_QUA_MONTH,'01') AS FISCAL_DATE
       ,@V_TEMP_QUA_MONTH              AS FISCAL_MTH
       ,V_QUA_DESC               AS DSCR_QUA
       ,'50000'                  AS CITY_ID
       ,'重庆市'                 AS CITY_NAME
       ,'5'                      AS LOAN_TYPE_ID
       ,'项目精准扶贫贷款'       AS LOAN_TYPE_NAME
       ,SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )/10000  AS LOAN_REMAIN
       ,SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )/10000  AS LOAN_FF
       ,CASE WHEN SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN IFNULL(LOAN_BAL_Y,0) ELSE 0 END )=0 THEN 0 ELSE (SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ) - SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ))
        /SUM(CASE WHEN T.DATA_DATE =@V_TEMP_QUA_MONTH_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END ) END      AS LOAN_FF_LYTB
    FROM edw.GLR_TPA_TYPE_LOAN T
   WHERE DATA_DATE IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
    AND T.ROWS_ID IN ('77','78')
    GROUP BY @V_TEMP_QUA_MONTH
    
    ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_NAN_TPA_POOR_RESULTS_BAK20190122
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_NAN_TPA_POOR_RESULTS_BAK20190122`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_NAN_TPA_POOR_RESULTS_BAK20190122`(IN P_DATA_DATE VARCHAR(8),OUT P_RESULT   INT)
BEGIN
/*
| Author :严锦涛
| Name :ADM.ana_glr_mth_small_micro_map
| FUNCTION:
| Purpose:货币信贷-专题分析-扶贫效果分析
|         EDW.GLR_TPA_TYPE_LOAN|全金融机构金融精准扶贫贷款统计表分类别|adm.ana_glr_mth_fina_jzfp
|    
|
| VER         DATE        AUTHOR           DESCRIPTION
| ---------  ----------  ---------------  ------------------------------------
| 1.0        2019-01-02     严锦涛        1.CREATES THE PROCEDURE
*/     
    DECLARE V_PROC_NAME VARCHAR(200) DEFAULT 'P_NAN_TPA_POOR_RESULTS.prc';
    DECLARE V_STEP INT DEFAULT 0;
    DECLARE V_START_TIME VARCHAR(20) DEFAULT NOW();
    DECLARE V_DATA_DATE VARCHAR(6) DEFAULT SUBSTR(P_DATA_DATE,1,6);
    DECLARE V_DATA_DATE_L VARCHAR(6) DEFAULT SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 12 MONTH),'%Y%m%d'),1,6);
    declare V_QUA_DESC VARCHAR(100) DEFAULT concat(DATE_FORMAT( P_DATA_DATE, '%Y' ),'年','第',QUARTER(P_DATA_DATE),'季度');
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    SET P_RESULT = 0;
    
    SET V_STEP:='1';
    DELETE  FROM ADM.ANA_GLR_MTH_FINA_JZFP WHERE FISCAL_MTH = V_DATA_DATE;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='2';
    insert into ADM.ana_glr_mth_fina_jzfp (
      FISCAL_DATE                #月份_date
     ,FISCAL_MTH                 #月份
     ,DSCR_QUA                   #该月对应季度描述
     ,CITY_ID                    #市编码
     ,CITY_NAME                  #市名称
     ,ORG_TYPE_ID                #金融机构类型编码
     ,ORG_TYPE_NAME              #金融机构类型名称
     ,ORG_ID                     #金融机构编码
     ,ORG_NAME                   #金融机构名称
     ,LOAN_TYPE_ID               #贷款类型ID
     ,LOAN_TYPE_NAME             #贷款类型描述
     ,LOAN_REMAIN                #贷款余额
     ,LOAN_REMAIN_LY             #去年同期贷款余额
     ,LOAN_FF                    #当年累计发放额
     ,LOAN_FF_LY                 #去年同期累计发放额
     ,STROKE_COUNT               #贷款笔数
     ,SPUR_SERV_POOR_NUM         #带动服务贫困人口数
     
     )

   #1. 个人精准扶贫贷款 贷款余额|去年同期贷款余额|当年累计发放额|去年同期累计发放额|贷款笔数|带动服务贫困人口数
    SELECT 
        CONCAT(V_DATA_DATE,'01') AS FISCAL_DATE
       ,V_DATA_DATE              AS FISCAL_MTH
       ,V_QUA_DESC               AS DSCR_QUA
       ,'50000'                  AS CITY_ID
       ,'重庆市'                 AS CITY_NAME
       ,O.ORG_TYPE_ID_2          AS ORG_TYPE_ID
       ,O.ORG_TYPE_DSCR_2        AS ORG_TYPE_NAME
       ,O.ORG_ID                 AS ORG_ID
       ,O.ORG_DSCR               AS ORG_NAME
       ,'1'                      AS LOAN_TYPE_ID
       ,'个人精准扶贫贷款'       AS LOAN_TYPE_NAME
       ,SUM(CASE WHEN T.ROWS_ID=13 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS LOAN_REMAIN
       ,SUM(CASE WHEN T.ROWS_ID=13 AND  T.DATA_DATE =V_DATA_DATE_L THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS LOAN_REMAIN_LY   
       ,SUM(CASE WHEN T.ROWS_ID=13 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )  AS LOAN_FF
       ,SUM(CASE WHEN T.ROWS_ID=13 AND  T.DATA_DATE =V_DATA_DATE_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )  AS LOAN_FF_LY
       ,SUM(CASE WHEN T.ROWS_ID=49 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS STROKE_COUNT
       ,SUM(CASE WHEN T.ROWS_ID=50 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS SPUR_SERV_POOR_NUM
       
    FROM edw.GLR_TPA_TYPE_LOAN T
    LEFT JOIN DMCODE.t_org_biz_lvl O
    ON T.ORG_NO = O.ORG_ID
    GROUP BY O.ORG_TYPE_ID_2,O.ORG_TYPE_DSCR_2,O.ORG_ID ,O.ORG_DSCR
  
    UNION ALL

    #2.金融精准扶贫贷款(一、建档立卡贫困人口贷款 +二、已脱贫人口贷款+三、其他个人精准扶贫贷款+四、产业精准扶贫贷款+五、项目精准扶贫贷款)：贷款余额|去年同期贷款余额|当年累计发放额|去年同期累计发放额|贷款笔数|带动服务贫困人口数
    select 
        CONCAT(V_DATA_DATE,'01') AS FISCAL_DATE
       ,V_DATA_DATE              AS FISCAL_MTH
       ,V_QUA_DESC               AS DSCR_QUA
       ,'50000'                  AS CITY_ID
       ,'重庆市'                 AS CITY_NAME
       ,O.ORG_TYPE_ID_2          AS ORG_TYPE_ID
       ,O.ORG_TYPE_DSCR_2        AS ORG_TYPE_NAME
       ,O.ORG_ID                 AS ORG_ID
       ,O.ORG_DSCR               AS ORG_NAME
       ,'2'                      AS LOAN_TYPE_ID
       ,'金融精准扶贫贷款'       AS LOAN_TYPE_NAME
       ,SUM(CASE WHEN T.ROWS_ID in(16,34,37,51) AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS LOAN_REMAIN
       ,SUM(CASE WHEN T.ROWS_ID IN(16,34,37,51) AND  T.DATA_DATE =V_DATA_DATE_L THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS LOAN_REMAIN_LY   
       ,SUM(CASE WHEN T.ROWS_ID IN(16,34,37,51) AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )  AS LOAN_FF
       ,SUM(CASE WHEN T.ROWS_ID IN(16,34,37,51) AND  T.DATA_DATE =V_DATA_DATE_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )  AS LOAN_FF_LY
       ,SUM(CASE WHEN T.ROWS_ID in(32,49,63,86) AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS STROKE_COUNT
       ,SUM(CASE WHEN T.ROWS_ID in(33,50,64,87) AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS SPUR_SERV_POOR_NUM
       
    FROM edw.GLR_TPA_TYPE_LOAN T
    LEFT JOIN DMCODE.t_org_biz_lvl O
    ON T.ORG_NO = O.ORG_ID
    GROUP BY O.ORG_TYPE_ID_2,O.ORG_TYPE_DSCR_2,O.ORG_ID ,O.ORG_DSCR
    
    union all
    
    #3. 金融精准扶贫贷款(含已脱贫人口)
    SELECT 
        CONCAT(V_DATA_DATE,'01') AS FISCAL_DATE
       ,V_DATA_DATE              AS FISCAL_MTH
       ,V_QUA_DESC               AS DSCR_QUA
       ,'50000'                  AS CITY_ID
       ,'重庆市'                 AS CITY_NAME
       ,O.ORG_TYPE_ID_2          AS ORG_TYPE_ID
       ,O.ORG_TYPE_DSCR_2        AS ORG_TYPE_NAME
       ,O.ORG_ID                 AS ORG_ID
       ,O.ORG_DSCR               AS ORG_NAME
       ,'3'                      AS LOAN_TYPE_ID
       ,'金融精准扶贫贷款(含已脱贫人口)'       AS LOAN_TYPE_NAME
       ,SUM(CASE WHEN T.ROWS_ID IN(11,16,34,37,51) AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS LOAN_REMAIN
       ,SUM(CASE WHEN T.ROWS_ID IN(11,16,34,37,51) AND  T.DATA_DATE =V_DATA_DATE_L THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS LOAN_REMAIN_LY   
       ,SUM(CASE WHEN T.ROWS_ID IN(11,16,34,37,51) AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )  AS LOAN_FF
       ,SUM(CASE WHEN T.ROWS_ID IN(11,16,34,37,51) AND  T.DATA_DATE =V_DATA_DATE_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )  AS LOAN_FF_LY
       ,SUM(CASE WHEN T.ROWS_ID IN(32,35,49,63,86) AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS STROKE_COUNT
       ,SUM(CASE WHEN T.ROWS_ID IN(33,36,50,64,87) AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS SPUR_SERV_POOR_NUM
       
    FROM edw.GLR_TPA_TYPE_LOAN T
    LEFT JOIN DMCODE.t_org_biz_lvl O
    ON T.ORG_NO = O.ORG_ID
    GROUP BY O.ORG_TYPE_ID_2,O.ORG_TYPE_DSCR_2,O.ORG_ID ,O.ORG_DSCR
   
   union all
   
   #4. 产业精准扶贫贷款 贷款余额|去年同期贷款余额|当年累计发放额|去年同期累计发放额|贷款笔数|带动服务贫困人口数
   SELECT 
        CONCAT(V_DATA_DATE,'01') AS FISCAL_DATE
       ,V_DATA_DATE              AS FISCAL_MTH
       ,V_QUA_DESC               AS DSCR_QUA
       ,'50000'                  AS CITY_ID
       ,'重庆市'                 AS CITY_NAME
       ,O.ORG_TYPE_ID_2          AS ORG_TYPE_ID
       ,O.ORG_TYPE_DSCR_2        AS ORG_TYPE_NAME
       ,O.ORG_ID                 AS ORG_ID
       ,O.ORG_DSCR               AS ORG_NAME
       ,'4'                      AS LOAN_TYPE_ID
       ,'产业精准扶贫贷款'       AS LOAN_TYPE_NAME
       ,SUM(CASE WHEN T.ROWS_ID=51 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS LOAN_REMAIN
       ,SUM(CASE WHEN T.ROWS_ID=51 AND  T.DATA_DATE =V_DATA_DATE_L THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS LOAN_REMAIN_LY   
       ,SUM(CASE WHEN T.ROWS_ID=51 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )  AS LOAN_FF
       ,SUM(CASE WHEN T.ROWS_ID=51 AND  T.DATA_DATE =V_DATA_DATE_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )  AS LOAN_FF_LY
       ,SUM(CASE WHEN T.ROWS_ID=63 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS STROKE_COUNT
       ,SUM(CASE WHEN T.ROWS_ID=64 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS SPUR_SERV_POOR_NUM
       
    FROM edw.GLR_TPA_TYPE_LOAN T
    LEFT JOIN DMCODE.t_org_biz_lvl O
    ON T.ORG_NO = O.ORG_ID
    GROUP BY O.ORG_TYPE_ID_2,O.ORG_TYPE_DSCR_2,O.ORG_ID ,O.ORG_DSCR
    
    union all 
    
    #5. 项目精准扶贫贷款  贷款余额|去年同期贷款余额|当年累计发放额|去年同期累计发放额|贷款笔数|带动服务贫困人口数
       SELECT 
        CONCAT(V_DATA_DATE,'01') AS FISCAL_DATE
       ,V_DATA_DATE              AS FISCAL_MTH
       ,V_QUA_DESC               AS DSCR_QUA
       ,'50000'                  AS CITY_ID
       ,'重庆市'                 AS CITY_NAME
       ,O.ORG_TYPE_ID_2          AS ORG_TYPE_ID
       ,O.ORG_TYPE_DSCR_2        AS ORG_TYPE_NAME
       ,O.ORG_ID                 AS ORG_ID
       ,O.ORG_DSCR               AS ORG_NAME
       ,'5'                      AS LOAN_TYPE_ID
       ,'项目精准扶贫贷款'       AS LOAN_TYPE_NAME
       ,SUM(CASE WHEN T.ROWS_ID=65 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS LOAN_REMAIN
       ,SUM(CASE WHEN T.ROWS_ID=65 AND  T.DATA_DATE =V_DATA_DATE_L THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS LOAN_REMAIN_LY   
       ,SUM(CASE WHEN T.ROWS_ID=65 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )  AS LOAN_FF
       ,SUM(CASE WHEN T.ROWS_ID=65 AND  T.DATA_DATE =V_DATA_DATE_L THEN  IFNULL(LOAN_BAL_Y,0) ELSE 0 END )  AS LOAN_FF_LY
       ,SUM(CASE WHEN T.ROWS_ID=86 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS STROKE_COUNT
       ,SUM(CASE WHEN T.ROWS_ID=87 AND  T.DATA_DATE =V_DATA_DATE   THEN  IFNULL(LOAN_BAL,0) ELSE 0 END )  AS SPUR_SERV_POOR_NUM
       
    FROM edw.GLR_TPA_TYPE_LOAN T
    LEFT JOIN DMCODE.t_org_biz_lvl O
    ON T.ORG_NO = O.ORG_ID
    GROUP BY O.ORG_TYPE_ID_2,O.ORG_TYPE_DSCR_2,O.ORG_ID ,O.ORG_DSCR
    
    
    ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_RPT_FINANCE_KEY_KPI_MTH
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_RPT_FINANCE_KEY_KPI_MTH`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_RPT_FINANCE_KEY_KPI_MTH`(IN P_DATA_DATE VARCHAR(8),OUT P_RESULT   INT)
BEGIN
 /*
    Author :yanjintao
    Name :ADM.P_RPT_FINANCE_KEY_KPI_MTH.PRC
    FUNCTION:
    Purpose:调统-两江新区金融业主要指标情况月表(ADM.RPT_FINANCE_KEY_KPI_MTH)
    VER         DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2019-02-26     yanjintao        1.CREATES THE PROCEDURE
*/     
    DECLARE V_PROC_NAME VARCHAR(200) DEFAULT 'ADM.P_RPT_FINANCE_KEY_KPI_MTH.PRC';
    DECLARE V_STEP INT DEFAULT 0;
    DECLARE V_START_TIME VARCHAR(20) DEFAULT NOW();
    /* EXCEPTION HANDLER  异常处理*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    
    
    SET P_RESULT = 0;
    -- 支持数据重跑
    SET V_STEP:='1';
    DELETE  FROM ADM.RPT_FINANCE_KEY_KPI_MTH WHERE DATA_DATE = P_DATA_DATE ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    SET V_STEP:='2';
    INSERT INTO ADM.RPT_FINANCE_KEY_KPI_MTH(
	 BATCH_DATE                         #跑批日期                            
	,AREA_NO                            #上报地区                            
	,DATA_DATE                          #数据日期，账期                      
	,ORG_NO                             #上报机构/上报用户                   
	,ROWS_ID                            #行号                                
	,ORG_CODE                           #机构编码                            
	,ORG_NAME                           #机构名称                            
	,DEP_LOCAL_FOREIGN_BAL              #本外币存款余额(万元)                
	,DEP_LOCAL_FOREIGN_BAL_P            #上期本外币存款余额(万元)            
	,DEP_CNY_BAL                        #人民币存款余额(万元)                
	,DEP_CNY_BAL_P                      #上期人民币存款余额(万元)            
	,DEP_SAVE_BAL                       #储蓄存款(万元)                      
	,DEP_SAVE_BAL_P                     #上期储蓄存款(万元)                  
	,LOAB_LOCAL_FOREIGN_BAL             #本外币贷款余额(万元)                
	,LOAB_LOCAL_FOREIGN_BAL_P           #上期本外币贷款余额(万元)            
	,LOAN_CNY_BAL                       #人民币贷款余额(万元)                
	,LOAN_CNY_BAL_P                     #上期人民币贷款余额(万元)            
	,LOAN_SHORT_BAL                     #短期贷款余额(万元)                  
	,LOAN_SHORT_BAL_P                   #上期短期贷款余额(万元)              
	,LOAN_MID_BAL                       #中长期贷款余额(万元)                
	,LOAN_MID_BAL_P                     #上期中长期贷款余额(万元)            
	,LOAN_PERSON_MID_BAL                #个人中长期贷款(万元)                
	,LOAN_PERSON_MID_BAL_P              #上期个人中长期贷款(万元)            
	)
	SELECT 
	 NOW()
	,AREA_NO                      
	,DATA_DATE                    
	,ORG_NO                       
	,ROWS_ID                      
	,ORG_CODE                     
	,ORG_NAME                     
	,DEP_LOCAL_FOREIGN_BAL        
	,DEP_LOCAL_FOREIGN_BAL_P      
	,DEP_CNY_BAL                  
	,DEP_CNY_BAL_P                
	,DEP_SAVE_BAL                 
	,DEP_SAVE_BAL_P               
	,LOAB_LOCAL_FOREIGN_BAL       
	,LOAB_LOCAL_FOREIGN_BAL_P     
	,LOAN_CNY_BAL                 
	,LOAN_CNY_BAL_P               
	,LOAN_SHORT_BAL               
	,LOAN_SHORT_BAL_P             
	,LOAN_MID_BAL                 
	,LOAN_MID_BAL_P               
	,LOAN_PERSON_MID_BAL          
	,LOAN_PERSON_MID_BAL_P        
	FROM EDW.GLR_EDS_FINANCE_KEY_KPI_MTH
	WHERE DATA_DATE = P_DATA_DATE 
	;
	CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_RPT_M_ESTATE_STAT
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_RPT_M_ESTATE_STAT`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_RPT_M_ESTATE_STAT`(
    IN P_DATA_DATE VARCHAR(8)
    ,OUT P_RESULT   INT)
BEGIN
    /*
    Author :zhangjiao
    Name :ADM.P_RPT_M_ESTATE_STAT.PRC
    FUNCTION:
    Purpose:表3-3 重庆市房地产市场数据监测表
    VER         DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2019-01-29     ZHANGJIAO        1.CREATES THE PROCEDURE
*/     
    DECLARE V_PROC_NAME VARCHAR(200) DEFAULT 'ADM.P_RPT_M_ESTATE_STAT.prc';
    DECLARE V_STEP INT DEFAULT 0;
    DECLARE V_START_TIME VARCHAR(20) DEFAULT NOW();
    /* EXCEPTION HANDLER  异常处理*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    
    
    SET P_RESULT = 0;
    -- 支持数据重跑
    SET V_STEP:='1';
    DELETE  FROM ADM.RPT_M_ESTATE_STAT WHERE DATA_DATE = SUBSTR(P_DATA_DATE,1,6) ;
    -- 业务逻辑处理
    SET V_STEP:='2' ;   
    INSERT INTO ADM.RPT_M_ESTATE_STAT(
                BATCH_DATE  
               ,AREA_NO     
               ,DATA_DATE   
               ,ORG_NO      
               ,ROWS_ID     
               ,PROJECT     
               ,LOAN_BALANCE
                )
       SELECT
              NOW()  
             ,AREA_NO     
             ,DATA_DATE   
             ,ORG_NO      
             ,ROWS_ID     
             ,PROJECT     
             ,SUM(IFNULL(LOAN_BALANCE,0))
    FROM EDW.GLR_REL_ESTATE_LOAN_MONITOR
    WHERE DATA_DATE =SUBSTR(P_DATA_DATE,1,6)
    GROUP BY  DATA_DATE 
             ,AREA_NO  
             ,ORG_NO      
             ,ROWS_ID     
             ,PROJECT     
             ;             
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_RPT_M_FARM_LOAN_STAT
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_RPT_M_FARM_LOAN_STAT`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_RPT_M_FARM_LOAN_STAT`(
    IN P_DATA_DATE VARCHAR(8)
    ,OUT P_RESULT   INT)
BEGIN
    /*
    Author :zhangjiao
    Name :P_RPT_M_FARM_LOAN_STAT
    FUNCTION:
    Purpose:表3-10：X年X月全市涉农贷款统计表
    VER         DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-11-20     ZHANGJIAO        1.CREATES THE PROCEDURE
*/     
    DECLARE V_PROC_NAME VARCHAR(200) DEFAULT 'ADM.P_RPT_M_FARM_LOAN_STAT.prc';
    DECLARE V_STEP INT DEFAULT 0;
    DECLARE V_START_TIME VARCHAR(20) DEFAULT NOW();
    /* EXCEPTION HANDLER  异常处理*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
    
            #季度日期处理
    SELECT CONCAT('\'',CONCAT(QUARTER(DATE_FORMAT(P_DATA_DATE,'%Y%m%d')),'Q'),'\'') INTO @v_temp_qua;
        SET @instr = CONCAT('SELECT MAX(T.MONTH) AS MONTH  INTO @V_TEMP_QUA_MONTH  FROM edw.dim_date t WHERE t.QUARTER=',@v_temp_qua,'
        AND t.YEAR = ',SUBSTR(P_DATA_DATE,1,4));
        
    PREPARE smt FROM @instr;
    EXECUTE smt;
    DEALLOCATE PREPARE smt;
    
    SET P_RESULT = 0;
    -- 支持数据重跑
    SET V_STEP:='1';
    DELETE  FROM ADM.RPT_M_FARM_LOAN_STAT WHERE DATA_DATE = @V_TEMP_QUA_MONTH;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    -- 业务逻辑处理
    SET V_STEP:='2' ;   
    INSERT INTO ADM.RPT_M_FARM_LOAN_STAT(
               BACH_DATE
              ,AREA_NO
              ,DATA_DATE
              ,ORG_NO
              ,PROJECT
              ,PROJECT_ORDER
              ,LOAN_BAL
              ,LOAN_BAL_ZB
              ,LOAN_BAL_ADD_NEW
              ,LOAN_BAL_ADD_NEW_ZB
              ,LOAN_BAL_TB
               )
         SELECT                                                       
               NOW()
              ,AREA_NO
              ,DATA_DATE
              ,ORG_NO
              ,PROJECT
              ,ROWS_ID
              ,SUM(IFNULL(LOAN_BAL,0))
              ,IFNULL(LOAN_BAL_ZB,0)
              ,SUM(IFNULL(LOAN_BAL_ADD_NEW,0))
              ,IFNULL(LOAN_BAL_ADD_NEW_ZB,0)
              ,IFNULL(LOAN_BAL_TB,0)
        FROM EDW.GLR_AGL_FARM_LOAN
     WHERE DATA_DATE = @V_TEMP_QUA_MONTH
     GROUP BY  DATA_DATE
              ,AREA_NO
              ,ORG_NO
              ,PROJECT
              ,ROWS_ID;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_RPT_M_LOAN_DIST_ORG_PROJ
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_RPT_M_LOAN_DIST_ORG_PROJ`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_RPT_M_LOAN_DIST_ORG_PROJ`(
    IN P_DATA_DATE VARCHAR(8)
    ,OUT P_RESULT   INT)
BEGIN
    /*
    Author :zhangjiao
    Name :P_RPT_M_LOAN_DIST_ORG_PROJ
    FUNCTION:
    Purpose:表3-4 重庆市全金融机构（含外资）大中小型企业贷款情况表 
           :表3-5 重庆市大中小型企业贷款分机构情况表
    VER         DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2018-12-25     ZHANGJIAO        1.CREATES THE PROCEDURE
*/     
    DECLARE V_PROC_NAME VARCHAR(200) DEFAULT 'ADM.P_RPT_M_LOAN_DIST_ORG_PROJ.prc';
    DECLARE V_STEP INT DEFAULT 0;
    DECLARE V_START_TIME VARCHAR(20) DEFAULT NOW();
    DECLARE V_DATA_DATE_LM VARCHAR(20) ;
    DECLARE V_DATA_DATE_LQ VARCHAR(20) ;
    /* EXCEPTION HANDLER  异常处理*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
     #上季度日期处理
     SET V_DATA_DATE_LQ = DATE_ADD(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'), INTERVAL -3 MONTH); 
     
    SELECT CONCAT('\'',CONCAT(QUARTER(DATE_FORMAT(V_DATA_DATE_LQ,'%Y%m%d')),'Q'),'\'') INTO @v_temp_qua;
    SET @instr = CONCAT('SELECT MAX(T.MONTH) AS MONTH  INTO @V_TEMP_QUA_MONTH_L  FROM edw.dim_date t WHERE t.QUARTER=',@v_temp_qua,'
    AND t.YEAR = ',SUBSTR(V_DATA_DATE_LQ,1,4));
    
        PREPARE smt FROM @instr;
        EXECUTE smt;
        DEALLOCATE PREPARE smt;
    
    #本年季度日期处理
    SELECT CONCAT('\'',CONCAT(QUARTER(DATE_FORMAT(P_DATA_DATE,'%Y%m%d')),'Q'),'\'') INTO @v_temp_qua;
    SET @instr = CONCAT('SELECT MAX(T.MONTH) AS MONTH  INTO @V_TEMP_QUA_MONTH  FROM edw.dim_date t WHERE t.QUARTER=',@v_temp_qua,'
    AND t.YEAR = ',SUBSTR(P_DATA_DATE,1,4));
    
        PREPARE smt FROM @instr;
        EXECUTE smt;
        DEALLOCATE PREPARE smt;
    SET P_RESULT = 0;
    -- 支持数据重跑
    SET V_STEP:='1';
    DELETE  FROM ADM.RPT_M_LOAN_DIST_ORG_PROJ WHERE DATA_DATE = @V_TEMP_QUA_MONTH;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    
    
    -- 业务逻辑处理
    SET V_STEP:='2' ;   
    INSERT INTO ADM.RPT_M_LOAN_DIST_ORG_PROJ(
               BATCH_DATE
              ,DATA_DATE
              ,ORG_NO
              ,ORG_DESC
              ,KPI_CODE
              ,PROJECT_CODE
              ,PROJECT_INFO
              ,ENTER_SCALE
              ,ENTER_SCALE_DESC
              ,BALANCE_CNY          -- 本月余额
              ,BALANCE_CNY_LM       -- 比上月增减额
              ,BALANCE_CNY_Y        -- 比年初增减额
              )
      (SELECT 
            NOW()
           ,@V_TEMP_QUA_MONTH
           ,t.ORG_NO
           ,x.ORG_DSCR
           ,t.kpi_code
           ,CASE WHEN t.KPI_CODE = '33370' THEN '0'
                 WHEN t.KPI_CODE = '33520' THEN 'ZA0'
                 WHEN t.KPI_CODE = '33556' THEN 'ZB0'
                 WHEN t.KPI_CODE = '33580' THEN 'ZC0'
                 ELSE m.dim_id END 
           ,CASE WHEN t.KPI_CODE = '33370' THEN '一、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33520' THEN '二、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33556' THEN '三、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33580' THEN '四、境内企业贷款合计'
            ELSE m.dim_desc END 
           ,'CS01'
           ,'大型企业贷款'
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END)/10000 AS BALANCE_CNY
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 - SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH_L THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 AS BALANCE_CNY_LM
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 - SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_BEGIN_Y,0) ELSE 0 END )/10000 AS BALANCE_CNY_Y
      FROM EDW.GLR_MPA_CBRC_3302 t
   LEFT JOIN dmcode.t_org_biz_lvl X
           ON t.ORG_NO = x.ORG_ID
   LEFT JOIN edw.rpt_indust_guarn_mas_mapping M
           ON M.MAPPING_ID = T.KPI_CODE
   WHERE KPI_CODE IN ('33370','33371','33372','33373','33374','33375','33376','33377','33378','33379','33380','33381','33382','33383','33384','33385','33386','33387','33388','33389','33390','33391'
                      ,'33392','33393','33394','33520','33521','33522','33523','33524','33525','33556','33557','33558','33559','33580','33581','33582','33583','33584','33585','33635','33641','33642','33653','33659','3369E')
        AND DATA_DATE IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
       GROUP BY 
            t.ORG_NO
           ,x.ORG_DSCR
           ,t.KPI_CODE
      ORDER BY t.KPI_CODE)
           
UNION ALL 
           
    (SELECT 
            NOW()
           ,@V_TEMP_QUA_MONTH
           ,t.ORG_NO
           ,x.ORG_DSCR
           ,t.kpi_code
           ,CASE WHEN t.KPI_CODE = '33395' THEN '0'
                 WHEN t.KPI_CODE = '33526' THEN 'ZA0'
                 WHEN t.KPI_CODE = '33560' THEN 'ZB0'
                 WHEN t.KPI_CODE = '33586' THEN 'ZC0'
                 ELSE m.dim_id END 
           ,CASE WHEN t.KPI_CODE = '33395' THEN '一、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33526' THEN '二、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33560' THEN '三、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33586' THEN '四、境内企业贷款合计'
            ELSE m.dim_desc END 
           ,'CS02'
           ,'中型企业贷款'
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 AS BALANCE_CNY
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 - SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH_L THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 AS BALANCE_CNY_LM
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 - SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_BEGIN_Y,0) ELSE 0 END )/10000 AS BALANCE_CNY_Y
       FROM EDW.GLR_MPA_CBRC_3302 t
    LEFT JOIN dmcode.t_org_biz_lvl X
           ON t.ORG_NO = x.ORG_ID
    LEFT JOIN EDW.RPT_INDUST_GUARN_MAS_MAPPING M
           ON M.MAPPING_ID = T.KPI_CODE
      WHERE KPI_CODE IN ('33395','33396','33397','33398','33399','33400','33401','33402','33403','33404','33405','33406','33407','33408','33409','33410','33411','33412','33413','33414','33415','33416'
                         ,'33417','33418','33419','33526','33527','33528','','33530','33531','33560','33561','33562','33563','33586','33587','33588','33589','33590','33591','33636','33643','33644','33654','33660','3369F')
            AND DATA_DATE IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
      GROUP BY 
            t.ORG_NO
           ,x.ORG_DSCR
           ,t.KPI_CODE
      ORDER BY t.KPI_CODE)
           
UNION ALL 
           
      (SELECT 
            NOW()
           ,@V_TEMP_QUA_MONTH
           ,t.ORG_NO
           ,x.ORG_DSCR
           ,t.KPI_CODE
           ,CASE WHEN t.KPI_CODE = '33420' THEN '0'
                 WHEN t.KPI_CODE = '33532' THEN 'ZA0'
                 WHEN t.KPI_CODE = '33564' THEN 'ZB0'
                 WHEN t.KPI_CODE = '33592' THEN 'ZC0'
                 ELSE m.dim_id END 
           ,CASE WHEN t.KPI_CODE = '33420' THEN '一、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33532' THEN '二、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33564' THEN '三、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33592' THEN '四、境内企业贷款合计'
            ELSE m.dim_desc END 
           ,'CS03'
           ,'小型企业贷款'
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 AS BALANCE_CNY
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 - SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH_L THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 AS BALANCE_CNY_LM
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 - SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_BEGIN_Y,0) ELSE 0 END )/10000 AS BALANCE_CNY_Y
      FROM EDW.GLR_MPA_CBRC_3302 t
    LEFT JOIN dmcode.t_org_biz_lvl X
          ON t.ORG_NO = x.ORG_ID
    LEFT JOIN EDW.RPT_INDUST_GUARN_MAS_MAPPING M
           ON M.MAPPING_ID = T.KPI_CODE
     WHERE KPI_CODE IN ('33420','33421','33422','33423','33424','33425','33426','33427','33428','33429','33430','33431','33432','33433','33434','33435','33436','33437','33438','33439','33440','33441'
                       ,'33442','33443','33444','33532','33533','33534','33535','33536','33537','33564','33565','33566','33567','33592','33593','33594','33595','33596','33597','33637','33645','33646','33655','33661','33665')
        AND DATA_DATE IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
      GROUP BY 
            t.ORG_NO
           ,x.ORG_DSCR
           ,t.KPI_CODE
     ORDER BY t.KPI_CODE)
           
UNION ALL 
           
      (SELECT 
            NOW()
           ,@V_TEMP_QUA_MONTH
           ,t.ORG_NO
           ,x.ORG_DSCR
           ,t.KPI_CODE
           ,CASE WHEN t.KPI_CODE = '33445' THEN '0'
                 WHEN t.KPI_CODE = '33538' THEN 'ZA0'
                 WHEN t.KPI_CODE = '33568' THEN 'ZB0'
                 WHEN t.KPI_CODE = '33598' THEN 'ZC0'
                 ELSE m.dim_id END 
           ,CASE WHEN t.KPI_CODE = '33445' THEN '一、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33538' THEN '二、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33568' THEN '三、境内企业贷款合计'
                 WHEN t.KPI_CODE = '33598' THEN '四、境内企业贷款合计'
            ELSE m.dim_desc END 
           ,'CS04'
           ,'其中：单户授信总额500万元以下的小型企业贷款'
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 AS BALANCE_CNY
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 - SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH_L THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 AS BALANCE_CNY_LM
           ,SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_CNY,0) ELSE 0 END )/10000 - SUM(CASE WHEN DATA_DATE=@V_TEMP_QUA_MONTH THEN IFNULL(BALANCE_BEGIN_Y,0) ELSE 0 END )/10000 AS BALANCE_CNY_Y
      FROM EDW.GLR_MPA_CBRC_3302 t
      LEFT JOIN dmcode.t_org_biz_lvl X
           ON t.ORG_NO = x.ORG_ID
      LEFT JOIN EDW.RPT_INDUST_GUARN_MAS_MAPPING M
           ON M.MAPPING_ID = T.KPI_CODE
      WHERE KPI_CODE IN ('33445','33446','33447','33448','33449','33450','33451','33452','33453','33454','33455','33456','33457','33458','33459','33460','33461','33462','33463','33464','33465','33466'
                         ,'33467','33468','33469','33538','33539','33540','33541','33542','33543','33568','33569','33570','33571','33598','33599','33600','33620','33621','33622','33638','33647','33648','33656','33662','33666')
       AND DATA_DATE IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
     GROUP BY 
            t.ORG_NO
           ,x.ORG_DSCR
           ,t.KPI_CODE
     ORDER BY t.KPI_CODE)
           
UNION ALL 
           
      (SELECT 
            NOW()
           ,@V_TEMP_QUA_MONTH
           ,t.ORG_NO
           ,x.ORG_DSCR
           ,t.KPI_CODE
           ,CASE WHEN t.KPI_CODE = '33470' THEN '0'
                 WHEN t.KPI_CODE = '33544' THEN 'ZA0'
                 WHEN t.KPI_CODE = '33572' THEN 'ZB0'
                 WHEN t.KPI_CODE = '33623' THEN 'ZC0'
