WHERE data_date IN (@V_TEMP_QUA_MONTH,@V_TEMP_QUA_MONTH_L)
GROUP BY  
          t.AREA_NO  
         ,t.DIST_NAME
;
CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for P_RPT_M_LOAN_SUM_INDUS
-- ----------------------------
DROP PROCEDURE IF EXISTS `P_RPT_M_LOAN_SUM_INDUS`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `P_RPT_M_LOAN_SUM_INDUS`(
    IN P_DATA_DATE VARCHAR(8)
    ,OUT P_RESULT   INT)
BEGIN
    /*
    Author :zhangjiao
    Name :P_RPT_M_LOAN_SUM_INDUS
    FUNCTION:
    Purpose:表2-5 重庆市贷款汇总表（分行业投向）
    VER         DATE        AUTHOR           DESCRIPTION
    ---------  ----------  ---------------  ------------------------------------
    1.0        2019-01-25    ZHANGJIAO        1.CREATES THE PROCEDURE
*/     
    DECLARE V_PROC_NAME VARCHAR(200) DEFAULT 'ADM.P_RPT_M_LOAN_SUM_INDUS.PRC';
    DECLARE V_STEP INT DEFAULT 0;
    DECLARE V_START_TIME VARCHAR(20) DEFAULT NOW();
    DECLARE V_DATA_DATE VARCHAR(20) DEFAULT SUBSTR(P_DATA_DATE,1,6);
    DECLARE V_DATA_DATE_L VARCHAR(20) DEFAULT SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 1 MONTH),'%Y%m%d'),1,6);                             -- 上月
    DECLARE V_DATA_DATE_BGY VARCHAR(20) DEFAULT CONCAT(SUBSTR(P_DATA_DATE,1,4),'01');                                                                 -- 年初
    DECLARE V_DATA_DATE_E VARCHAR(20) DEFAULT CONCAT(SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 12 MONTH),'%Y%m%d'),1,4),'12');               -- 去年末
    DECLARE V_DATA_DATE_P VARCHAR(8) DEFAULT SUBSTR(DATE_FORMAT(DATE_SUB(DATE_FORMAT(P_DATA_DATE,'%Y%m%d'),INTERVAL 12 MONTH),'%Y%m%d'),1,6);                             -- 去年同期
    /* EXCEPTION HANDLER  异常处理*/
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 @V_RETURN_CODE = RETURNED_SQLSTATE ,@V_ERROR_MSG = MESSAGE_TEXT;
        CALL ETL.EDW_PROC_ERROR_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,@V_RETURN_CODE,@V_ERROR_MSG);
        SET P_RESULT = 1;
    END;
        
    SET P_RESULT = 0;
    -- 支持数据重跑
    SET V_STEP:='1';
    DELETE  FROM ADM.RPT_M_LOAN_SUM_INDUS WHERE DATA_DATE = SUBSTR(P_DATA_DATE,1,6);
    -- 业务逻辑处理
    SET V_STEP:='2' ;   
    INSERT INTO ADM.RPT_M_LOAN_SUM_INDUS(
               BATCH_DATE      
              ,AREA_NO         
              ,DATA_DATE       
              ,ORG_NO          
              ,ROWS_ID         
              ,INDUSTRY        
              ,LOAN_BAL        
              ,LOAN_BAL_SUB_BGY
              ,LOAN_BAL_SUB_P  
              ,LOAN_BAL_TB     
            )
     SELECT
             NOW()
            ,AREA_NO
            ,V_DATA_DATE
            ,ORG_NO
            ,ROWS_ID
            ,CASE WHEN ROWS_ID ='2' THEN '汇总'
             ELSE PROJECT END
            ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(BALANCE,0) ELSE 0 END)
            ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(BALANCE,0) else 0 END)  - SUM(CASE WHEN DATA_DATE = V_DATA_DATE_BGY THEN IFNULL(BALANCE,0) ELSE 0 END)                                                           -- 比年初新增
            ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(BALANCE,0) ELSE 0 END) - SUM(CASE WHEN DATA_DATE = V_DATA_DATE_L THEN IFNULL(BALANCE,0) ELSE 0 END )                                                                                          -- 比上月新增
            ,CASE WHEN SUM(CASE WHEN DATA_DATE = V_DATA_DATE_P THEN IFNULL(BALANCE,0) ELSE 0 END) = 0 THEN 0 ELSE 
             (SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(BALANCE,0) ELSE 0 END) - SUM(CASE WHEN DATA_DATE = V_DATA_DATE_P THEN IFNULL(BALANCE,0) ELSE 0 END))/SUM(CASE WHEN DATA_DATE = V_DATA_DATE_P THEN IFNULL(BALANCE,0) ELSE 0 END)*100  END            -- 同比增长
     FROM EDW.GLR_EDS_SPE_DATA_INDUS
    WHERE DATA_DATE in (V_DATA_DATE,V_DATA_DATE_L,V_DATA_DATE_P,V_DATA_DATE_BGY,V_DATA_DATE_E)
     GROUP BY 
               AREA_NO
              ,ORG_NO
              ,ROWS_ID
              ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    END
;;
delimiter ;

