             END AS ORG_CODE
           ,PROJECT                                
           ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE then IFNULL(UNNOR_BAL,0) ELSE 0 END)                                                     AS   UNNOR_BAL
           ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(UNNOR_BAL_SUB_BGY,0) ELSE 0 END)                                             AS   UNNOR_BAL_SUB_BGY
           ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(UNNOR_BAL,0) ELSE 0 END )- SUM(CASE WHEN DATA_DATE = V_DATA_DATE_P THEN IFNULL(UNNOR_BAL,0) ELSE 0 END )       AS   UNNOR_BAL_SUB_P
           ,CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(UNNOR_BAL_TB,0) ELSE 0 END                                                      AS   UNNOR_BAL_TB
           ,CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(UNNOR_BAL_RATE,0) ELSE 0 END                                                    AS   UNNOR_BAL_RATE
