           ,CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(UNNOR_BAL_RATE_TB,0) ELSE 0 END                                                 AS   UNNOR_BAL_RATE_TB
      FROM EDW.GLR_EDS_FINAN_REGUL_STUTAS
      WHERE DATA_DATE IN (V_DATA_DATE,V_DATA_DATE_P)
      GROUP BY 
           AREA_NO
           ,ORG_NO
           ,ROWS_ID
           ,CASE WHEN PROJECT ='工商银行'                       THEN 'ORG01'
                 WHEN PROJECT ='农业银行'                       THEN 'ORG02'
