                 WHEN PROJECT ='重庆三峡银行'                   THEN 'ORG26'
                 WHEN PROJECT ='汉口银行'                       THEN 'ORG27'
                 WHEN PROJECT ='中国邮政储蓄银行'               THEN 'ORG28'
                 WHEN PROJECT ='国家开发银行'                   THEN 'ORG29'
                 WHEN PROJECT ='进出口银行'                     THEN 'ORG30'
                 WHEN PROJECT ='农业发展银行'                   THEN 'ORG31'
                 WHEN PROJECT ='重庆富民银行'                   THEN 'ORG32'
                 WHEN PROJECT ='村镇银行'                       THEN 'ORG33'
                 WHEN PROJECT ='新华信托'                       THEN 'ORG34'
                 WHEN PROJECT ='国际信托'                       THEN 'ORG35'
                 WHEN PROJECT ='化医财务'                       THEN 'ORG36'
                 WHEN PROJECT ='机电财务'                       THEN 'ORG37'
                 WHEN PROJECT ='力帆财务'                       THEN 'ORG38'
                 WHEN PROJECT ='能投财务'                       THEN 'ORG39'
                 WHEN PROJECT ='昆仑租赁'                       THEN 'ORG40'
                 WHEN PROJECT ='渝农商租赁'                     THEN 'ORG41'
                 WHEN PROJECT ='汽车金融公司'                   THEN 'ORG42'
                 WHEN PROJECT ='贷款公司'                       THEN 'ORG43'
             END  
         ,PROJECT ) X
       ON T.ORG_CODE = X.ORG_CODE
       AND T.DATA_DATE = X.DATA_DATE
       WHERE T.DATA_DATE IN (V_DATA_DATE,V_DATA_DATE_P)
       GROUP BY  T.DATA_DATE
                     ,T.ROWS_ID
                     ,T.ORG_NAME
UNION ALL 
     SELECT 
            NOW()
           ,T.AREA_NO
           ,T.DATA_DATE
           ,T.ORG_NO
           ,T.ROWS_ID
           ,T.ORG_NAME
           ,SUM(IFNULL(T.LOAN_BAL,0))
           ,SUM(IFNULL(T.LOAN_BAL_SUB_P,0))
           ,SUM(IFNULL(T.LOAN_BAL_SUB_BGY,0))
           ,IFNULL(T.LOAN_BAL_TB,0)
           ,SUM(IFNULL(X.UNNOR_BAL,0))
           ,SUM(IFNULL(X.UNNOR_BAL_SUB_BGY,0))
           ,SUM(IFNULL(X.UNNOR_BAL_SUB_P,0))
           ,IFNULL(X.UNNOR_BAL_TB,0)
           ,IFNULL(X.UNNOR_BAL_RATE,0)
           ,IFNULL(X.UNNOR_BAL_RATE_SUB_BGY,0)
           ,IFNULL(X.UNNOR_BAL_RATE_TB,0)
  FROM 
    (SELECT 
            NOW()
           ,AREA_NO
           ,V_DATA_DATE                         AS DATA_DATE
           ,ORG_NO
           ,'2'                                 AS  ROWS_ID
           ,'ORG00'                             AS  ORG_CODE
           ,'汇总'                              AS  ORG_NAME
           ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE then IFNULL(LOAN_BAL,0) ELSE 0 END)              AS  LOAN_BAL
           ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE then IFNULL(LOAN_BAL_SUB_P,0) ELSE 0 END)        AS  LOAN_BAL_SUB_P
           ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE then IFNULL(LOAN_BAL_SUB_BGY,0) ELSE 0 END)      AS  LOAN_BAL_SUB_BGY
           ,CASE WHEN SUM(CASE WHEN DATA_DATE = V_DATA_DATE_TB THEN IFNULL(LOAN_BAL,0) END )=0 THEN 0 ELSE 
            (SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(LOAN_BAL,0) END) - SUM(CASE WHEN DATA_DATE = V_DATA_DATE_TB THEN IFNULL(LOAN_BAL,0) END))/SUM(CASE WHEN DATA_DATE = V_DATA_DATE_TB THEN IFNULL(LOAN_BAL,0) END)*100 END           AS  LOAN_BAL_TB
      FROM EDW.GLR_MPA_ALL_ORG_DEPB_CNY_LOAN
      WHERE DATA_DATE IN (V_DATA_DATE,V_DATA_DATE_TB)
      GROUP BY 
           AREA_NO
           ,ORG_NO
           ,'2'                               
           ,'ORG00'                             
           ,'汇总') T
   LEFT JOIN
 -- 全市贷款质量余额的汇总的值取全市银行业合计的值
     (SELECT 
            NOW()
           ,AREA_NO
           ,V_DATA_DATE                                                                 AS DATA_DATE
           ,ORG_NO
           ,ROWS_ID
           ,'ORG00'                                                                      AS ORG_CODE
           ,'汇总'                                                                       AS PROJECT                                
           ,SUM(case when DATA_DATE = V_DATA_DATE then IFNULL(UNNOR_BAL,0) ELSE 0 END)                                                    AS   UNNOR_BAL
           ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE then IFNULL(UNNOR_BAL_SUB_BGY,0) ELSE 0 END)                                            AS   UNNOR_BAL_SUB_BGY
           ,SUM(CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(UNNOR_BAL,0) ELSE 0 END )- SUM(CASE WHEN DATA_DATE = V_DATA_DATE_P THEN IFNULL(UNNOR_BAL,0) ELSE 0 END )                     AS   UNNOR_BAL_SUB_P
           ,CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(UNNOR_BAL_TB,0) ELSE 0 END                                                      AS   UNNOR_BAL_TB
           ,CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(UNNOR_BAL_RATE,0) ELSE 0 END                                                   AS   UNNOR_BAL_RATE
           ,CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(UNNOR_BAL_RATE_SUB_BGY,0) ELSE 0 END                                            AS   UNNOR_BAL_RATE_SUB_BGY
           ,CASE WHEN DATA_DATE = V_DATA_DATE THEN IFNULL(UNNOR_BAL_RATE_TB,0) ELSE 0 END                                                 AS   UNNOR_BAL_RATE_TB
      FROM EDW.GLR_EDS_FINAN_REGUL_STUTAS
      WHERE DATA_DATE IN (V_DATA_DATE,V_DATA_DATE_P)
            AND ROWS_ID = 51
      GROUP BY 
              AREA_NO
              ,ORG_NO
              ,ROWS_ID
              ,'ORG00'                                                                    
              ,'汇总' ) X
       ON T.ORG_CODE = X.ORG_CODE
       AND T.DATA_DATE = X.DATA_DATE
       WHERE T.DATA_DATE IN (V_DATA_DATE,V_DATA_DATE_P,V_DATA_DATE_TB)
       GROUP BY  T.DATA_DATE
                ,T.ROWS_ID
                ,T.ORG_NAME
                ;
    CALL ETL.EDW_PROC_TRACE_LOG(P_DATA_DATE,V_START_TIME,NOW(),V_PROC_NAME,V_STEP,ROW_COUNT());
    END
;;
delimiter ;

