	-- 中文描述转维度编码
	UPDATE adm.`sust_sk_funds_application` a
	LEFT JOIN
	adm.v_sust_biz_category c  -- 业务类别
	ON a.Y1201 = c.`BIZ_DSCR`
	LEFT JOIN
	adm.v_sust_industry d      -- 所属行业
	ON a.Y2803 = d.`LEV_1_DSCR`
	LEFT JOIN
	adm.v_sust_enterprise_size e   -- 规模
	ON a.Y2804 = e.`E_SIZE_DSCR`
	LEFT JOIN
	adm.v_sust_ownership f       -- 所有制
	ON a.Y2807 = f.`OS_DSCR`
	LEFT JOIN
	adm.v_sust_investment_style_a02 g -- 投资方式
	ON a.`Y21_Y22_Y23` = g.`name_3`
	LEFT JOIN
	adm.v_sust_joint_investment h  -- 是否联合投资
	ON a.Y2401 = h.DSCR
	LEFT JOIN
	adm.v_sust_term_category i  -- 期限类别
	ON a.Y2601 = i.`TC_DSCR`
	LEFT JOIN
	adm.v_sust_forward_buyback j -- 是否带远期回购
	ON a.Y2605 = j.FB_DSCR
	LEFT JOIN
	adm.v_sust_fixed_income k  -- 收益是否固定
	ON a.Y2701 = k.INCOME_DSCR
	LEFT JOIN
	adm.v_sust_guaranty_style l -- 担保方式
	ON a.Y3101 = l.`GS_DSCR`
	LEFT JOIN
	adm.v_sust_currency_type m  -- 币种
	ON a.Y2502 = m.TYPE_DSCR
	LEFT JOIN
	adm.v_sust_data_category n  -- 数据类别
	ON a.Y2501 = n.DATA_C_DSCR
	LEFT JOIN
	adm.v_sust_cash_status o  -- 资金状态
	ON a.Y3103 = o.CS_DSCR
	SET 
	a.Y1201 = c.`BIZ_CODE`,
	a.Y2803 = d.`LEV_1_ID`,
	a.Y2804 = e.`E_SIZE_CODE`,
	a.Y2807 = f.`OS_CODE`,
	a.`Y21_Y22_Y23` = g.`code_3`,
	a.Y2401 = h.CODE,
	a.Y2601 = i.TC_CODE,
	a.Y2605 = j.FB_CODE,
	a.Y2701 = k.INCOME_CODE,
	a.Y3101 = l.GS_CODE,
	a.Y2502 = m.TYPE_CODE,
	a.Y2501 = n.DATA_C_CODE,
	a.Y3103 = o.CS_CODE
	    ;
	COMMIT;
END
;;
delimiter ;

