-- ----------------------------
-- Procedure structure for p_trs_kyd_industry_comprehensive
-- ----------------------------
DROP PROCEDURE IF EXISTS `p_trs_kyd_industry_comprehensive`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `p_trs_kyd_industry_comprehensive`(IN V_DATA_DATE VARCHAR(10))
BEGIN
/*凯盈达-分行业--综合查询*/
DELETE FROM ADM.TRS_KYD_INDUSTRY_COMPREHENSIVE WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m');
INSERT INTO ADM.TRS_KYD_INDUSTRY_COMPREHENSIVE
select
	 DATE_FORMAT(V_DATA_DATE,'%Y-%m')
	,S_TRECODE
	,S_TREDSCR
	,AREA_NO
	,AREA_DSCR
	,ETPCODE
	,ETPNAME
	,LEV_4_ID
	,LEV_4_DSCR
	,S_BDGSBTCODE
	,BDGSBTNAME
	,sum(F_AMT)
from edw.trs_kyd_industry ind
where ind.d_acct like concat(date_format(V_DATA_DATE,'%Y-%m'),'%')
  and ind.LEV_4_ID <> 'null'
group by
	 date_format(ind.d_acct,'%Y-%m')
	,S_TRECODE
	,S_TREDSCR
	,AREA_NO
	,AREA_DSCR
	,ETPCODE
	,ETPNAME
	,LEV_4_ID
	,LEV_4_DSCR
	,S_BDGSBTCODE
	,BDGSBTNAME;


	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for p_trs_mth_income_industry
-- ----------------------------
DROP PROCEDURE IF EXISTS `p_trs_mth_income_industry`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `p_trs_mth_income_industry`(in V_DATA_DATE VARCHAR(10))
BEGIN
/*税收收入分行业分税种月报总表*/
DELETE FROM ADM.TRS_MTH_INCOME_INDUSTRY WHERE D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m');
INSERT INTO ADM.TRS_MTH_INCOME_INDUSTRY
SELECT 
	D_ACCT,
	PROJCODE,
	PROJECT,
	S_TRECODE,
	ENTERPRISE_CODE,
	ENTERPRISE_NAME,
	SUM(F_AMT_101),
	SUM(F_AMT_101_YEAR),
	SUM(F_AMT_10101),
	SUM(F_AMT_10101_YEAR),
	SUM(F_AMT_1010101),
	SUM(F_AMT_1010101_YEAR),
	SUM(F_AMT_1010104),
	SUM(F_AMT_1010104_YEAR),
	SUM(F_AMT_10102),
	SUM(F_AMT_10102_YEAR),
	SUM(F_AMT_1010201),
	SUM(F_AMT_1010201_YEAR),
	SUM(F_AMT_10104),
	SUM(F_AMT_10104_YEAR),
	SUM(F_AMT_10106),
	SUM(F_AMT_10106_YEAR),
	SUM(F_AMT_10107),
	SUM(F_AMT_10107_YEAR),
	SUM(F_AMT_10109),
	SUM(F_AMT_10109_YEAR),
	SUM(F_AMT_10110),
	SUM(F_AMT_10110_YEAR),
	SUM(F_AMT_10111),
	SUM(F_AMT_10111_YEAR),
	SUM(F_AMT_10112),
	SUM(F_AMT_10112_YEAR),
	SUM(F_AMT_10113),
	SUM(F_AMT_10113_YEAR),
	SUM(F_AMT_10116),
	SUM(F_AMT_10116_YEAR),
	SUM(F_AMT_10115),
	SUM(F_AMT_10115_YEAR),
	SUM(F_AMT_10114),
	SUM(F_AMT_10114_YEAR),
	SUM(F_AMT_10117),
	SUM(F_AMT_10117_YEAR),
	SUM(F_AMT_10118),
	SUM(F_AMT_10118_YEAR),
	SUM(F_AMT_10119),
	SUM(F_AMT_10119_YEAR),
	SUM(F_AMT_10121),
	SUM(F_AMT_10121_YEAR),
	SUM(F_AMT_10120),
	SUM(F_AMT_10120_YEAR),
	SUM(F_AMT_99999),
	SUM(F_AMT_99999_YEAR),
	S_BELONGFLAG
FROM
(
SELECT
	DATE_FORMAT(DET.S_INTREDATE,'%Y-%m')   		AS D_ACCT,
	IFNULL(INDUS.LEV_1_ID,'ZQT')	  		AS PROJCODE,
	IFNULL(INDUS.LEV_1_DSCR,'其他') AS PROJECT,
	DET.S_TRECODE     		AS S_TRECODE,
	DET.ETPCODE			AS ENTERPRISE_CODE,
