	IFNULL(INDUS.LEV_3_DSCR,'其他') AS PROJECT,
	DET.S_TRECODE     		AS S_TRECODE,
	DET.ETPCODE			AS ENTERPRISE_CODE,
	DET.ETPNAME			AS ENTERPRISE_NAME,
	''				AS F_AMT_101,
	''				AS F_AMT_101_YEAR,
	''				AS F_AMT_10101,
	''				AS F_AMT_10101_YEAR,
	''				AS F_AMT_1010101,
	''				AS F_AMT_1010101_YEAR,
	''				AS F_AMT_1010104,
	''				AS F_AMT_1010104_YEAR,
	''				AS F_AMT_10102,
	''				AS F_AMT_10102_YEAR,
	''				AS F_AMT_1010201,
	''				AS F_AMT_1010201_YEAR,
	''				AS F_AMT_10104,
	''				AS F_AMT_10104_YEAR,
	''				AS F_AMT_10106,
	''				AS F_AMT_10106_YEAR,
	''				AS F_AMT_10107,
	''				AS F_AMT_10107_YEAR,
	''				AS F_AMT_10109,
	''				AS F_AMT_10109_YEAR,
	''				AS F_AMT_10110,
	''				AS F_AMT_10110_YEAR,
	''				AS F_AMT_10111,
	''				AS F_AMT_10111_YEAR,
	''				AS F_AMT_10112,
	''				AS F_AMT_10112_YEAR,
	''				AS F_AMT_10113,
	''				AS F_AMT_10113_YEAR,
	''				AS F_AMT_10116,
	''				AS F_AMT_10116_YEAR,
	''				AS F_AMT_10115,
	''				AS F_AMT_10115_YEAR,
	''				AS F_AMT_10114,
	'' 				AS F_AMT_10114_YEAR,
	''				AS F_AMT_10117,
	''				AS F_AMT_10117_YEAR,
	''				AS F_AMT_10118,
	''				AS F_AMT_10118_YEAR,
	''				AS F_AMT_10119,
	''				AS F_AMT_10119_YEAR,
	SUM(DET.F_AMT)			AS F_AMT_10121,
	SUM(DET2.F_AMT)	        	AS F_AMT_10121_YEAR,
	''				AS F_AMT_10120,
	''				AS F_AMT_10120_YEAR,
	''				AS F_AMT_99999,
	''   				AS F_AMT_99999_YEAR,
	'1' 				AS S_BELONGFLAG
FROM ODS.TV_FIN_INCOME_DETAIL DET
LEFT JOIN ODS.TV_FIN_INCOME_DETAIL DET2
       ON DATE_FORMAT(DET2.S_INTREDATE,'%Y-%m') = DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m')
       AND DET.S_TRECODE = DET2.S_TRECODE
       AND DET.C_BDGLEVEL = DET2.C_BDGLEVEL
       AND DET.S_BDGSBTCODE = DET2.S_BDGSBTCODE
       AND DET.C_BDGKIND = DET2.C_BDGKIND
       AND DET.ETPCODE = DET2.ETPCODE     
LEFT JOIN ODS.TRS_ENTERPRISE_INFOR INFO
       ON DET.TAXPAYCODE = INFO.UNISCID
LEFT JOIN EDW.CM_CLR_INDUSTRY_INFO INDUS
       ON INFO.INDUSTRYCO = INDUS.LEV_4_ID
WHERE DATE_FORMAT(DET.S_INTREDATE,'%Y-%m') = DATE_FORMAT(V_DATA_DATE,'%Y-%m')
  AND DET.S_BDGSBTCODE = '10121'
GROUP BY
      DATE_FORMAT(DET.S_INTREDATE,'%Y-%m'),
      DET.S_TRECODE,
      DET.C_BDGLEVEL,
      DET.S_BDGSBTCODE,
      DET.C_BDGKIND,
      DET.ETPCODE,
      IFNULL(INDUS.LEV_3_ID,'ZQT') 
    UNION ALL
    -- 烟叶税
  SELECT
	DATE_FORMAT(DET.S_INTREDATE,'%Y-%m')   		AS D_ACCT,
	CONCAT(INDUS.LEV_1_ID,IFNULL(INDUS.LEV_3_ID,'ZQT'))     	AS PROJCODE,
	IFNULL(INDUS.LEV_3_DSCR,'其他') AS PROJECT,
	DET.S_TRECODE     		AS S_TRECODE,
	DET.ETPCODE			AS ENTERPRISE_CODE,
	DET.ETPNAME			AS ENTERPRISE_NAME,
	''				AS F_AMT_101,
	''				AS F_AMT_101_YEAR,
	''				AS F_AMT_10101,
	''				AS F_AMT_10101_YEAR,
	''				AS F_AMT_1010101,
	''				AS F_AMT_1010101_YEAR,
	''				AS F_AMT_1010104,
	''				AS F_AMT_1010104_YEAR,
	''				AS F_AMT_10102,
	''				AS F_AMT_10102_YEAR,
	''				AS F_AMT_1010201,
	''				AS F_AMT_1010201_YEAR,
	''				AS F_AMT_10104,
	''				AS F_AMT_10104_YEAR,
	''				AS F_AMT_10106,
	''				AS F_AMT_10106_YEAR,
	''				AS F_AMT_10107,
	''				AS F_AMT_10107_YEAR,
	''				AS F_AMT_10109,
	''				AS F_AMT_10109_YEAR,
	''				AS F_AMT_10110,
	''				AS F_AMT_10110_YEAR,
	''				AS F_AMT_10111,
	''				AS F_AMT_10111_YEAR,
	''				AS F_AMT_10112,
	''				AS F_AMT_10112_YEAR,
	''				AS F_AMT_10113,
	''				AS F_AMT_10113_YEAR,
	''				AS F_AMT_10116,
	''				AS F_AMT_10116_YEAR,
	''				AS F_AMT_10115,
	''				AS F_AMT_10115_YEAR,
	''				AS F_AMT_10114,
	'' 				AS F_AMT_10114_YEAR,
	''				AS F_AMT_10117,
	''				AS F_AMT_10117_YEAR,
	''				AS F_AMT_10118,
	''				AS F_AMT_10118_YEAR,
	''				AS F_AMT_10119,
	''				AS F_AMT_10119_YEAR,
	''				AS F_AMT_10121,
	''				AS F_AMT_10121_YEAR,
	SUM(DET.F_AMT)			AS F_AMT_10120,
	SUM(DET2.F_AMT)	                AS F_AMT_10120_YEAR,
	''				AS F_AMT_99999,
	''  				AS F_AMT_99999_YEAR,
	'1' 				AS S_BELONGFLAG
FROM ODS.TV_FIN_INCOME_DETAIL DET
LEFT JOIN ODS.TV_FIN_INCOME_DETAIL DET2
       ON DATE_FORMAT(DET2.S_INTREDATE,'%Y-%m') = DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m')
       AND DET.S_TRECODE = DET2.S_TRECODE
       AND DET.C_BDGLEVEL = DET2.C_BDGLEVEL
       AND DET.S_BDGSBTCODE = DET2.S_BDGSBTCODE
       AND DET.C_BDGKIND = DET2.C_BDGKIND
       AND DET.ETPCODE = DET2.ETPCODE     
LEFT JOIN ODS.TRS_ENTERPRISE_INFOR INFO
       ON DET.TAXPAYCODE = INFO.UNISCID
LEFT JOIN EDW.CM_CLR_INDUSTRY_INFO INDUS
       ON INFO.INDUSTRYCO = INDUS.LEV_4_ID
WHERE DATE_FORMAT(DET.S_INTREDATE,'%Y-%m') = DATE_FORMAT(V_DATA_DATE,'%Y-%m')
  AND DET.S_BDGSBTCODE = '10120'
GROUP BY
      DATE_FORMAT(DET.S_INTREDATE,'%Y-%m'),
      DET.S_TRECODE,
      DET.C_BDGLEVEL,
      DET.S_BDGSBTCODE,
      DET.C_BDGKIND,
      DET.ETPCODE,
      IFNULL(INDUS.LEV_3_ID,'ZQT') 
 ) SMA
 GROUP BY
	D_ACCT,
	PROJCODE,
	S_TRECODE,
	ENTERPRISE_CODE;
	     
INSERT INTO ADM.TRS_MTH_INCOME_INDUSTRY
SELECT
	DATE_FORMAT(Q.D_ACCT,'%Y-%m'),
	Q.PROCODE,	 	
	Q.PROJECT,		
	B.PID     				AS S_TRECODE,
	Q.ENTERPRISE_CODE			AS ENTERPRISE_CODE,
	Q.ENTERPRISE_NAME			AS ENTERPRISE_NAME,
	SUM(Q.F_AMT_101),
	SUM(Q.F_AMT_101_YEAR)			AS F_AMT_101_YEAR,
	SUM(Q.F_AMT_10101),
	SUM(Q.F_AMT_10101_YEAR)			AS F_AMT_10101_YEAR,
	SUM(Q.F_AMT_1010101),
	SUM(Q.F_AMT_1010101_YEAR)		AS F_AMT_1010101_YEAR,
	SUM(Q.F_AMT_1010104),
	SUM(Q.F_AMT_1010104_YEAR)		AS F_AMT_1010104_YEAR,
	SUM(Q.F_AMT_10102),
	SUM(Q.F_AMT_10102_YEAR)			AS F_AMT_10102_YEAR,
	SUM(Q.F_AMT_1010201),
	SUM(Q.F_AMT_1010201_YEAR)		AS F_AMT_1010201_YEAR,
	SUM(Q.F_AMT_10104),
	SUM(Q.F_AMT_10104_YEAR)			AS F_AMT_10104_YEAR,
	SUM(Q.F_AMT_10106),		
	SUM(Q.F_AMT_10106_YEAR)			AS F_AMT_10106_YEAR,
	SUM(Q.F_AMT_10107),		
	SUM(Q.F_AMT_10107_YEAR)			AS F_AMT_10107_YEAR,
	SUM(Q.F_AMT_10109),		
	SUM(Q.F_AMT_10109_YEAR)			AS F_AMT_10109_YEAR,
	SUM(Q.F_AMT_10110),		
	SUM(Q.F_AMT_10110_YEAR)			AS F_AMT_10110_YEAR,
	SUM(Q.F_AMT_10111),		
	SUM(Q.F_AMT_10111_YEAR)			AS F_AMT_10111_YEAR,
	SUM(Q.F_AMT_10112),		
	SUM(Q.F_AMT_10112_YEAR)			AS F_AMT_10112_YEAR,
	SUM(Q.F_AMT_10113),		
	SUM(Q.F_AMT_10113_YEAR)			AS F_AMT_10113_YEAR,
	SUM(Q.F_AMT_10116),		
	SUM(Q.F_AMT_10116_YEAR)			AS F_AMT_10116_YEAR,
	SUM(Q.F_AMT_10115),		
	SUM(Q.F_AMT_10115_YEAR)			AS F_AMT_10115_YEAR,
	SUM(Q.F_AMT_10114),		
	SUM(Q.F_AMT_10114_YEAR)			AS F_AMT_10114_YEAR,
	SUM(Q.F_AMT_10117),		
	SUM(Q.F_AMT_10117_YEAR)			AS F_AMT_10117_YEAR,
	SUM(Q.F_AMT_10118),		
	SUM(Q.F_AMT_10118_YEAR)			AS F_AMT_10118_YEAR,
	SUM(Q.F_AMT_10119),		
	SUM(Q.F_AMT_10119_YEAR)			AS F_AMT_10119_YEAR,
	SUM(Q.F_AMT_10121),		
	SUM(Q.F_AMT_10121_YEAR)			AS F_AMT_10121_YEAR,
	SUM(Q.F_AMT_10120),
	SUM(Q.F_AMT_10120_YEAR)			AS F_AMT_10120_YEAR,
	''					AS F_AMT_99999,
	''					AS F_AMT_99999_YEAR,
	'0' 					AS S_BELONGFLAG
from ADM.trs_mth_income_industry Q
LEFT JOIN 
(
SELECT 
	DISTINCT 
	p.GUOKU_ID AS PID,
	p.LEVEL,
	p.GUOKU_DSCR,
	c.GUOKU_ID AS CID
FROM edw.cm_guoku_dimnsn p
LEFT JOIN edw.cm_guoku_dimnsn c
ON p.GUOKU_LVL_ID_2 = c.GUOKU_LVL_ID_1 
OR  p.GUOKU_LVL_ID_3 = c.GUOKU_LVL_ID_2 
OR  p.GUOKU_ID = c.GUOKU_LVL_ID_3
) B 
     ON Q.S_TRECODE = B.CID
WHERE DATE_FORMAT(Q.D_ACCT,'%Y-%m') = DATE_FORMAT(V_DATA_DATE,'%Y-%m')
  AND Q.S_BELONGFLAG = '1'
GROUP BY
      DATE_FORMAT(Q.D_ACCT,'%Y-%m'),
      Q.PROCODE,
      B.PID,
      Q.ENTERPRISE_CODE;
      
  
  -- 更新表中其他各税
UPDATE ADM.TRS_MTH_INCOME_INDUSTRY A,
(
SELECT 
*
FROM ADM.TRS_MTH_INCOME_INDUSTRY 
WHERE D_ACCT = DATE_FORMAT(DATE_SUB(V_DATA_DATE,INTERVAL 1 YEAR),'%Y-%m')
) B
SET A.F_AMT_99999 = (A.F_AMT_101-A.F_AMT_10101-A.F_AMT_10102-A.F_AMT_10104-A.F_AMT_10106-A.F_AMT_10107-
	       A.F_AMT_10109-A.F_AMT_10110-A.F_AMT_10111-A.F_AMT_10112-A.F_AMT_10113-A.F_AMT_10116-
	       A.F_AMT_10115-A.F_AMT_10114-A.F_AMT_10117-A.F_AMT_10118-A.F_AMT_10119-A.F_AMT_10121-A.F_AMT_10120),
    A.F_AMT_99999_YEAR = (B.F_AMT_101-B.F_AMT_10101-B.F_AMT_10102-B.F_AMT_10104-B.F_AMT_10106-B.F_AMT_10107-
	       B.F_AMT_10109-B.F_AMT_10110-B.F_AMT_10111-B.F_AMT_10112-B.F_AMT_10113-B.F_AMT_10116-
	       B.F_AMT_10115-B.F_AMT_10114-B.F_AMT_10117-B.F_AMT_10118-B.F_AMT_10119-B.F_AMT_10121-B.F_AMT_10120)
WHERE A.D_ACCT = DATE_FORMAT(V_DATA_DATE,'%Y-%m')
  AND A.PROCODE  = B.PROCODE
  AND A.S_TRECODE  = B.S_TRECODE
  AND A.ENTERPRISE_CODE  = B.ENTERPRISE_CODE;
	END
;;
delimiter ;

