,S_VOUCHERNO           -- 支付凭证编号
,S_ORIVOUCHERNO        -- 原支付凭证编号
,S_ORIPAYVOUDATE       -- 原支付凭证日期
,S_FUNDTYPECODE        -- 预算种类:1-预算内，2-预算外
,S_BDGORGCODE          -- 预算单位编码
,S_BDGORGNAME          -- 预算单位名称
