-- ----------------------------
-- Procedure structure for test_loop
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
  
--     SET s_date = DATE_FORMAT(s_date,'%Y%m%d');
  
  SELECT s_date;
  
  
--   CALL adm.p_trs_kyd_enterprise_rank (s_date);
call adm.p_trs_kyd_enterprise(s_date);
CALL adm.p_trs_kyd_industry(s_date);
CALL adm.p_trs_kyd_industry_comprehensive(s_date);
  
-- call indicators_lib.p_exe_formula_hand(s_date,'269f91eea5ab11eba5bf0050569e3b4e');  
-- CALL indicators_lib.p_exe_formula_hand(s_date,'8d6f6284b54311ea8bc1000c29587404');  
  
-- call adm.P_EXECUTE_DATE_PROCESSING(s_date);
 
--  CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 month);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop1
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop1`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop1`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE V_SQL_INSERT    LONGTEXT        DEFAULT ''; -- 插数语句SQL
  DECLARE V_SQLTXT        LONGTEXT        DEFAULT ''; -- 执行SQL
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
  
  SELECT s_date;
## 功能分类预算收入-日
## DROP TABLE ADM.trs_budget_function_income_daily
## CREATE TABLE adm.trs_budget_function_income_daily AS
delete from adm.trs_budget_function_income_daily where D_REPORTDATE = s_date;
insert into adm.trs_budget_function_income_daily
SELECT
 DATE_FORMAT(aa.D_REPORTDATE,'%Y-%m-%d') AS D_REPORTDATE,
 aa.S_TRECODE AS S_TRECODE,
 aa.C_BUDGETLEVEL AS C_BUDGETLEVEL,
 dt1.SUBJECT_CODE_4 AS SUBJECT_CODE_4,
 dt1.SUBJECT_DSCR_4 AS SUBJECT_DSCR_4,
 dt1.FUN_CLASS_CODE_1 AS FUN_CLASS_CODE_1,
 dt1.FUN_CLASS_DSCR_1 AS FUN_CLASS_DSCR_1,
 dt1.FUN_CLASS_CODE_2 AS FUN_CLASS_CODE_2,
 dt1.FUN_CLASS_DSCR_2 AS FUN_CLASS_DSCR_2,
 dt1.FUN_CLASS_CODE_3 AS FUN_CLASS_CODE_3,
 dt1.FUN_CLASS_DSCR_3 AS FUN_CLASS_DSCR_3,
 aa.F_DAYAMT AS THIS_PERIOD_AMT,
 bb.F_DAYAMT AS LAST_PERIOD_AMT,
 aa.F_YEARAMT AS THIS_PERIOD_YEARAMT,
 bb.F_YEARAMT AS LAST_PERIOD_YEARAMT,
 CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
  ## -- 本期预算收入
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = s_date
-- 	AND S_TAXORGCODE NOT IN('000000000000','111111111111','222222222222','333333333333','444444444444','555555555555') 
	AND S_TAXORGCODE = 'XXXXXXXXXXXX'
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
	UNION ALL
   ## -- 本期调拨收入（转移性收入）
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = s_date
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
) aa
LEFT JOIN
## --去年同期
(
  ## -- 预算收入
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
	AND S_TAXORGCODE NOT IN('000000000000','111111111111','222222222222','333333333333','444444444444','555555555555') 
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
	UNION ALL
   ## -- 调拨收入（转移性收入）
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
) bb
ON  aa.D_REPORTDATE = DATE_ADD(bb.D_REPORTDATE,INTERVAL 1 YEAR)
AND aa.S_TRECODE = bb.S_TRECODE
AND aa.C_BUDGETLEVEL = bb.C_BUDGETLEVEL
AND aa.S_BUDGETSUBJECTCODE = bb.S_BUDGETSUBJECTCODE
JOIN
(
SELECT
a.`FUN_CLASS_CODE_1` AS FUN_CLASS_CODE_1,
a.`FUN_CLASS_DSCR_1` AS FUN_CLASS_DSCR_1,
a.`FUN_CLASS_CODE_2` AS FUN_CLASS_CODE_2,
a.`FUN_CLASS_DSCR_2` AS FUN_CLASS_DSCR_2,
a.`FUN_CLASS_CODE_3` AS FUN_CLASS_CODE_3,
a.`FUN_CLASS_DSCR_3` AS FUN_CLASS_DSCR_3,
b.`SUBJECT_CODE_4` AS SUBJECT_CODE_4,
b.`SUBJECT_DSCR_4` AS SUBJECT_DSCR_4
FROM
edw.`cm_guoku_functional_type` a
LEFT JOIN
edw.`cm_guoku_rcpt_dsb` b
ON  a.`FUN_CLASS_CODE_3` = b.`T_CLASS_CODE_3`
WHERE
-- b.`OF_YEAR` = YEAR(s_date)
 a.FUN_CLASS_CODE_1 = 'T01'
) dt1
ON aa.S_BUDGETSUBJECTCODE = dt1.SUBJECT_CODE_4
  
  
 
  
  
 ;
  
 
 CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop2
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop2`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop2`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop2.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE V_SQL_INSERT    LONGTEXT        DEFAULT ''; -- 插数语句SQL
  DECLARE V_SQLTXT        LONGTEXT        DEFAULT ''; -- 执行SQL
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
	  SET V_STEP_ID =1;
	  delete from  ADM.TRS_SK_SUBJECT_INCOME where  REPORTDATE=s_date;  
	  SET V_STEP_ID =2;
	  INSERT INTO ADM.TRS_SK_SUBJECT_INCOME
	SELECT
	 A.D_EXPFILE                         AS REPORTDATE        -- 时间（日）
	,DATE_FORMAT(A.D_EXPFILE,'%Y-%m')    AS D_MONTH           -- 时间（月）
	,DATE_FORMAT(A.D_EXPFILE,'%Y')       AS D_YEAR            -- 时间（年）
	 --  ,B.GUOKU_LVL_ID_1                    AS GUOKU_LVL_ID_1    -- 所属省国库代码
	 --  ,B.GUOKU_LVL_DSCR_1                  AS GUOKU_LVL_DSCR_1  -- 所属省国库名称
	 --  ,B.GUOKU_LVL_ID_2                    AS GUOKU_LVL_ID_2    -- 所属市国库代码
	 --  ,B.GUOKU_LVL_DSCR_2                  AS GUOKU_LVL_DSCR_2  -- 所属市国库名称
	,A.S_TRECODE                         AS GUOKU_ID    -- 所属县国库代码
	 --  ,B.GUOKU_DSCR                        AS GUOKU_LVL_DSCR_3  -- 所属县国库名称
	 --  ,C.SUBJECT_CODE_1                    AS SUBJECT_CODE_1    -- 科目类级代码
	 --  ,C.SUBJECT_DSCR_1                    AS SUBJECT_DSCR_1    -- 科目类级名称
	 --  ,C.SUBJECT_CODE_2                    AS SUBJECT_CODE_2    -- 科目款级代码
	 --  ,C.SUBJECT_DSCR_2                    AS SUBJECT_DSCR_2    -- 科目款级名称
	 --  ,C.SUBJECT_CODE_3                    AS SUBJECT_CODE_3    -- 科目项级代码
	 --  ,C.SUBJECT_DSCR_3                    AS SUBJECT_DSCR_3    -- 科目项级名称
	,A.S_BDGSBTCODE                      AS SUBJECT_CODE_4    -- 科目目级代码
	 -- ,C.SUBJECT_DSCR_4                    AS SUBJECT_DSCR_4    -- 科目目级名称
	,A.S_BDGLEVEL                        AS BUDGETLEVEL_CODE  -- 预算级次代码
	,D.BUDGET_DSCR                       AS BUDGETLEVEL_DSCR  -- 预算级次描述
	,A.F_DAYAMT                          AS F_DAYAMT          -- 日金额
	FROM EDW.TRS_D005_TR_BDGINCM A
	 --  LEFT JOIN EDW.CM_GUOKU_DIMNSN B 
	 --  ON A.S_TRECODE=B.GUOKU_ID
	 --  LEFT JOIN EDW.CM_GUOKU_RCPT_DSB C
	 --  ON A.S_BDGSBTCODE=C.SUBJECT_CODE_4
	LEFT JOIN EDW.CM_GUOKU_BUDGET_LEVEL D
	ON A.S_BDGLEVEL=D.BUDGET_CODE
	WHERE A.D_EXPFILE = s_date
	UNION ALL
	SELECT
	 B.D_EXPFILE                         AS REPORTDATE        -- 时间（日）
	,DATE_FORMAT(B.D_EXPFILE,'%Y-%m')    AS D_MONTH           -- 时间（月）
	,DATE_FORMAT(B.D_EXPFILE,'%Y')       AS D_YEAR            -- 时间（年）
	 --  ,C.GUOKU_LVL_ID_1                    AS GUOKU_LVL_ID_1    -- 所属省国库代码
	 --  ,C.GUOKU_LVL_DSCR_1                  AS GUOKU_LVL_DSCR_1  -- 所属省国库名称
	 --  ,C.GUOKU_LVL_ID_2                    AS GUOKU_LVL_ID_2    -- 所属市国库代码
	 --  ,c.GUOKU_LVL_DSCR_2                  AS GUOKU_LVL_DSCR_2  -- 所属市国库名称
	,B.S_TRECODE                         AS GUOKU_ID    -- 所属县国库代码
	 --  ,C.GUOKU_DSCR                        AS GUOKU_LVL_DSCR_3  -- 所属县国库名称
	 --  ,D.SUBJECT_CODE_1                    AS SUBJECT_CODE_1    -- 科目类级代码
	 --  ,D.SUBJECT_DSCR_1                    AS SUBJECT_DSCR_1    -- 科目类级名称
	 --  ,D.SUBJECT_CODE_2                    AS SUBJECT_CODE_2    -- 科目款级代码
	 --  ,D.SUBJECT_DSCR_2                    AS SUBJECT_DSCR_2    -- 科目款级名称
	 --  ,D.SUBJECT_CODE_3                    AS SUBJECT_CODE_3    -- 科目项级代码
	 --  ,D.SUBJECT_DSCR_3                    AS SUBJECT_DSCR_3    -- 科目项级名称
	,B.S_BDGSBTCODE                      AS SUBJECT_CODE_4    -- 科目目级代码
	 --  ,D.SUBJECT_DSCR_4                    AS SUBJECT_DSCR_4    -- 科目目级名称
	,B.S_BDGLEVEL                        AS BUDGETLEVEL_CODE  -- 预算级次代码
	,E.BUDGET_DSCR                       AS BUDGETLEVEL_DSCR  -- 预算级次描述
	,B.F_DAYAMT                          AS F_DAYAMT          -- 日金额
	FROM EDW.TRS_D005_TR_MOVEFUNDINCM B
	 -- LEFT JOIN EDW.CM_GUOKU_DIMNSN C
	 -- ON B.S_TRECODE=C.GUOKU_ID
	 -- LEFT JOIN EDW.CM_GUOKU_RCPT_DSB D
	 -- ON B.S_BDGSBTCODE=D.SUBJECT_CODE_4
	LEFT JOIN EDW.CM_GUOKU_BUDGET_LEVEL E
	ON B.S_BDGLEVEL=E.BUDGET_CODE
	WHERE B.D_EXPFILE = s_date;
 
 CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop3
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop3`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop3`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop3.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE V_SQL_INSERT    LONGTEXT        DEFAULT ''; -- 插数语句SQL
  DECLARE V_SQLTXT        LONGTEXT        DEFAULT ''; -- 执行SQL
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
	  SET V_STEP_ID =1;
	  delete from  ADM.TRS_SK_SUBJECT_PAYOUT where  REPORTDATE=s_date;
  
	  SET V_STEP_ID =2;
	  -- (多维)支出分科目统计表
	-- 2018年3月30日之后取(含30日)
	INSERT INTO ADM.TRS_SK_SUBJECT_PAYOUT
	SELECT
	 B.D_EXPFILE                         AS REPORTDATE        -- 时间（日）
	,DATE_FORMAT(B.D_EXPFILE,'%Y-%m')    AS D_MONTH           -- 时间（月）
	,DATE_FORMAT(B.D_EXPFILE,'%Y')       AS D_YEAR            -- 时间（年）
	 --  ,C.GUOKU_LVL_ID_1                    AS GUOKU_LVL_ID_1    -- 所属省国库代码
	 --  ,C.GUOKU_LVL_DSCR_1                  AS GUOKU_LVL_DSCR_1  -- 所属省国库名称
	 --  ,C.GUOKU_LVL_ID_2                    AS GUOKU_LVL_ID_2    -- 所属市国库代码
	 --  ,c.GUOKU_LVL_DSCR_2                  AS GUOKU_LVL_DSCR_2  -- 所属市国库名称
	,B.S_TRECODE                         AS GUOKU_ID    -- 所属县国库代码
	 --  ,C.GUOKU_DSCR                        AS GUOKU_LVL_DSCR_3  -- 所属县国库名称
	 --  ,D.SUBJECT_CODE_1                    AS SUBJECT_CODE_1    -- 科目类级代码
	 --  ,D.SUBJECT_DSCR_1                    AS SUBJECT_DSCR_1    -- 科目类级名称
	 --  ,D.SUBJECT_CODE_2                    AS SUBJECT_CODE_2    -- 科目款级代码
	 --  ,D.SUBJECT_DSCR_2                    AS SUBJECT_DSCR_2    -- 科目款级名称
	 --  ,D.SUBJECT_CODE_3                    AS SUBJECT_CODE_3    -- 科目项级代码
	 --  ,D.SUBJECT_DSCR_3                    AS SUBJECT_DSCR_3    -- 科目项级名称
	,B.S_FUNCSBTCODE                     AS SUBJECT_CODE_4    -- 科目目级代码
	 --  ,D.SUBJECT_DSCR_4                    AS SUBJECT_DSCR_4    -- 科目目级名称
	,B.F_DAYAMT                          AS F_DAYAMT          -- 日金额
	FROM EDW.TRS_D005_TR_BDGPAYOUT B
	 --  LEFT JOIN EDW.CM_GUOKU_DIMNSN C
	 --  ON B.S_TRECODE=C.GUOKU_ID
	 --  LEFT JOIN EDW.CM_GUOKU_RCPT_DSB D
	 --  ON B.S_FUNCSBTCODE=D.SUBJECT_CODE_4
	WHERE B.D_EXPFILE =   s_date;
 
 CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop4
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop4`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop4`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop4.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE V_SQL_INSERT    LONGTEXT        DEFAULT ''; -- 插数语句SQL
  DECLARE V_SQLTXT        LONGTEXT        DEFAULT ''; -- 执行SQL
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
	 
## 限额税收统计表-日
## DROP TABLE ADM.TRS_BUDGET_LIMIT_INCOME_DAILY
## CREATE TABLE adm.trs_budget_limit_income_daily AS
select s_date;
delete from adm.trs_budget_limit_income_daily where D_ACCEPT = s_date;
insert into adm.trs_budget_limit_income_daily
SELECT
  c.lev_1_dscr AS INDUSTRY,
  aa.`D_ACCEPT` AS D_ACCEPT,
  aa.`S_TAXPAYCODE` AS S_TAXPAYCODE,
  aa.`S_TAXPAYNAME` AS S_TAXPAYNAME,
  aa.`S_ETPNAME` AS S_ETPNAME,
  aa.`S_AIMTRECODE` AS S_AIMTRECODE,
  dt3.`GUOKU_DSCR` AS GUOKU_DSCR,
  aa.`S_BDGSBTCODE` AS S_BDGSBTCODE,
  dt2.`SUBJECT_DSCR_4` AS S_BDGSBTNAME,
  aa.F_AMT AS THIS_PERIOD_AMT,
  aa.TAXDATE AS TAXDATE,
  CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
## --电子税票
SELECT
  a.`D_ACCEPT` AS D_ACCEPT,
  a.`S_PAYERORGCODE` AS S_PAYERORGCODE,
  a.`S_PAYERACCT` AS S_PAYERACCT,
  a.`S_PAYEROPNBNKNO` AS S_PAYEROPNBNKNO,
  a.`S_TAXPAYCODE` AS S_TAXPAYCODE,
  a.`S_TAXPAYNAME` AS S_TAXPAYNAME,
  a.`S_ETPCODE` AS S_ETPCODE,
  a.`S_ETPNAME` AS S_ETPNAME,
  a.`S_ETPTYPE` AS S_ETPTYPE,
  a.`S_AIMTRECODE` AS S_AIMTRECODE,
  a.`S_BDGSBTCODE` AS S_BDGSBTCODE,
  CONCAT(a.D_TAXSTARTDATE,'-',a.D_TAXENDDATE) AS TAXDATE,
  a.`F_AMT` AS F_AMT 
FROM
  edw.`trs_d004_htv_import_incomeonline_detail` a
WHERE
    a.`D_ACCEPT` = s_date
      AND a.C_BDGKIND='1'
-- AND a.`S_BDGSBTCODE` LIKE '101%'
  
  UNION ALL   
  ## --纸质税票
SELECT
  a.`D_ACCEPT` AS D_ACCEPT,
  a.`S_PAYERORGCODE` AS S_PAYERORGCODE,
  '999999999999' AS S_PAYERACCT,
  NULL AS S_PAYEROPNBNKNO,
  '999999999999' AS S_TAXPAYCODE,
  '纸质税票' AS S_TAXPAYNAME,
  NULL AS S_ETPCODE,
  NULL AS S_ETPNAME,
  a.`S_ETPTYPE` AS S_ETPTYPE,
  a.`S_AIMTRECODE` AS S_AIMTRECODE,
  a.`S_BDGSBTCODE` AS S_BDGSBTCODE,
  a.I_OFMONTH AS TAXDATE,
  a.`F_AMT` AS F_AMT 
FROM
  edw.`trs_d004_htv_handbook_detail` a
WHERE
 a.`D_ACCEPT` = s_date
  AND a.C_BDGKIND='1'
-- AND a.`S_BDGSBTCODE` LIKE '101%'
) aa
LEFT JOIN 
edw.`cm_guoku_entpown_information_list` dt1
ON aa.S_TAXPAYCODE = dt1.`S_TAXPAYCODE`
LEFT JOIN edw.cm_guoku_industry c ON dt1.LEV_4_ID=c.LEV_4_ID  
LEFT JOIN 
edw.`cm_guoku_rcpt_dsb` dt2
ON aa.S_BDGSBTCODE = dt2.`SUBJECT_CODE_4`
LEFT JOIN
edw.`cm_guoku_dimnsn` dt3
ON aa.`S_AIMTRECODE` = dt3.`GUOKU_ID`
;	 
	 
	 
	 
	 
	 
 
 CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop5
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop5`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop5`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop5.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE V_SQL_INSERT    LONGTEXT        DEFAULT ''; -- 插数语句SQL
  DECLARE V_SQLTXT        LONGTEXT        DEFAULT ''; -- 执行SQL
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
	  SET V_STEP_ID =1;
	  delete from  ADM.TRS_SK_ACCT_STOCK where  REPORTDATE=s_date;
  
	  SET V_STEP_ID =2;
		-- (多维)库存分账户统计表
	-- 2018年3月30日之后取(含30日)
	INSERT INTO ADM.TRS_SK_ACCT_STOCK
	SELECT
	 B.D_ACCT                          AS REPORTDATE        -- 时间（日）
	,DATE_FORMAT(B.D_ACCT,'%Y-%m')     AS D_MONTH           -- 时间（月）
	,DATE_FORMAT(B.D_ACCT,'%Y')        AS D_YEAR            -- 时间（年）
	 --  ,C.GUOKU_LVL_ID_1                  AS GUOKU_LVL_ID_1      -- 所属省国库代码
	 --  ,C.GUOKU_LVL_DSCR_1                AS GUOKU_LVL_DSCR_1    -- 所属省国库名称
	 --  ,C.GUOKU_LVL_ID_2                  AS GUOKU_LVL_ID_2      -- 所属市国库代码
	 --  ,C.GUOKU_LVL_DSCR_2                AS GUOKU_LVL_DSCR_2    -- 所属市国库名称
	,B.S_TRECODE                       AS GUOKU_ID      -- 所属县国库代码
	 --  ,C.GUOKU_DSCR                      AS GUOKU_LVL_DSCR_3    -- 所属县国库名称
	,B.S_ACCT           AS ACCOUNT_CODE        -- 账户编码
	,B.S_ACCTNAME       AS ACCOUNT_NAME        -- 账户名称
	,B.F_PREDATEBALANCE AS F_YESTERDAYBALANCE  -- 上期余额
	,B.F_DAYINCOME      AS F_TODAYRECEIPT      -- 当期收入额
	,B.F_DAYPAYOUT      AS F_TODAYPAY          -- 当期支出额
	,B.F_DAYBALANCE     AS F_TODAYBALANCE      -- 当期余额
	FROM EDW.TRS_D005_TR_STOCKDAY B
	 --  LEFT JOIN EDW.CM_GUOKU_DIMNSN C
	 --  ON B.S_TRECODE=C.GUOKU_ID
	   WHERE B.D_ACCT =  s_date;
 
 CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop6
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop6`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop6`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop6.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
	  SET V_STEP_ID =1;
    DELETE FROM ADM.ANA_TRS_INCOME_SUBJECT_STRUCT WHERE D_DATE = s_date;
	  SET V_STEP_ID =2;
-- 2018年3月30日之后（含30日）
INSERT INTO ADM.ANA_TRS_INCOME_SUBJECT_STRUCT
-- 全辖
SELECT
DATE_FORMAT(s_date,'%Y-%m-%d') AS D_DATE -- 工具需要日期（该月第一天）
,DATE_FORMAT(s_date,'%Y-%m') AS D_YEAR_MTH   -- 数据日期（年-月）
,B.FULL_JUE_GUOKU_ID AS GUOKU_ID  -- 国库编码
,B.FULL_JUE_GUOKU_DSCR            -- 国库名称
,'1' AS FLAG_CODE          -- 辖属标志编码（1：全辖，2：本级）
,'全辖' AS FLAG            -- 辖属标志（1：全辖，2：本级）
,A.SUB_LVL_CODE            -- 收入科目结构编码（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,A.SUB_LVL_DSCR            -- 收入科目结构名称（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,SUM(A.BUDGET_INCOME) AS BUDGET_INCOME -- 预算收入总金额（元）
FROM (
SELECT
M.S_TRECODE -- 国库编码
,M.SUB_LVL_CODE -- 收入科目结构编码（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,M.SUB_LVL_DSCR -- 收入科目结构名称（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,SUM(M.BUDGET_INCOME) AS BUDGET_INCOME -- 预算收入金额（元）
FROM (
-- 本月-预算收入金额(正常期预算收入)
SELECT
M.S_TRECODE -- 国库编码
,CASE WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='101' THEN '01'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='102' THEN '02'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='103' THEN '03'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3) NOT IN ('101','102','103') THEN '04'
END AS SUB_LVL_CODE -- 收入科目结构编码
,CASE WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='101' THEN '税收收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='102' THEN '政府性基金预算收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='103' THEN '社保收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3) NOT IN ('101','102','103') THEN '其他收入'
END AS SUB_LVL_DSCR -- 收入科目结构名称
,M.F_MONTHAMT AS BUDGET_INCOME   -- 预算收入金额（元）
FROM EDW.TRS_D005_TR_BDGINCM M  -- 正常期预算收入报表
WHERE D_EXPFILE=s_date
UNION ALL
-- 本月-预算收入金额(正常期调拨收入)
SELECT
M.S_TRECODE -- 国库编码
,CASE WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='101' THEN '01'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='102' THEN '02'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='103' THEN '03'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3) NOT IN ('101','102','103') THEN '04'
END AS SUB_LVL_CODE -- 收入科目结构编码
,CASE WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='101' THEN '税收收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='102' THEN '政府性基金预算收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='103' THEN '社保收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3) NOT IN ('101','102','103') THEN '其他收入'
END AS SUB_LVL_DSCR -- 收入科目结构名称
,M.F_MONTHAMT AS BUDGET_INCOME   -- 预算收入金额（元）
FROM EDW.TRS_D005_TR_MOVEFUNDINCM M  -- 正常期调拨收入报表
WHERE D_EXPFILE=s_date
) M
GROUP BY M.S_TRECODE,M.SUB_LVL_CODE
) A
LEFT JOIN EDW.CM_GUOKU_ANA_WHOLE_BANK B
ON A.S_TRECODE=B.SUB_GUOKU_ID
GROUP BY 
DATE_FORMAT(s_date,'%Y-%m-01')
,DATE_FORMAT(s_date,'%Y-%m')
,s_date 
,B.FULL_JUE_GUOKU_ID 
,B.FULL_JUE_GUOKU_DSCR           
,A.SUB_LVL_CODE           
,A.SUB_LVL_DSCR 
UNION ALL
-- 本级
SELECT
DATE_FORMAT(s_date,'%Y-%m-01') AS D_DATE -- 工具需要日期（该月第一天）
,DATE_FORMAT(s_date,'%Y-%m') AS D_YEAR_MTH   -- 数据日期（年-月）
,A.S_TRECODE AS GUOKU_ID   -- 国库编码
,B.GUOKU_DSCR              -- 国库名称
,'2' AS FLAG_CODE          -- 辖属标志编码（1：全辖，2：本级）
,'本级' AS FLAG            -- 辖属标志（1：全辖，2：本级）
,A.SUB_LVL_CODE            -- 收入科目结构编码（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,A.SUB_LVL_DSCR            -- 收入科目结构名称（01：税收收入，02：非税收入，03：社保收入，04：其他收入）
,SUM(A.BUDGET_INCOME) AS BUDGET_INCOME -- 预算收入总金额（元）
FROM (
-- 本月-预算收入金额(正常期预算收入)
SELECT
M.S_TRECODE -- 国库编码
,CASE WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='101' THEN '01'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='102' THEN '02'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='103' THEN '03'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3) NOT IN ('101','102','103') THEN '04'
END AS SUB_LVL_CODE -- 收入科目结构编码
,CASE WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='101' THEN '税收收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='102' THEN '政府性基金预算收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='103' THEN '社保收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3) NOT IN ('101','102','103') THEN '其他收入'
END AS SUB_LVL_DSCR -- 收入科目结构名称
,M.F_MONTHAMT AS BUDGET_INCOME   -- 预算收入金额（元）
FROM EDW.TRS_D005_TR_BDGINCM M  -- 正常期预算收入报表
WHERE D_EXPFILE=s_date
UNION ALL
-- 本月-预算收入金额(正常期调拨收入)
SELECT
M.S_TRECODE -- 国库编码
,CASE WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='101' THEN '01'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='102' THEN '02'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='103' THEN '03'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3) NOT IN ('101','102','103') THEN '04'
END AS SUB_LVL_CODE -- 收入科目结构编码
,CASE WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='101' THEN '税收收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='102' THEN '政府性基金预算收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3)='103' THEN '社保收入'
      WHEN SUBSTR(M.S_BDGSBTCODE,1,3) NOT IN ('101','102','103') THEN '其他收入'
END AS SUB_LVL_DSCR -- 收入科目结构名称
,M.F_MONTHAMT AS BUDGET_INCOME   -- 预算收入金额（元）
FROM EDW.TRS_D005_TR_MOVEFUNDINCM M  -- 正常期调拨收入报表
WHERE D_EXPFILE=s_date
) A
LEFT JOIN EDW.CM_GUOKU_DIMNSN B
ON A.S_TRECODE=B.GUOKU_ID
GROUP BY A.S_TRECODE,A.SUB_LVL_CODE;
 
 CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop7
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop7`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop7`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  s_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop7.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  -- SET s_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
	  SET V_STEP_ID =1;
    DELETE FROM ADM.TRS_STOCK_CHANGE_MONTHLY WHERE D_REPORTDATE = DATE_FORMAT(s_date,'%Y-%m');
	  SET V_STEP_ID =2;
-- 2018年3月30日之后（含30日）
INSERT INTO ADM.TRS_STOCK_CHANGE_MONTHLY
-- 全辖
SELECT 
  DATE_FORMAT(aa.D_REPORTDATE,'%Y-%m') AS D_REPORTDATE,
  aa.S_TRECODE AS S_TRECODE,
  dt1.GUOKU_DSCR AS GUOKU_DSCR,
  aa.S_ACCTCODE AS S_ACCTCODE,
  aa.S_ACCTNAME AS S_ACCTNAME,
  aa.D_ACCTDATE AS D_ACCTDATE,
  aa.SUB_ACCTCODE AS SUB_ACCTCODE,
  dt1.LEVEL AS LEVEL,
  aa.F_TODAYBALANCE AS THIS_PERIOD_AMT,
  bb.F_TODAYBALANCE AS LAST_PERIOD_AMT,
  CURRENT_TIMESTAMP AS UPDATE_DATE 
FROM
  (SELECT 
    a.D_REPORTDATE AS D_REPORTDATE,
    a.S_TRECODE AS S_TRECODE,
    a.S_ACCTCODE AS S_ACCTCODE,
    a.S_ACCTNAME AS S_ACCTNAME,
    a.D_ACCTDATE AS D_ACCTDATE,
    b.ACOUNT_SUBJECT AS SUB_ACCTCODE,
    a.F_TODAYBALANCE AS F_TODAYBALANCE 
  FROM
    edw.`trs_d003_tr_stock` a 
   JOIN 
      (SELECT 
        MAX(tb.D_REPORTDATE) AS D_REPORTDATE,      
        tb.S_TRECODE,
        tb.S_ACCTCODE,
        MAX(tb.D_ACCTDATE) AS D_ACCTDATE
      FROM
        edw.trs_d003_tr_stock tb
      WHERE tb.D_REPORTDATE BETWEEN DATE_FORMAT(s_date,'%Y-%m-01') AND s_date
      GROUP BY tb.S_TRECODE,
        tb.S_ACCTCODE
        )c
         ON a.D_REPORTDATE = c.D_REPORTDATE
        AND a.S_TRECODE = c.S_TRECODE
        AND a.S_ACCTCODE = c.S_ACCTCODE
        AND a.D_ACCTDATE = c.D_ACCTDATE
    LEFT JOIN 
      (SELECT DISTINCT 
        t.GUOKU_ID AS GUOKU_ID,
        t.ACOUNT_CODE AS ACOUNT_CODE,
        t.ACOUNT_SUBJECT AS ACOUNT_SUBJECT 
      FROM
        edw.cm_guoku_trecode_account t) b 
      ON a.S_ACCTCODE = b.ACOUNT_CODE 
      AND a.S_TRECODE = b.GUOKU_ID
  ) aa 
  LEFT JOIN 
    (SELECT 
      a.D_REPORTDATE AS D_REPORTDATE,
      a.S_TRECODE AS S_TRECODE,
      a.S_ACCTCODE AS S_ACCTCODE,
      a.S_ACCTNAME AS S_ACCTNAME,
      a.D_ACCTDATE AS D_ACCTDATE,
      b.ACOUNT_SUBJECT AS SUB_ACCTCODE,
      a.F_TODAYBALANCE AS F_TODAYBALANCE 
    FROM
      edw.`trs_d003_tr_stock` a 
      JOIN 
      (SELECT 
        MAX(tb.D_REPORTDATE) AS D_REPORTDATE,      
        tb.S_TRECODE,
        tb.S_ACCTCODE,
        MAX(tb.D_ACCTDATE) AS D_ACCTDATE
      FROM
        edw.trs_d003_tr_stock tb
      WHERE tb.D_REPORTDATE BETWEEN DATE_SUB(DATE_FORMAT(s_date,'%Y-%m-01'), INTERVAL 1 YEAR) AND DATE_SUB(s_date, INTERVAL 1 YEAR)
      GROUP BY tb.S_TRECODE,
        tb.S_ACCTCODE
        )c
         ON a.D_REPORTDATE = c.D_REPORTDATE
        AND a.S_TRECODE = c.S_TRECODE
        AND a.S_ACCTCODE = c.S_ACCTCODE
        AND a.D_ACCTDATE = c.D_ACCTDATE
      LEFT JOIN 
        (SELECT DISTINCT 
          t.GUOKU_ID AS GUOKU_ID,
          t.ACOUNT_CODE AS ACOUNT_CODE,
          t.ACOUNT_SUBJECT AS ACOUNT_SUBJECT 
        FROM
          edw.cm_guoku_trecode_account t) b 
        ON a.S_ACCTCODE = b.ACOUNT_CODE 
        AND a.S_TRECODE = b.GUOKU_ID 
    ) bb 
    ON  aa.D_REPORTDATE = DATE_ADD(bb.D_REPORTDATE,INTERVAL 1 YEAR)
    AND aa.S_TRECODE = bb.S_TRECODE 
    AND aa.S_ACCTCODE = bb.S_ACCTCODE 
    AND aa.S_ACCTNAME = bb.S_ACCTNAME 
    AND aa.D_ACCTDATE = bb.D_ACCTDATE 
    AND aa.SUB_ACCTCODE = bb.SUB_ACCTCODE 
  LEFT JOIN edw.`cm_guoku_dimnsn` dt1 
    ON aa.S_TRECODE = dt1.GUOKU_ID
    ;
 
  CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y-%m-%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop8
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop8`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop8`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  s_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop8.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  -- SET s_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
	  SET V_STEP_ID =1;
 -- DELETE FROM ADM.TRS_BUDGET_FUNCTION_INCOME_DAILY WHERE D_REPORTDATE = DATE_FORMAT(s_date,'%Y-%m');
	  SET V_STEP_ID =2;
-- 2018年3月30日之后（含30日）
INSERT INTO ADM.TRS_BUDGET_FUNCTION_INCOME_DAILY
## 功能分类预算收入-日
## DROP TABLE ADM.trs_budget_function_income_daily
## CREATE TABLE adm.trs_budget_function_income_daily AS
SELECT
 DATE_FORMAT(aa.D_REPORTDATE,'%Y-%m-%d') AS D_REPORTDATE,
 aa.S_TRECODE AS S_TRECODE,
 aa.C_BUDGETLEVEL AS C_BUDGETLEVEL,
 dt1.SUBJECT_CODE_4 AS SUBJECT_CODE_4,
 dt1.SUBJECT_DSCR_4 AS SUBJECT_DSCR_4,
 dt1.FUN_CLASS_CODE_1 AS FUN_CLASS_CODE_1,
 dt1.FUN_CLASS_DSCR_1 AS FUN_CLASS_DSCR_1,
 dt1.FUN_CLASS_CODE_2 AS FUN_CLASS_CODE_2,
 dt1.FUN_CLASS_DSCR_2 AS FUN_CLASS_DSCR_2,
 dt1.FUN_CLASS_CODE_3 AS FUN_CLASS_CODE_3,
 dt1.FUN_CLASS_DSCR_3 AS FUN_CLASS_DSCR_3,
 aa.F_DAYAMT AS THIS_PERIOD_AMT,
 bb.F_DAYAMT AS LAST_PERIOD_AMT,
 aa.F_YEARAMT AS THIS_PERIOD_YEARAMT,
 bb.F_YEARAMT AS LAST_PERIOD_YEARAMT,
 CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
    ## -- 本期预算收入
 SELECT 
D_REPORTDATE,
'2200000000' AS S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME,
SUM(F_DAYAMT) AS F_DAYAMT,
SUM(F_YEARAMT) AS F_YEARAMT FROM 
(SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  SUM(F_DAYAMT) AS F_DAYAMT,
  SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = s_date 
  AND C_BUDGETTYPE = '1' 
  AND S_TAXORGCODE = '000000000000' 
  AND S_TRECODE='2200000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME 
UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = s_date 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  
  UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = s_date 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND   C_BUDGETLEVEL='4'
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  
    UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = s_date 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND   C_BUDGETLEVEL='5'
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  ) a 
  GROUP BY D_REPORTDATE,
 S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME
	UNION ALL
   ## -- 本期调拨收入（转移性收入）
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = s_date
	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
) aa
LEFT JOIN
## --去年同期
(
    ## -- 本期预算收入
 SELECT 
D_REPORTDATE,
'2200000000' AS S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME,
SUM(F_DAYAMT) AS F_DAYAMT,
SUM(F_YEARAMT) AS F_YEARAMT FROM 
(SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  SUM(F_DAYAMT) AS F_DAYAMT,
  SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR) 
  AND C_BUDGETTYPE = '1' 
  AND S_TAXORGCODE = '000000000000' 
  AND S_TRECODE='2200000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME 
UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR) 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  
  UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR) 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND   C_BUDGETLEVEL='4'
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  
    UNION ALL 
SELECT 
  D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME,
  - 1 * SUM(F_DAYAMT) AS F_DAYAMT,
  - 1 * SUM(F_YEARAMT) AS F_YEARAMT 
FROM
  edw.trs_d003_tr_budget_income 
WHERE D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR) 
  AND S_TRECODE <> '2200000000'
  AND    C_BUDGETTYPE = '1' 
  AND   C_BUDGETLEVEL='5'
  AND S_TAXORGCODE <>  '000000000000'
GROUP BY D_REPORTDATE,
  C_BUDGETLEVEL,
  S_BUDGETSUBJECTCODE,
  S_BUDGETSUBJECTNAME
  ) a 
  GROUP BY D_REPORTDATE,
 S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME 
	UNION ALL
   ## -- 调拨收入（转移性收入）
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
) bb
ON  aa.D_REPORTDATE = DATE_ADD(bb.D_REPORTDATE,INTERVAL 1 YEAR)
AND aa.S_TRECODE = bb.S_TRECODE
AND aa.C_BUDGETLEVEL = bb.C_BUDGETLEVEL
AND aa.S_BUDGETSUBJECTCODE = bb.S_BUDGETSUBJECTCODE
JOIN
(
SELECT
a.`FUN_CLASS_CODE_1` AS FUN_CLASS_CODE_1,
a.`FUN_CLASS_DSCR_1` AS FUN_CLASS_DSCR_1,
a.`FUN_CLASS_CODE_2` AS FUN_CLASS_CODE_2,
a.`FUN_CLASS_DSCR_2` AS FUN_CLASS_DSCR_2,
a.`FUN_CLASS_CODE_3` AS FUN_CLASS_CODE_3,
a.`FUN_CLASS_DSCR_3` AS FUN_CLASS_DSCR_3,
b.`SUBJECT_CODE_4` AS SUBJECT_CODE_4,
b.`SUBJECT_DSCR_4` AS SUBJECT_DSCR_4
FROM
edw.`cm_guoku_functional_type` a
LEFT JOIN
-- edw.`cm_guoku_rcpt_dsb_fuc` b
-- ON  a.`FUN_CLASS_CODE_3` = b.`FUN_CLASS_CODE_3`
edw.`cm_guoku_rcpt_dsb` b
ON  a.`FUN_CLASS_CODE_3` = b.`T_CLASS_CODE_3`
WHERE
-- b.`OF_YEAR` = YEAR(s_date) AND 
a.FUN_CLASS_CODE_1 = 'T01'
) dt1
ON aa.S_BUDGETSUBJECTCODE = dt1.SUBJECT_CODE_4;
 
  CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y-%m-%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop9
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop9`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop9`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  s_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop9.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  -- SET s_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
	  SET V_STEP_ID =1;
 DELETE FROM ADM.TRS_BUDGET_FUNCTION_INCOME_DAILY WHERE D_REPORTDATE = DATE_FORMAT(s_date,'%Y-%m-%d');
	  SET V_STEP_ID =2;
-- 2018年3月30日之后（含30日）
INSERT INTO ADM.TRS_BUDGET_FUNCTION_INCOME_DAILY
## 功能分类预算收入-日
## DROP TABLE ADM.trs_budget_function_income_daily
## CREATE TABLE adm.trs_budget_function_income_daily AS
SELECT
 DATE_FORMAT(aa.D_REPORTDATE,'%Y-%m-%d') AS D_REPORTDATE,
 aa.S_TRECODE AS S_TRECODE,
 aa.C_BUDGETLEVEL AS C_BUDGETLEVEL,
 dt1.SUBJECT_CODE_4 AS SUBJECT_CODE_4,
 dt1.SUBJECT_DSCR_4 AS SUBJECT_DSCR_4,
 dt1.FUN_CLASS_CODE_1 AS FUN_CLASS_CODE_1,
 dt1.FUN_CLASS_DSCR_1 AS FUN_CLASS_DSCR_1,
 dt1.FUN_CLASS_CODE_2 AS FUN_CLASS_CODE_2,
 dt1.FUN_CLASS_DSCR_2 AS FUN_CLASS_DSCR_2,
 dt1.FUN_CLASS_CODE_3 AS FUN_CLASS_CODE_3,
 dt1.FUN_CLASS_DSCR_3 AS FUN_CLASS_DSCR_3,
 aa.F_DAYAMT AS THIS_PERIOD_AMT,
 bb.F_DAYAMT AS LAST_PERIOD_AMT,
 aa.F_YEARAMT AS THIS_PERIOD_YEARAMT,
 bb.F_YEARAMT AS LAST_PERIOD_YEARAMT,
 CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
    ## -- 本期预算收入
    
SELECT 
D_REPORTDATE,
S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME,
SUM(F_DAYAMT) AS  F_DAYAMT,
SUM(F_YEARAMT)  AS F_YEARAMT
FROM 
edw.`trs_d003_tr_budget_income`
WHERE S_TAXORGCODE = 'XXXXXXXXXXXX'
AND D_REPORTDATE = s_date
AND S_TRECODE = '2200000000'
AND C_BUDGETTYPE = '1'
AND C_BUDGETLEVEL = '2'
GROUP BY 
D_REPORTDATE,
S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME
	UNION ALL
   ## -- 本期调拨收入（转移性收入）
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = s_date
	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
) aa
LEFT JOIN
## --去年同期
(
    ## -- 本期预算收入
 SELECT 
D_REPORTDATE,
S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME,
SUM(F_DAYAMT) AS  F_DAYAMT,
SUM(F_YEARAMT)  AS F_YEARAMT
FROM 
edw.`trs_d003_tr_budget_income`
WHERE S_TAXORGCODE = 'XXXXXXXXXXXX'
AND  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
AND S_TRECODE = '2200000000'
AND C_BUDGETTYPE = '1'
AND C_BUDGETLEVEL = '2'
GROUP BY 
D_REPORTDATE,
S_TRECODE,
C_BUDGETLEVEL,
S_BUDGETSUBJECTCODE,
S_BUDGETSUBJECTNAME
	UNION ALL
   ## -- 本期调拨收入（转移性收入）
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = DATE_SUB(s_date,INTERVAL 1 YEAR)
	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
) bb
ON  aa.D_REPORTDATE = DATE_ADD(bb.D_REPORTDATE,INTERVAL 1 YEAR)
AND aa.S_TRECODE = bb.S_TRECODE
AND aa.C_BUDGETLEVEL = bb.C_BUDGETLEVEL
AND aa.S_BUDGETSUBJECTCODE = bb.S_BUDGETSUBJECTCODE
JOIN
(
SELECT
a.`FUN_CLASS_CODE_1` AS FUN_CLASS_CODE_1,
a.`FUN_CLASS_DSCR_1` AS FUN_CLASS_DSCR_1,
a.`FUN_CLASS_CODE_2` AS FUN_CLASS_CODE_2,
a.`FUN_CLASS_DSCR_2` AS FUN_CLASS_DSCR_2,
a.`FUN_CLASS_CODE_3` AS FUN_CLASS_CODE_3,
a.`FUN_CLASS_DSCR_3` AS FUN_CLASS_DSCR_3,
b.`SUBJECT_CODE_4` AS SUBJECT_CODE_4,
b.`SUBJECT_DSCR_4` AS SUBJECT_DSCR_4
FROM
edw.`cm_guoku_functional_type` a
LEFT JOIN
-- edw.`cm_guoku_rcpt_dsb_fuc` b
-- ON  a.`FUN_CLASS_CODE_3` = b.`FUN_CLASS_CODE_3`
edw.`cm_guoku_rcpt_dsb` b
ON  a.`FUN_CLASS_CODE_3` = b.`T_CLASS_CODE_3`
WHERE
-- b.`OF_YEAR` = YEAR(s_date) AND 
a.FUN_CLASS_CODE_1 = 'T01'
) dt1
ON aa.S_BUDGETSUBJECTCODE = dt1.SUBJECT_CODE_4;
 
  CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y-%m-%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop_income_all
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop_income_all`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop_income_all`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop_income_all.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE V_SQL_INSERT    LONGTEXT        DEFAULT ''; -- 插数语句SQL
  DECLARE V_SQLTXT        LONGTEXT        DEFAULT ''; -- 执行SQL
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
  
  SELECT s_date;
## 功能分类预算收入-日
## DROP TABLE ADM.trs_budget_function_income_daily
## CREATE TABLE adm.trs_budget_function_income_daily AS
DELETE FROM adm.trs_budget_function_income_daily WHERE D_REPORTDATE = s_date;
INSERT INTO adm.trs_budget_function_income_daily
SELECT
 DATE_FORMAT(aa.D_REPORTDATE,'%Y-%m-%d') AS D_REPORTDATE,
 aa.S_TRECODE AS S_TRECODE,
 aa.C_BUDGETLEVEL AS C_BUDGETLEVEL,
 dt1.SUBJECT_CODE_4 AS SUBJECT_CODE_4,
 dt1.SUBJECT_DSCR_4 AS SUBJECT_DSCR_4,
 dt1.FUN_CLASS_CODE_1 AS FUN_CLASS_CODE_1,
 dt1.FUN_CLASS_DSCR_1 AS FUN_CLASS_DSCR_1,
 dt1.FUN_CLASS_CODE_2 AS FUN_CLASS_CODE_2,
 dt1.FUN_CLASS_DSCR_2 AS FUN_CLASS_DSCR_2,
 dt1.FUN_CLASS_CODE_3 AS FUN_CLASS_CODE_3,
 dt1.FUN_CLASS_DSCR_3 AS FUN_CLASS_DSCR_3,
 aa.F_DAYAMT AS THIS_PERIOD_AMT,
 0 AS LAST_PERIOD_AMT,
 aa.F_YEARAMT AS THIS_PERIOD_YEARAMT,
 0 AS LAST_PERIOD_YEARAMT,
 CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(
  ## -- 本期预算收入 除重庆分出外其他国库的本级
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = s_date
	AND S_TAXORGCODE NOT IN('000000000000','XXXXXXXXXXXX') 
	AND S_TRECODE <> '2200000000'
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
	
	UNION ALL
	-- 重庆分库的本级
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_budget_income t1
	WHERE  D_REPORTDATE = s_date
	AND S_TAXORGCODE  IN('XXXXXXXXXXXX') 
	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
	
	UNION ALL
   ## -- 本期调拨收入（转移性收入）
	SELECT 
	 t1.D_REPORTDATE AS D_REPORTDATE,
	 t1.S_TRECODE AS S_TRECODE,
	 t1.C_BUDGETLEVEL AS C_BUDGETLEVEL,
	 t1.S_BUDGETSUBJECTCODE AS S_BUDGETSUBJECTCODE,
	 t1.S_BUDGETSUBJECTNAME AS S_BUDGETSUBJECTNAME,
	 SUM(t1.F_DAYAMT) AS F_DAYAMT,
	 SUM(t1.F_YEARAMT) AS F_YEARAMT
	FROM edw.trs_d003_tr_move_income t1
	WHERE  D_REPORTDATE = s_date
-- 	AND S_TAXORGCODE NOT IN('000000000000','XXXXXXXXXXXX') 
-- 	AND S_TRECODE = '2200000000'
	GROUP BY
	t1.D_REPORTDATE,
	t1.S_TRECODE,
	t1.C_BUDGETLEVEL,
	t1.S_BUDGETSUBJECTCODE,
	t1.S_BUDGETSUBJECTNAME
) aa
JOIN
(
SELECT
a.`FUN_CLASS_CODE_1` AS FUN_CLASS_CODE_1,
a.`FUN_CLASS_DSCR_1` AS FUN_CLASS_DSCR_1,
a.`FUN_CLASS_CODE_2` AS FUN_CLASS_CODE_2,
a.`FUN_CLASS_DSCR_2` AS FUN_CLASS_DSCR_2,
a.`FUN_CLASS_CODE_3` AS FUN_CLASS_CODE_3,
a.`FUN_CLASS_DSCR_3` AS FUN_CLASS_DSCR_3,
b.`SUBJECT_CODE_4` AS SUBJECT_CODE_4,
b.`SUBJECT_DSCR_4` AS SUBJECT_DSCR_4
FROM
edw.`cm_guoku_functional_type` a
LEFT JOIN
edw.`cm_guoku_rcpt_dsb` b
ON  a.`FUN_CLASS_CODE_3` = b.`T_CLASS_CODE_3`
WHERE
-- b.`OF_YEAR` = YEAR(s_date)
 a.FUN_CLASS_CODE_1 = 'T01'
) dt1
ON aa.S_BUDGETSUBJECTCODE = dt1.SUBJECT_CODE_4
  
  
 
  
  
 ;
  
 
 CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_loop_stock
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_loop_stock`;
delimiter ;;
CREATE DEFINER=`root`@`%` PROCEDURE `test_loop_stock`(IN s_date DATE,IN edate DATE)
BEGIN
  -- DECLARE  data_date DATE ;  -- 数据日期
  DECLARE V_START_TIME    CHAR(19)      DEFAULT NOW();
  DECLARE V_PROC_NAME     VARCHAR(80)   DEFAULT 'ADM.test_loop_stock.PRC';
  DECLARE V_STEP_ID       INT           DEFAULT 0;
  DECLARE V_SQL_INSERT    LONGTEXT        DEFAULT ''; -- 插数语句SQL
  DECLARE V_SQLTXT        LONGTEXT        DEFAULT ''; -- 执行SQL
  -- SET data_date =  '2018-01-01';
  WHILE s_date <= edate
  DO
	  SET V_STEP_ID =1;
	  DELETE FROM  adm.trs_stock_change_daily WHERE  D_REPORTDATE=s_date;  
	  SET V_STEP_ID =2;
	## 库存变动情况-日
## drop table ADM.TRS_STOCK_CHANGE_DAILY
## CREATE TABLE adm.trs_stock_change_daily AS
##
 insert into adm.trs_stock_change_daily
 (
D_REPORTDATE,
S_TRECODE,
GUOKU_DSCR,
S_ACCTCODE,
S_ACCTNAME,
D_ACCTDATE,
SUB_ACCTCODE,
LEVEL,
THIS_PERIOD_AMT,
LAST_PERIOD_AMT,
UPDATE_DATE 
 )
SELECT
  aa.D_REPORTDATE AS D_REPORTDATE,
  aa.S_TRECODE AS S_TRECODE,
  dt1.GUOKU_DSCR AS GUOKU_DSCR,
  aa.S_ACCTCODE AS S_ACCTCODE,
  aa.S_ACCTNAME AS S_ACCTNAME,
  aa.D_ACCTDATE AS D_ACCTDATE,
  aa.SUB_ACCTCODE AS SUB_ACCTCODE,
  dt1.`LEVEL` AS LEVEL,
  aa.F_TODAYBALANCE AS THIS_PERIOD_AMT,
  bb.F_TODAYBALANCE AS LAST_PERIOD_AMT,
  CURRENT_TIMESTAMP AS UPDATE_DATE
FROM
(

	SELECT
	  a.D_REPORTDATE AS D_REPORTDATE,
	  a.S_TRECODE AS S_TRECODE,
	  a.S_ACCTCODE AS S_ACCTCODE,
	  a.S_ACCTNAME AS S_ACCTNAME,
	  a.D_ACCTDATE AS D_ACCTDATE,
	  b.ACOUNT_SUBJECT AS SUB_ACCTCODE,
	  a.F_TODAYBALANCE AS F_TODAYBALANCE
	FROM
	  edw.`trs_d003_tr_stock` a
	LEFT JOIN 
	  (
		SELECT DISTINCT
		t.GUOKU_ID AS GUOKU_ID,
		t.ACOUNT_CODE AS ACOUNT_CODE,
		t.ACOUNT_SUBJECT AS ACOUNT_SUBJECT
		FROM
		edw.cm_guoku_trecode_account t
	  ) b
	ON a.S_ACCTCODE = b.ACOUNT_CODE
	AND a.S_TRECODE = b.GUOKU_ID
	WHERE 
	  a.D_REPORTDATE = s_date
) aa
LEFT JOIN
(
	SELECT
	  a.D_REPORTDATE AS D_REPORTDATE,
	  a.S_TRECODE AS S_TRECODE,
	  a.S_ACCTCODE AS S_ACCTCODE,
	  a.S_ACCTNAME AS S_ACCTNAME,
	  a.D_ACCTDATE AS D_ACCTDATE,
	  b.ACOUNT_SUBJECT AS SUB_ACCTCODE,
	  a.F_TODAYBALANCE AS F_TODAYBALANCE
	FROM
	  edw.`trs_d003_tr_stock` a
	LEFT JOIN 
	  (
		SELECT DISTINCT
		t.GUOKU_ID AS GUOKU_ID,
		t.ACOUNT_CODE AS ACOUNT_CODE,
		t.ACOUNT_SUBJECT AS ACOUNT_SUBJECT
		FROM
		edw.cm_guoku_trecode_account t
	  ) b
	ON a.S_ACCTCODE = b.ACOUNT_CODE
	AND a.S_TRECODE = b.GUOKU_ID
	WHERE 
	  a.D_REPORTDATE = DATE_SUB(s_date, INTERVAL 1 YEAR)
) bb
ON  bb.D_REPORTDATE = DATE_SUB((aa.D_REPORTDATE),INTERVAL 1 YEAR)
AND aa.S_TRECODE = bb.S_TRECODE
AND aa.S_ACCTCODE = bb.S_ACCTCODE
AND aa.S_ACCTNAME = bb.S_ACCTNAME
-- AND aa.D_ACCTDATE = bb.D_ACCTDATE
AND bb.D_REPORTDATE = DATE_SUB((aa.D_ACCTDATE),INTERVAL 1 YEAR)
AND aa.SUB_ACCTCODE = bb.SUB_ACCTCODE
LEFT JOIN
edw.`cm_guoku_dimnsn_fact` dt1
ON aa.S_TRECODE = dt1.GUOKU_ID

;
 
 
 CALL ETL.EDW_PROC_TRACE_LOG(DATE_FORMAT(s_date,'%Y%m%d'),V_START_TIME,NOW(),V_PROC_NAME,V_STEP_ID,ROW_COUNT());
 
 
 
  -- SET  s_date = DATE_FORMAT(s_date,'%Y-%m-01');
  SET s_date = DATE_ADD(s_date,INTERVAL 1 DAY);
  COMMIT;
  END WHILE;
END
;;
delimiter ;

